/* 本番と同じ GAS のプログラム（Code.gs・Reception.gs・Progress.gs）。練習版はこれをブラウザの中で動かす */
window.IW_GAS_SRC = "/* ============================================================\n   第40回岩手県中学校インドアソフトテニス大会 システム\n   バックエンドGAS（申込系） v1\n   - スプレッドシートにバインドして使う（拡張機能 → Apps Script）\n   - 規約：ES5（var / function のみ）\n   ============================================================ */\n\nvar SHEET_CONFIG = '設定';\nvar SHEET_MASTER = '加盟チーム';\nvar SHEET_ENTRY = '出場枠';\nvar SHEET_PAIR = '個人ペア';\nvar SHEET_LOG = 'ログ';\nvar SHEET_CHANGE = '選手変更';\nvar SHEET_DRAW = '組合せ';\nvar SHEET_MATCH = '試合';\nvar SHEET_RANK = '予選順位';\nvar SHEET_REQ = '変更申請';\nvar SHEET_OFFICIAL = 'プログラム_役員';\nvar SHEET_HISTORY = 'プログラム_栄光の記録';\n\nvar HEADERS = {};\nHEADERS[SHEET_MASTER] = ['チーム名', '種別', '地区', '代表者名', '代表者メール', '登録料入金', '選手JSON'];\nHEADERS[SHEET_ENTRY] = ['entryId', '区分', 'チーム名', '地区', '代表者名', '代表者メール', 'トークン', '受付コード',\n  '状態', '申込日時', '更新日時', '監督氏名', '監督役職', '申込者氏名', '申込者役職', '申込者電話', '申込者メール',\n  '選手JSON', 'ペア数', '参加料', '要確認', 'リンク送信日時', '受付状態', '受付日時', '備考', '略称', '初回アクセス日時', '督促送信日時',\n  '受付担当', '受付メール送信日時', '領収書番号', '領収書ファイルID', '領収書作成日時', '公開同意日時'];\nHEADERS[SHEET_PAIR] = ['pairId', '区分', 'A氏名', 'A学年', 'A所属', 'B氏名', 'B学年', 'B所属', '支払チーム', '監督氏名', '監督役職', '変更記録', '申込時変更'];\nHEADERS[SHEET_LOG] = ['日時', '種別', '内容'];\nHEADERS[SHEET_CHANGE] = ['日時', '区分', 'チーム', '対象', '変更前', '変更後', '名簿外', '理由', '理由公開'];\nHEADERS[SHEET_DRAW] = ['区分', '枠', '対象ID'];\nHEADERS[SHEET_MATCH] = ['matchId', '区分', '段階', 'ラウンド', '番号', '左', '右', 'コート', '順番', '2面', '状態', '開始', '終了', '勝者', 'スコア', '備考', '更新日時', 'オーダー左', 'オーダー右', '番手', '判定', 'オーダー公開'];\nHEADERS[SHEET_RANK] = ['区分', 'ブロック', '1位', '2位', '更新日時', '3位', '得失表示', '得失値'];\nHEADERS[SHEET_REQ] = ['申請ID', '日時', '区分', 'entryId', 'チーム', '種別', '対象', '内容', '理由', '状態', '処理日時', 'コメント', '申請者'];\nHEADERS[SHEET_OFFICIAL] = ['区分', '役職', '氏名', '所属'];\nHEADERS[SHEET_HISTORY] = ['回', '年度', '種別', '優勝', '準優勝', '3位', '3位（2）'];\n\nvar CONFIG_DEFAULTS = [\n  ['大会名', '第40回岩手県中学校インドアソフトテニス大会'],\n  ['申込開始', '2026-11-04 09:00'],\n  ['申込締切', '2026-11-19 17:00'],\n  ['サイトURL', 'https://skkr-d.github.io/iwate-indoor/'],\n  ['管理パスワード', 'iwatestc2030'],\n  ['登録システムGAS_URL', 'https://script.google.com/macros/s/AKfycbwMaX6mOexotFkV6n5Y79QXO9IhDgBRvT4PHuCr9c9j435683_N7G8yKkQPcIi-wXtu/exec'],\n  ['団体戦参加料', '10000'],\n  ['個人戦参加料', '3000'],\n  ['団体戦上限', '16'],\n  ['個人戦上限', '16'],\n  ['個人戦日程', '令和8年11月28日（土）'],\n  ['団体戦日程', '令和8年11月29日（日）'],\n  ['男子会場', '雫石町営体育館'],\n  ['女子会場', '紫波町総合体育館'],\n  ['開場時刻', '7:30'],\n  ['受付時刻', '7:35〜8:00'],\n  ['略称最大文字数', '6'],\n  ['受付パスワード', 'indoor40'],\n  ['本部パスワード', 'honbu40'],\n  ['組合せパスワード', ''],\n  ['変更申請の通知先', ''],\n  ['領収書発行者', '岩手県中学生ソフトテニス連盟'],\n  ['領収書代表者', '会長　佐々木　義孝'],\n  ['角印画像ファイルID', ''],\n  ['個人戦名簿PDF', '01_個人戦出場ペア名簿.pdf'],\n  ['団体戦名簿PDF', '02_団体戦出場チーム一覧.pdf'],\n  ['競技開始時刻', '9:00'],\n  ['5ゲーム目安（分）', '20'],\n  ['7ゲーム目安（分）', '30'],\n  ['団体戦の次戦までの間隔（分）', '15'],\n  ['個人戦の次戦までの間隔（分）', '0'],\n  ['1回戦オーダー締切', '8:40'],\n  ['オーダー提出（分）', '10'],\n  ['コート集合（分）', '15'],\n  ['署名', '岩手県中学生ソフトテニス連盟\\n競技委員長　坂倉　大\\n携帯：090-7072-2035（18〜20時）\\nE-mail：iwatestc2030@gmail.com']\n];\n\n/* 区分定義 */\nvar DIVISIONS = {\n  MT: { code: 'MT', name: '男子団体戦', gender: '男', type: 'team' },\n  WT: { code: 'WT', name: '女子団体戦', gender: '女', type: 'team' },\n  MI: { code: 'MI', name: '男子個人戦', gender: '男', type: 'indiv' },\n  WI: { code: 'WI', name: '女子個人戦', gender: '女', type: 'indiv' }\n};\nvar DIV_ORDER = ['MI', 'WI', 'MT', 'WT'];\n\n/* ============================================================\n   初期セットアップ（最初に1回だけ手動実行）\n   ============================================================ */\nfunction setup() {\n  var ss = ss_();\n  var names = [SHEET_CONFIG, SHEET_MASTER, SHEET_ENTRY, SHEET_PAIR, SHEET_LOG, SHEET_CHANGE, SHEET_DRAW, SHEET_MATCH, SHEET_RANK, SHEET_REQ, SHEET_OFFICIAL, SHEET_HISTORY];\n  var i, sh;\n  for (i = 0; i < names.length; i++) {\n    sh = ss.getSheetByName(names[i]);\n    if (!sh) sh = ss.insertSheet(names[i]);\n    /* 日付・スコアの自動変換を防ぐため全セルを書式なしテキストに */\n    sh.getRange(1, 1, sh.getMaxRows(), sh.getMaxColumns()).setNumberFormat('@');\n    if (names[i] === SHEET_CONFIG) {\n      setupConfig_(sh);\n    } else {\n      ensureHeaders_(sh, HEADERS[names[i]]);\n    }\n    sh.setFrozenRows(1);\n  }\n  var def = ss.getSheetByName('シート1');\n  if (def && def.getLastRow() === 0 && ss.getSheets().length > 1) ss.deleteSheet(def);\n  log_('setup', 'シートを初期化しました');\n}\n\nfunction setupConfig_(sh) {\n  if (sh.getLastRow() === 0) sh.appendRow(['項目', '値']);\n  var values = sh.getDataRange().getValues();\n  var have = {};\n  var i;\n  for (i = 1; i < values.length; i++) have[String(values[i][0])] = true;\n  for (i = 0; i < CONFIG_DEFAULTS.length; i++) {\n    if (!have[CONFIG_DEFAULTS[i][0]]) sh.appendRow(CONFIG_DEFAULTS[i]);\n  }\n}\n\n/* 既存ヘッダーは書き換えず、足りない列だけ末尾に追加する */\nfunction ensureHeaders_(sh, headers) {\n  if (sh.getLastRow() === 0) {\n    sh.getRange(1, 1, 1, headers.length).setValues([headers]).setFontWeight('bold');\n    return;\n  }\n  var current = sh.getRange(1, 1, 1, sh.getLastColumn()).getValues()[0];\n  var i;\n  for (i = 0; i < headers.length; i++) {\n    if (current.indexOf(headers[i]) < 0) {\n      sh.getRange(1, sh.getLastColumn() + 1).setValue(headers[i]).setFontWeight('bold');\n    }\n  }\n}\n\n/* ============================================================\n   ルーティング\n   ============================================================ */\nfunction doGet(e) {\n  var p = (e && e.parameter) || {};\n  try {\n    switch (p.action) {\n      case 'getEntry': return json_(apiGetEntry_(p.t));\n      case 'progress': return json_(progressData_(p.div, false));\n      case 'portal': return json_(portalData_(p.t));\n      case 'getTicket': return json_(apiGetTicket_(p.t));\n      case 'changeInfo': return json_(changeInfo_(p.t));\n      case 'changes': return json_({ status: 'ok', changes: publicChanges_(p.div), divisions: DIVISIONS, divOrder: DIV_ORDER, tournament: getConfig_()['大会名'] });\n      case 'programData': return json_(programData_());\n      case 'ping': return json_({ status: 'ok', time: now_() });\n      default: return json_({ status: 'error', message: '不明なアクション: ' + p.action });\n    }\n  } catch (err) {\n    return json_({ status: 'error', message: err.message });\n  }\n}\n\nfunction doPost(e) {\n  var body;\n  try {\n    body = JSON.parse(e.postData.contents);\n  } catch (err) {\n    return json_({ status: 'error', message: '送信データを読み取れません: ' + err.message });\n  }\n  try {\n    switch (body.action) {\n      case 'submitEntry': return json_(apiSubmitEntry_(body));\n      case 'getPdf': return json_(apiGetPdf_(body));\n      case 'recLogin':\n      case 'recList':\n      case 'recLookup':\n      case 'recConfirm':\n      case 'recCancel': return json_(receptionRoute_(body));\n      case 'ctlLoad':\n      case 'ctlUpdate':\n      case 'ctlRanks':\n      case 'ctlDiff':\n      case 'ctlConfig':\n      case 'ctlOrder':\n      case 'ctlPairs': return json_(controlRoute_(body));\n      case 'submitOrder': return json_(apiSubmitOrder_(body));\n      case 'changeRequest': return json_(apiChangeRequest_(body));\n      default:\n        if (String(body.action || '').indexOf('admin') === 0) return json_(adminRoute_(body));\n        return json_({ status: 'error', message: '不明なアクション: ' + body.action });\n    }\n  } catch (err) {\n    log_('error', body.action + ': ' + err.message);\n    return json_({ status: 'error', message: err.message });\n  }\n}\n\n/* ============================================================\n   公開API：申込画面\n   ============================================================ */\nfunction apiGetEntry_(token) {\n  var entry = findEntryByToken_(token);\n  if (!entry) return { status: 'error', code: 'invalid', message: '申込リンクが無効です。メールのリンクを確認するか、連盟までお問い合わせください。' };\n  if (!entry['初回アクセス日時']) recordFirstAccess_(token);\n  var cfg = getConfig_();\n  var div = DIVISIONS[entry['区分']];\n  var res = {\n    status: 'ok',\n    tournament: cfg['大会名'],\n    division: div,\n    teamName: entry['チーム名'],\n    district: districtName_(entry['地区']),\n    state: entry['状態'] || '未申込',\n    period: periodInfo_(cfg),\n    date: div.type === 'team' ? cfg['団体戦日程'] : cfg['個人戦日程'],\n    venue: div.gender === '男' ? cfg['男子会場'] : cfg['女子会場'],\n    abbr: entry['略称'] || '',\n    abbrSuggest: suggestAbbr_(entry['チーム名']),\n    abbrMax: toInt_(cfg['略称最大文字数']) || 6,\n    fee: 0,\n    saved: null\n  };\n  if (entry['状態'] === '申込済') {\n    res.saved = {\n      abbr: entry['略称'] || '',\n      coachName: entry['監督氏名'], coachTitle: entry['監督役職'],\n      applicantName: entry['申込者氏名'], applicantTitle: entry['申込者役職'],\n      applicantPhone: entry['申込者電話'], applicantEmail: entry['申込者メール'],\n      players: parseJson_(entry['選手JSON'], []),\n      consentAt: entry['公開同意日時'] || '',\n      updatedAt: entry['更新日時'] || entry['申込日時']\n    };\n  }\n  if (div.type === 'team') {\n    res.fee = toInt_(cfg['団体戦参加料']);\n    res.roster = rosterFor_(entry['チーム名'], div.gender);\n  } else {\n    var pairs = pairsForEntry_(entry);\n    res.pairs = pairs;\n    /* 申込時の選手変更（競技委員会承認）があるペアは、交代する側のチームの名簿を渡す */\n    res.preRosters = {};\n    var pi;\n    for (pi = 0; pi < pairs.length; pi++) {\n      if (!pairs[pi].preChange) continue;\n      var pteam = pairs[pi].preChange.side === 'B' ? pairs[pi].bTeam : pairs[pi].aTeam;\n      if (!res.preRosters[pteam]) res.preRosters[pteam] = rosterFor_(pteam, div.gender);\n    }\n    res.fee = toInt_(cfg['個人戦参加料']) * pairs.length;\n    res.feePerPair = toInt_(cfg['個人戦参加料']);\n  }\n  return res;\n}\n\nfunction apiSubmitEntry_(body) {\n  var lock = LockService.getScriptLock();\n  if (!lock.tryLock(20000)) throw new Error('混み合っています。少し待ってからもう一度送信してください。');\n  try {\n    var t = table_(SHEET_ENTRY);\n    var entry = null;\n    var i;\n    for (i = 0; i < t.rows.length; i++) {\n      if (body.t && String(t.rows[i]['トークン']) === String(body.t)) { entry = t.rows[i]; break; }\n    }\n    if (!entry) throw new Error('申込リンクが無効です。');\n    var cfg = getConfig_();\n    var period = periodInfo_(cfg);\n    if (period.state === 'before') throw new Error('申込受付は ' + period.start + ' からです。');\n    if (period.state === 'after') throw new Error('申込期間は ' + period.end + ' で終了しました。変更は連盟へご連絡ください。');\n\n    var d = body.data || {};\n    var div = DIVISIONS[entry['区分']];\n    if (d.consent !== true) throw new Error('「個人情報の取扱い」への同意（選手本人および保護者、監督）のチェックが必要です。');\n    requireText_(d.applicantName, '申込責任者の氏名');\n    requireText_(d.applicantTitle, '申込責任者の役職');\n    requireText_(d.applicantPhone, '申込責任者の携帯番号');\n    if (!/^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$/.test(String(d.applicantEmail || ''))) throw new Error('メールアドレスの形式が正しくありません。');\n    var abbr = String(d.teamAbbr || '').replace(/[\\s　]/g, '');\n    var abbrMax = toInt_(cfg['略称最大文字数']) || 6;\n    if (!abbr) throw new Error('組合せ用の略称を入力してください。');\n    if (abbr.length > abbrMax) throw new Error('略称は' + abbrMax + '文字以内で入力してください。');\n\n    var update = {\n      '略称': abbr,\n      '申込者氏名': d.applicantName, '申込者役職': d.applicantTitle,\n      '申込者電話': String(d.applicantPhone), '申込者メール': d.applicantEmail,\n      '更新日時': now_(),\n      '公開同意日時': now_()\n    };\n    var isNew = entry['状態'] !== '申込済';\n    if (isNew) update['申込日時'] = now_();\n    update['状態'] = '申込済';\n\n    if (div.type === 'team') {\n      requireText_(d.coachName, '監督（ベンチ入り指導者）の氏名');\n      requireText_(d.coachTitle, '監督（ベンチ入り指導者）の役職');\n      var checked = validateTeamPlayers_(d.players, entry['チーム名'], div.gender);\n      update['監督氏名'] = d.coachName;\n      update['監督役職'] = d.coachTitle;\n      update['選手JSON'] = JSON.stringify(checked.players);\n      update['要確認'] = checked.flags.join(' / ');\n      update['参加料'] = String(toInt_(cfg['団体戦参加料']));\n    } else {\n      var pairs = pairsForEntry_(entry);\n      if (pairs.length === 0) throw new Error('このチームの出場ペアが登録されていません。連盟へお問い合わせください。');\n      /* 申込時の選手変更（競技委員会承認）：先にすべて確かめてから、あとで反映する */\n      var preDo = [];\n      var j0, pq, pv, pside, porigin, pcur;\n      for (j0 = 0; j0 < pairs.length; j0++) {\n        pq = pairs[j0];\n        if (!pq.preChange) continue;\n        pv = (d.preChanges || {})[pq.pairId] || {};\n        pside = pq.preChange.side === 'B' ? 'B' : 'A';\n        porigin = pq.change ? pq.change.from : (pside === 'A' ? pq.aName : pq.bName);\n        pcur = pside === 'A' ? pq.aName : pq.bName;\n        requireText_(pv.name, 'ペア「' + pq.aName + '・' + pq.bName + '」で、' + porigin + 'さんに代わる選手の氏名');\n        requireText_(pv.grade, 'ペア「' + pq.aName + '・' + pq.bName + '」で、代わる選手の学年');\n        if (normName_(pv.name) === normName_(porigin)) throw new Error(porigin + 'さんの代わりの選手を選んでください（競技委員会承認の選手変更）。');\n        if (normName_(pv.name) === normName_(pcur) && pq.change) continue;\n        changePairPlayerCore_({ pairId: pq.pairId, side: pside, name: pv.name, grade: pv.grade, dryRun: true });\n        preDo.push({ pairId: pq.pairId, side: pside, name: String(pv.name).trim(), grade: pv.grade, reason: pq.preChange.reason, publicReason: !!pq.preChange.pub });\n      }\n      var coaches = d.pairCoaches || {};\n      var pt = table_(SHEET_PAIR);\n      var j, pr, c;\n      for (j = 0; j < pt.rows.length; j++) {\n        pr = pt.rows[j];\n        c = coaches[pr.pairId];\n        if (!c) continue;\n        if (!isPairOfEntry_(pr, entry)) continue;\n        requireText_(c.name, 'ペア「' + pr['A氏名'] + '・' + pr['B氏名'] + '」の監督氏名');\n        requireText_(c.title, 'ペア「' + pr['A氏名'] + '・' + pr['B氏名'] + '」の監督役職');\n        writeRow_(pt, pr, { '監督氏名': c.name, '監督役職': c.title });\n      }\n      for (j = 0; j < preDo.length; j++) changePairPlayerCore_(preDo[j]);\n      var refreshed = pairsForEntry_(entry);\n      for (j = 0; j < refreshed.length; j++) {\n        if (!refreshed[j].coachName) throw new Error('すべてのペアに監督（ベンチ入り指導者）を入力してください。');\n      }\n      update['ペア数'] = String(refreshed.length);\n      update['参加料'] = String(toInt_(cfg['個人戦参加料']) * refreshed.length);\n      update['選手JSON'] = JSON.stringify(refreshed);\n    }\n    if (!entry['受付コード']) update['受付コード'] = newCode_(10);\n    writeRow_(t, entry, update);\n    var saved = table_(SHEET_ENTRY);\n    var latest = null;\n    for (i = 0; i < saved.rows.length; i++) {\n      if (String(saved.rows[i]['トークン']) === String(body.t)) { latest = saved.rows[i]; break; }\n    }\n    log_(isNew ? '申込' : '修正', div.name + '／' + entry['チーム名']);\n    var mailError = '';\n    try {\n      sendConfirmMail_(latest, cfg, isNew);\n    } catch (mErr) {\n      mailError = mErr.message;\n      log_('mail-error', entry['チーム名'] + ': ' + mErr.message);\n    }\n    return { status: 'ok', isNew: isNew, mailError: mailError };\n  } finally {\n    lock.releaseLock();\n  }\n}\n\n/* 団体戦の選手チェック：最低4名・最大8名、重複不可、名簿外は要確認フラグ */\nfunction validateTeamPlayers_(players, teamName, gender) {\n  if (!players || players.length !== 8) throw new Error('選手データが不正です（8枠分必要）。');\n  var roster = rosterFor_(teamName, gender);\n  var rosterNames = {};\n  var i;\n  for (i = 0; i < roster.length; i++) rosterNames[normName_(roster[i].name)] = roster[i];\n  var out = [];\n  var seen = {};\n  var flags = [];\n  var count = 0;\n  var p, key;\n  for (i = 0; i < 8; i++) {\n    p = players[i] || {};\n    if (p.vacant) {\n      if (i < 4) throw new Error('No.' + (i + 1) + 'は欠員にできません（最低4名）。');\n      out.push({ no: i + 1, vacant: true });\n      continue;\n    }\n    requireText_(p.name, 'No.' + (i + 1) + 'の選手名');\n    requireText_(p.grade, 'No.' + (i + 1) + 'の学年');\n    key = normName_(p.name);\n    if (seen[key]) throw new Error('「' + p.name + '」が重複しています。');\n    seen[key] = true;\n    var offRoster = !rosterNames[key];\n    if (offRoster) flags.push('No.' + (i + 1) + ' ' + p.name + ' は登録名簿にない');\n    out.push({ no: i + 1, name: String(p.name).trim(), grade: p.grade, offRoster: offRoster });\n    count++;\n  }\n  if (count < 4) throw new Error('選手は最低4名必要です。');\n  return { players: out, flags: flags };\n}\n\n/* ============================================================\n   公開API：受付票・HP入口\n   ============================================================ */\nfunction apiGetTicket_(token) {\n  var entry = findEntryByToken_(token);\n  if (!entry) return { status: 'error', message: 'リンクが無効です。' };\n  if (entry['状態'] !== '申込済') return { status: 'error', message: 'まだ申込が完了していません。' };\n  var cfg = getConfig_();\n  var div = DIVISIONS[entry['区分']];\n  return {\n    status: 'ok',\n    tournament: cfg['大会名'],\n    division: div.name,\n    date: div.type === 'team' ? cfg['団体戦日程'] : cfg['個人戦日程'],\n    venue: div.gender === '男' ? cfg['男子会場'] : cfg['女子会場'],\n    openTime: cfg['開場時刻'],\n    receptionTime: cfg['受付時刻'],\n    teamName: entry['チーム名'],\n    fee: toInt_(entry['参加料']),\n    pairCount: toInt_(entry['ペア数']),\n    receptionCode: entry['受付コード'],\n    /* 受付済みなら受付の時刻（例 7:42）。受付票に「✅ 受付済み（7:42）」と出す */\n    reception: entry['受付状態'] === '受付済' ? (String(entry['受付日時'] || '').slice(11, 16).replace(/^0/, '') || '受付済') : '',\n    type: DIVISIONS[entry['区分']].type,\n    divCode: entry['区分'],\n    /* 選手・監督の変更申請ができる期間か（申込締切後〜当日の受付終了）。期間外はボタンを出さない */\n    changeOpen: changePeriod_(cfg, div).open,\n    /* 表彰の対象（第3位・準優勝・優勝）。個人戦はこのチームが申し込んだペアごと */\n    awards: (function () { try { return awardsFor_(entry); } catch (e) { return []; } })()\n  };\n}\n\n/* 申込書PDF（申込者向け：申込リンクのトークンで取得） */\nfunction apiGetPdf_(body) {\n  var entry = findEntryByToken_(body.t);\n  if (!entry) return { status: 'error', message: 'リンクが無効です。' };\n  if (entry['状態'] !== '申込済') return { status: 'error', message: 'まだ申込が完了していません。' };\n  return pdfResponse_(entry);\n}\n\nfunction pdfResponse_(entry) {\n  var blob = buildApplicationPdf_(entry, getConfig_());\n  return { status: 'ok', name: blob.getName(), base64: Utilities.base64Encode(blob.getBytes()) };\n}\n\n/* ============================================================\n   管理API\n   ============================================================ */\nfunction adminRoute_(body) {\n  var cfg = getConfig_();\n  var given = String(body.pw || '');\n  if (given && given === String(cfg['管理パスワード'])) return adminRouteFull_(body, cfg);\n  if (given && String(cfg['組合せパスワード'] || '') && given === String(cfg['組合せパスワード'])) return drawRoute_(body, cfg);\n  return { status: 'error', code: 'auth', message: 'パスワードが違います。' };\n}\n\n/* 組合せ係：組合せの閲覧と保存だけ（公開＝進行表の作成、個人情報、メールは不可） */\nfunction drawRoute_(body, cfg) {\n  switch (body.action) {\n    case 'adminLoad':\n      return { status: 'ok', role: 'draw', config: { '大会名': cfg['大会名'], 'サイトURL': cfg['サイトURL'] }, divisions: DIVISIONS, divOrder: DIV_ORDER };\n    case 'adminDrawLoad': return adminDrawLoad_(body);\n    case 'adminPreview':\n    case 'adminPreviewProgram': return previewRoute_(body);\n    case 'adminDrawSave':\n      var mt = table_(SHEET_MATCH);\n      var i;\n      for (i = 0; i < mt.rows.length; i++) {\n        if (mt.rows[i]['区分'] === body.div) throw new Error('この区分は進行表（公開）が作成済みのため、組合せ係では変更できません。競技委員長へ連絡してください。');\n      }\n      body.by = '組合せ係';\n      return adminDrawSave_(body);\n    default:\n      return { status: 'error', code: 'role', message: '組合せ係のパスワードでは、この操作はできません。' };\n  }\n}\n\nfunction adminRouteFull_(body, cfg) {\n  switch (body.action) {\n    case 'adminLoad': return adminLoad_(cfg);\n    case 'adminRefreshMaster': return adminRefreshMaster_(cfg);\n    case 'adminSetTeams': return adminSetTeams_(body, cfg);\n    case 'adminSavePair': return adminSavePair_(body, cfg);\n    case 'adminDeletePair': return adminDeletePair_(body);\n    case 'adminSendLinks': return adminSendLinks_(body, cfg);\n    case 'adminSendReminders': return adminSendReminders_(body, cfg);\n    case 'adminPdf': return adminPdf_(body);\n    case 'adminListPdf': return adminListPdf_(body, cfg);\n    case 'adminReceiptPdf': return adminReceiptPdf_(body, cfg);\n    case 'adminReceiptBatch': return adminReceiptBatch_(body, cfg);\n    case 'adminReceiptPrint': return adminReceiptPrint_(body, cfg);\n    case 'adminResendReceipt': return adminResendReceipt_(body, cfg);\n    case 'adminChangeTeamPlayer': return adminChangeTeamPlayer_(body);\n    case 'adminChangePairPlayer': return adminChangePairPlayer_(body);\n    case 'adminChangeCoach': return adminChangeCoach_(body);\n    case 'adminSetPreChange': return adminSetPreChange_(body);\n    case 'adminChangeDecide': return adminChangeDecide_(body);\n    case 'adminDrawLoad': return adminDrawLoad_(body);\n    case 'adminDrawSave': return adminDrawSave_(body);\n    case 'adminPreview':\n    case 'adminPreviewProgram': return previewRoute_(body);\n    case 'adminGenerate': return adminGenerate_(body);\n    case 'adminCtlLoad': return progressData_(body.div, true);\n    case 'adminCtlUpdate': return adminCtlUpdate_(body);\n    case 'adminCtlRanks': return adminCtlRanks_(body);\n    case 'adminCtlConfig': return adminCtlConfig_(body);\n    default: return { status: 'error', message: '不明な管理アクション: ' + body.action };\n  }\n}\n\nfunction adminLoad_(cfg) {\n  var m = table_(SHEET_MASTER);\n  var teams = [];\n  var i, r;\n  for (i = 0; i < m.rows.length; i++) {\n    r = m.rows[i];\n    if (!r['チーム名']) continue;\n    teams.push({\n      name: r['チーム名'], category: r['種別'], district: districtName_(r['地区']),\n      repName: r['代表者名'], hasEmail: !!r['代表者メール'], paid: r['登録料入金'] === '済',\n      players: parseJson_(r['選手JSON'], [])\n    });\n  }\n  var e = table_(SHEET_ENTRY);\n  var entries = [];\n  for (i = 0; i < e.rows.length; i++) {\n    r = e.rows[i];\n    entries.push({\n      entryId: r.entryId, div: r['区分'], teamName: r['チーム名'], district: districtName_(r['地区']),\n      repEmail: r['代表者メール'], token: r['トークン'], state: r['状態'] || '未申込',\n      appliedAt: r['申込日時'], updatedAt: r['更新日時'], coachName: r['監督氏名'], coachTitle: r['監督役職'],\n      applicantTitle: r['申込者役職'],\n      applicantName: r['申込者氏名'], applicantPhone: r['申込者電話'], applicantEmail: r['申込者メール'],\n      players: parseJson_(r['選手JSON'], []), pairCount: r['ペア数'], fee: r['参加料'],\n      flag: r['要確認'], linkSentAt: r['リンク送信日時'], reception: r['受付状態'], abbr: r['略称'] || '',\n      firstAccessAt: r['初回アクセス日時'] || '', remindedAt: r['督促送信日時'] || '',\n      receptionAt: r['受付日時'] || '', receptionStaff: r['受付担当'] || '', receptionMailAt: r['受付メール送信日時'] || '',\n      receiptNo: r['領収書番号'] || '', receiptReady: !!(r['領収書ファイルID'] && String(r['領収書作成日時']) >= String(r['更新日時'] || r['申込日時']))\n    });\n  }\n  var p = table_(SHEET_PAIR);\n  var pairs = [];\n  for (i = 0; i < p.rows.length; i++) pairs.push(pairObj_(p.rows[i]));\n  var safeCfg = {};\n  var k;\n  for (k in cfg) if (cfg.hasOwnProperty(k) && k !== '管理パスワード') safeCfg[k] = cfg[k];\n  return {\n    status: 'ok', config: safeCfg, divisions: DIVISIONS, divOrder: DIV_ORDER,\n    period: periodInfo_(cfg), teams: teams, entries: entries, pairs: pairs,\n    masterUpdatedAt: PropertiesService.getScriptProperties().getProperty('MASTER_UPDATED_AT') || '',\n    changes: changeLog_(),\n    requests: changeRequests_()\n  };\n}\n\n/* 登録システム（申込系GAS）から加盟チーム名簿を取り込む（読み取り専用参照） */\nfunction adminRefreshMaster_(cfg) {\n  var url = String(cfg['登録システムGAS_URL']) + '?action=getRegistrations';\n  var res = UrlFetchApp.fetch(url, { muteHttpExceptions: true, followRedirects: true });\n  if (res.getResponseCode() !== 200) throw new Error('登録システムの読み込みに失敗しました（HTTP ' + res.getResponseCode() + '）');\n  var data;\n  try {\n    data = JSON.parse(res.getContentText());\n  } catch (err) {\n    throw new Error('登録システムの応答を読み取れません: ' + res.getContentText().slice(0, 80));\n  }\n  var regs = data.registrations || [];\n  var rows = [];\n  var i, r, players, j, pl;\n  for (i = 0; i < regs.length; i++) {\n    r = regs[i];\n    if (!r.teamName) continue;\n    players = parseJson_(r.playersJson, []);\n    var norm = [];\n    for (j = 0; j < players.length; j++) {\n      pl = players[j] || {};\n      if (!pl.name) continue;\n      norm.push({ name: String(pl.name).trim(), grade: pl.grade || '', gender: String(pl.gender || '').indexOf('女') >= 0 ? '女' : (String(pl.gender || '').indexOf('男') >= 0 ? '男' : '') });\n    }\n    rows.push([String(r.teamName).trim(), r.category || '', districtName_(r.district), r.repName || '', r.repEmail || '', r.paid ? '済' : '未', JSON.stringify(norm)]);\n  }\n  var sh = ss_().getSheetByName(SHEET_MASTER);\n  if (sh.getLastRow() > 1) sh.getRange(2, 1, sh.getLastRow() - 1, sh.getLastColumn()).clearContent();\n  if (rows.length > 0) {\n    sh.getRange(2, 1, rows.length, HEADERS[SHEET_MASTER].length).setNumberFormat('@').setValues(rows);\n  }\n  PropertiesService.getScriptProperties().setProperty('MASTER_UPDATED_AT', now_());\n  log_('名簿更新', rows.length + 'チーム');\n  return { status: 'ok', count: rows.length };\n}\n\n/* 団体戦：出場チームの指定（チェックを外したチームは未申込なら削除） */\nfunction adminSetTeams_(body, cfg) {\n  var div = DIVISIONS[body.div];\n  if (!div || div.type !== 'team') throw new Error('団体戦の区分を指定してください。');\n  var want = body.teams || [];\n  var max = toInt_(cfg['団体戦上限']) || 16;\n  if (want.length > max) throw new Error(div.name + 'は最大' + max + 'チームです（選択：' + want.length + '）。');\n  var lock = LockService.getScriptLock();\n  lock.waitLock(20000);\n  try {\n    var t = table_(SHEET_ENTRY);\n    var existing = {};\n    var i, r;\n    for (i = 0; i < t.rows.length; i++) {\n      r = t.rows[i];\n      if (r['区分'] === body.div) existing[r['チーム名']] = r;\n    }\n    var wantMap = {};\n    for (i = 0; i < want.length; i++) wantMap[want[i]] = true;\n    var blocked = [];\n    var toDelete = [];\n    var name;\n    for (name in existing) {\n      if (!existing.hasOwnProperty(name) || wantMap[name]) continue;\n      if (existing[name]['状態'] === '申込済') blocked.push(name);\n      else toDelete.push(existing[name]._row);\n    }\n    if (blocked.length > 0) throw new Error('申込済みのチームは外せません：' + blocked.join('、'));\n    toDelete.sort(function (a, b) { return b - a; });\n    for (i = 0; i < toDelete.length; i++) t.sheet.deleteRow(toDelete[i]);\n    var added = 0;\n    for (i = 0; i < want.length; i++) {\n      if (existing[want[i]]) continue;\n      appendEntry_(body.div, want[i]);\n      added++;\n    }\n    log_('出場指定', div.name + '：追加' + added + '／削除' + toDelete.length);\n    return { status: 'ok', added: added, removed: toDelete.length };\n  } finally {\n    lock.releaseLock();\n  }\n}\n\n/* 個人戦：選考ペアの登録・更新。支払チームの出場枠を自動作成 */\nfunction adminSavePair_(body, cfg) {\n  var p = body.pair || {};\n  var div = DIVISIONS[p.div];\n  if (!div || div.type !== 'indiv') throw new Error('個人戦の区分を指定してください。');\n  requireText_(p.aName, '選手Aの氏名');\n  requireText_(p.aTeam, '選手Aの所属');\n  requireText_(p.bName, '選手Bの氏名');\n  requireText_(p.bTeam, '選手Bの所属');\n  var payer = p.payer || p.aTeam;\n  if (payer !== p.aTeam && payer !== p.bTeam) throw new Error('支払チームはAかBの所属から選んでください。');\n  var lock = LockService.getScriptLock();\n  lock.waitLock(20000);\n  try {\n    var pt = table_(SHEET_PAIR);\n    var count = 0;\n    var target = null;\n    var i;\n    for (i = 0; i < pt.rows.length; i++) {\n      if (pt.rows[i]['区分'] === p.div) count++;\n      if (p.pairId && pt.rows[i].pairId === p.pairId) target = pt.rows[i];\n    }\n    var max = toInt_(cfg['個人戦上限']) || 16;\n    if (!target && count >= max) throw new Error(div.name + 'は最大' + max + 'ペアです。');\n    var values = {\n      '区分': p.div, 'A氏名': String(p.aName).trim(), 'A学年': p.aGrade || '', 'A所属': p.aTeam,\n      'B氏名': String(p.bName).trim(), 'B学年': p.bGrade || '', 'B所属': p.bTeam, '支払チーム': payer\n    };\n    var oldPayer = target ? target['支払チーム'] : null;\n    if (target) {\n      if (oldPayer !== payer && entryStateFor_(p.div, oldPayer) === '申込済') {\n        throw new Error('支払チーム「' + oldPayer + '」は申込済みのため、支払チームを変更できません。');\n      }\n      writeRow_(pt, target, values);\n    } else {\n      values.pairId = 'P' + newCode_(8);\n      appendObj_(pt, values);\n    }\n    ensureEntry_(p.div, payer);\n    if (oldPayer && oldPayer !== payer) cleanupEntry_(p.div, oldPayer);\n    log_('ペア登録', div.name + '：' + values['A氏名'] + '・' + values['B氏名']);\n    return { status: 'ok' };\n  } finally {\n    lock.releaseLock();\n  }\n}\n\nfunction adminDeletePair_(body) {\n  var lock = LockService.getScriptLock();\n  lock.waitLock(20000);\n  try {\n    var pt = table_(SHEET_PAIR);\n    var i, r;\n    for (i = 0; i < pt.rows.length; i++) {\n      r = pt.rows[i];\n      if (r.pairId === body.pairId) {\n        if (entryStateFor_(r['区分'], r['支払チーム']) === '申込済') {\n          throw new Error('支払チーム「' + r['支払チーム'] + '」は申込済みです。ペアを外す場合はスプレッドシートで直接修正してください。');\n        }\n        pt.sheet.deleteRow(r._row);\n        cleanupEntry_(r['区分'], r['支払チーム']);\n        log_('ペア削除', r['A氏名'] + '・' + r['B氏名']);\n        return { status: 'ok' };\n      }\n    }\n    throw new Error('ペアが見つかりません。');\n  } finally {\n    lock.releaseLock();\n  }\n}\n\n/* 申込リンクの送信：代表者メールごとに1通にまとめる */\n/* 申込書PDF（管理者用） */\nfunction adminPdf_(body) {\n  var t = table_(SHEET_ENTRY);\n  var i;\n  for (i = 0; i < t.rows.length; i++) {\n    if (t.rows[i].entryId === body.entryId) {\n      if (t.rows[i]['状態'] !== '申込済') throw new Error('まだ申込されていません。');\n      return pdfResponse_(t.rows[i]);\n    }\n  }\n  throw new Error('申込データが見つかりません。');\n}\n\nfunction adminSendLinks_(body, cfg) {\n  var t = table_(SHEET_ENTRY);\n  var ids = body.entryIds || [];\n  var onlyUnsent = !!body.onlyUnsent;\n  var groups = {};\n  var order = [];\n  var skipped = [];\n  var i, r, key;\n  for (i = 0; i < t.rows.length; i++) {\n    r = t.rows[i];\n    if (ids.length > 0 && ids.indexOf(r.entryId) < 0) continue;\n    if (onlyUnsent && r['リンク送信日時']) continue;\n    if (!r['代表者メール']) { skipped.push(r['チーム名']); continue; }\n    key = String(r['代表者メール']).toLowerCase() + '|' + r['チーム名'];\n    if (!groups[key]) { groups[key] = []; order.push(key); }\n    groups[key].push(r);\n  }\n  var remaining = MailApp.getRemainingDailyQuota();\n  if (order.length > remaining) throw new Error('本日のメール送信可能数（残り' + remaining + '通）を超えます。対象を絞ってください。');\n  /* 添付する確定名簿（PDF）を送信前にすべて用意する。見つからなければ1通も送らない */\n  var need = { indiv: false, team: false };\n  for (i = 0; i < order.length; i++) {\n    var kinds = linkMailKinds_(groups[order[i]]);\n    if (kinds.indiv) need.indiv = true;\n    if (kinds.team) need.team = true;\n  }\n  var att = {};\n  if (need.indiv) att.indiv = rosterPdf_(cfg['個人戦名簿PDF'] || '01_個人戦出場ペア名簿.pdf', '個人戦名簿PDF');\n  if (need.team) att.team = rosterPdf_(cfg['団体戦名簿PDF'] || '02_団体戦出場チーム一覧.pdf', '団体戦名簿PDF');\n  var sent = 0;\n  var stamp = now_();\n  for (i = 0; i < order.length; i++) {\n    var resent = false;\n    var x;\n    for (x = 0; x < groups[order[i]].length; x++) if (groups[order[i]][x]['リンク送信日時']) resent = true;\n    sendLinkMail_(groups[order[i]], cfg, resent, att);\n    var j;\n    for (j = 0; j < groups[order[i]].length; j++) writeRow_(t, groups[order[i]][j], { 'リンク送信日時': stamp });\n    sent++;\n  }\n  log_('リンク送信', sent + '通' + (skipped.length ? '／メール未登録：' + skipped.join('、') : ''));\n  return { status: 'ok', sent: sent, skipped: skipped };\n}\n\n/* 未申込チームへの督促メール（管理者のみ）。同じチームの複数区分は1通にまとめる */\nfunction adminSendReminders_(body, cfg) {\n  var t = table_(SHEET_ENTRY);\n  var ids = body.entryIds || [];\n  var groups = {};\n  var order = [];\n  var skipped = [];\n  var i, r, key;\n  for (i = 0; i < t.rows.length; i++) {\n    r = t.rows[i];\n    if (r['状態'] === '申込済') continue;\n    if (ids.length > 0 && ids.indexOf(r.entryId) < 0) continue;\n    if (!r['代表者メール']) { skipped.push(r['チーム名']); continue; }\n    key = String(r['代表者メール']).toLowerCase() + '|' + r['チーム名'];\n    if (!groups[key]) { groups[key] = []; order.push(key); }\n    groups[key].push(r);\n  }\n  if (order.length === 0) return { status: 'ok', sent: 0, skipped: skipped };\n  var remaining = MailApp.getRemainingDailyQuota();\n  if (order.length > remaining) throw new Error('本日のメール送信可能数（残り' + remaining + '通）を超えます。対象を絞ってください。');\n  var stamp = now_();\n  var j;\n  for (i = 0; i < order.length; i++) {\n    sendReminderMail_(groups[order[i]], cfg);\n    for (j = 0; j < groups[order[i]].length; j++) writeRow_(t, groups[order[i]][j], { '督促送信日時': stamp });\n  }\n  log_('督促送信', order.length + '通' + (skipped.length ? '／メール未登録：' + skipped.join('、') : ''));\n  return { status: 'ok', sent: order.length, skipped: skipped };\n}\n\n/* ============================================================\n   メール\n   ============================================================ */\nfunction sendReminderMail_(rows, cfg) {\n  var first = rows[0];\n  var site = siteUrl_(cfg);\n  var lines = [];\n  lines.push(first['チーム名'] + '　' + (first['代表者名'] ? first['代表者名'] + ' 様' : 'ご担当者 様'));\n  lines.push('');\n  lines.push('岩手県中学生ソフトテニス連盟です。');\n  lines.push(cfg['大会名'] + 'について、下記の区分の参加申込がまだ完了していません。');\n  lines.push('申込締切（' + warekiDateTime_(cfg['申込締切']) + '）までに、専用の申込リンクからお申し込みください。');\n  lines.push('');\n  var sorted = rows.slice().sort(function (a, b) { return DIV_ORDER.indexOf(a['区分']) - DIV_ORDER.indexOf(b['区分']); });\n  var i, r, div;\n  for (i = 0; i < sorted.length; i++) {\n    r = sorted[i];\n    div = DIVISIONS[r['区分']];\n    lines.push('■ ' + div.name + '（' + (div.type === 'team' ? cfg['団体戦日程'] : cfg['個人戦日程']) + '）');\n    lines.push('　' + site + (div.type === 'team' ? 'entry-team.html' : 'entry-individual.html') + '?t=' + r['トークン']);\n    lines.push('');\n  }\n  lines.push('※ 出場を辞退される場合や、すでに申込済みの場合は、お手数ですが下記までご連絡ください。');\n  lines.push('');\n  lines.push('--');\n  lines.push(cfg['署名']);\n  var subject = '【' + cfg['大会名'] + '】参加申込のお願い（締切 ' + warekiDateTime_(cfg['申込締切']) + '）';\n  MailApp.sendEmail({ to: first['代表者メール'], subject: subject, body: lines.join('\\n'), name: '岩手県中学生ソフトテニス連盟' });\n}\n\n/* 1通に含まれる区分の種類（個人戦・団体戦） */\nfunction linkMailKinds_(rows) {\n  var k = { indiv: false, team: false };\n  var i;\n  for (i = 0; i < rows.length; i++) {\n    if (DIVISIONS[rows[i]['区分']].type === 'team') k.team = true; else k.indiv = true;\n  }\n  return k;\n}\n\n/* 確定名簿PDFをGoogleドライブから取得。設定値はファイル名・ファイルID・ドライブのURLのどれでもよい */\nfunction rosterPdf_(spec, label) {\n  spec = String(spec || '').trim();\n  var file = null;\n  var m = spec.match(/\\/d\\/([A-Za-z0-9_-]{20,})/) || spec.match(/[?&]id=([A-Za-z0-9_-]{20,})/);\n  var id = m ? m[1] : (/^[A-Za-z0-9_-]{25,}$/.test(spec) ? spec : '');\n  if (id) {\n    try { file = DriveApp.getFileById(id); } catch (e) { throw new Error('設定「' + label + '」のファイル（' + spec + '）を開けません。'); }\n  } else {\n    var it = DriveApp.getFilesByName(spec);\n    var f;\n    while (it.hasNext()) {\n      f = it.next();\n      if (f.isTrashed()) continue;\n      if (!file || f.getLastUpdated().getTime() > file.getLastUpdated().getTime()) file = f;\n    }\n    if (!file) throw new Error('添付する「' + spec + '」がGoogleドライブに見つかりません。メールは送信していません。ファイルをドライブに置くか、設定シート「' + label + '」にファイル名・ID・URLを入れてください。');\n  }\n  var blob = file.getBlob();\n  if (blob.getContentType() !== 'application/pdf') blob = file.getAs('application/pdf');\n  return blob.setName(id ? file.getName() : spec);\n}\n\nfunction sendLinkMail_(rows, cfg, isResend, att) {\n  var first = rows[0];\n  if (!first['代表者メール']) return;\n  var kinds = linkMailKinds_(rows);\n  att = att || {};\n  var site = siteUrl_(cfg);\n  var lines = [];\n  lines.push(first['チーム名'] + '　' + (first['代表者名'] ? first['代表者名'] + ' 様' : 'ご担当者 様'));\n  lines.push('');\n  lines.push('岩手県中学生ソフトテニス連盟です。');\n  lines.push(cfg['大会名'] + 'の参加申込についてご案内します。');\n  lines.push('');\n  lines.push('貴チームは下記の区分の' + (kinds.team && kinds.indiv ? '出場チーム・出場ペア' : kinds.team ? '出場チーム' : '出場ペア') + 'に決定しました。');\n  lines.push((kinds.team && kinds.indiv ? '個人戦の出場ペア名簿と団体戦の出場チーム一覧' : kinds.team ? '団体戦の出場チーム一覧' : '個人戦の出場ペア名簿') + '（PDF）を添付しています。');\n  lines.push('それぞれ専用の申込リンクから、申込期間内にお申し込みください。');\n  lines.push('');\n  lines.push('■ 申込期間');\n  lines.push('　' + warekiDateTime_(cfg['申込開始']) + ' 〜 ' + warekiDateTime_(cfg['申込締切']));\n  lines.push('');\n  var sorted = rows.slice().sort(function (a, b) { return DIV_ORDER.indexOf(a['区分']) - DIV_ORDER.indexOf(b['区分']); });\n  var i, r, div;\n  for (i = 0; i < sorted.length; i++) {\n    r = sorted[i];\n    div = DIVISIONS[r['区分']];\n    lines.push('■ ' + div.name + '（' + (div.type === 'team' ? cfg['団体戦日程'] : cfg['個人戦日程']) + '／' + (div.gender === '男' ? cfg['男子会場'] : cfg['女子会場']) + '）');\n    if (div.type === 'indiv') {\n      var pairs = pairsForEntry_(r);\n      var j;\n      for (j = 0; j < pairs.length; j++) lines.push('　・' + pairs[j].label);\n    }\n    lines.push('　' + site + (div.type === 'team' ? 'entry-team.html' : 'entry-individual.html') + '?t=' + r['トークン']);\n    lines.push('');\n  }\n  lines.push('※ このリンクは貴チーム専用です。他チームへの転送はご遠慮ください。');\n  lines.push('※ 申込後も、申込期間内であれば同じリンクから内容を修正できます。');\n  lines.push('※ 参加料は大会当日の受付で現金にて納入してください。');\n  lines.push('※ 申込フォームでは、選手の氏名・学年・学校名、監督（ベンチ入り指導者）の氏名、試合結果を大会ホームページへの掲載や報道機関への結果提供等に使用することについて、選手本人および保護者、監督の同意を得ていることを確認します。申込開始までにご確認をお願いします。');\n  lines.push('');\n  lines.push('--');\n  lines.push(cfg['署名']);\n  var what = kinds.team && kinds.indiv ? '団体戦出場チーム・個人戦出場ペアの決定について' : kinds.team ? '団体戦出場チームの決定について' : '個人戦出場ペアの決定について';\n  var subject = '【' + cfg['大会名'] + '】' + what + '（申込リンクのご案内）' + (isResend ? '（再送）' : '');\n  var files = [];\n  if (kinds.indiv) { if (!att.indiv) att.indiv = rosterPdf_(cfg['個人戦名簿PDF'] || '01_個人戦出場ペア名簿.pdf', '個人戦名簿PDF'); files.push(att.indiv); }\n  if (kinds.team) { if (!att.team) att.team = rosterPdf_(cfg['団体戦名簿PDF'] || '02_団体戦出場チーム一覧.pdf', '団体戦名簿PDF'); files.push(att.team); }\n  MailApp.sendEmail({ to: first['代表者メール'], subject: subject, body: lines.join('\\n'), name: '岩手県中学生ソフトテニス連盟', attachments: files });\n}\n\nfunction sendConfirmMail_(entry, cfg, isNew) {\n  var div = DIVISIONS[entry['区分']];\n  var site = siteUrl_(cfg);\n  var lines = [];\n  lines.push(entry['チーム名'] + '　' + entry['申込者氏名'] + ' 様');\n  lines.push('');\n  lines.push(cfg['大会名'] + '　' + div.name + 'の' + (isNew ? '参加申込を受け付けました。' : '申込内容の修正を受け付けました。'));\n  lines.push('');\n  lines.push('■ 大会情報');\n  lines.push('　期日：' + (div.type === 'team' ? cfg['団体戦日程'] : cfg['個人戦日程']));\n  lines.push('　会場：' + (div.gender === '男' ? cfg['男子会場'] : cfg['女子会場']));\n  lines.push('　開場：' + cfg['開場時刻']);\n  lines.push('　受付：' + cfg['受付時刻']);\n  lines.push('');\n  lines.push('■ 申込内容');\n  lines.push('　チーム名：' + entry['チーム名'] + (entry['略称'] ? '（組合せ表記：' + entry['略称'] + '）' : ''));\n  if (div.type === 'team') {\n    lines.push('　監督（ベンチ入り指導者）：' + entry['監督氏名'] + '（' + entry['監督役職'] + '）');\n    var players = parseJson_(entry['選手JSON'], []);\n    var i;\n    for (i = 0; i < players.length; i++) {\n      lines.push('　' + players[i].no + '．' + (players[i].vacant ? '（欠員）' : players[i].name + '（' + players[i].grade + '）'));\n    }\n  } else {\n    var pairs = pairsForEntry_(entry);\n    var k;\n    for (k = 0; k < pairs.length; k++) {\n      lines.push('　ペア' + (k + 1) + '：' + pairs[k].label + '　監督：' + pairs[k].coachName + '（' + pairs[k].coachTitle + '）');\n    }\n  }\n  lines.push('　申込責任者：' + entry['申込者氏名'] + '（' + entry['申込者役職'] + '）' + entry['申込者電話']);\n  lines.push('　個人情報の取扱い：同意済み（選手本人および保護者、監督）');\n  lines.push('');\n  lines.push('■ 参加料：' + toInt_(entry['参加料']).toLocaleString() + '円（大会当日の受付で現金にて納入）');\n  lines.push('');\n  lines.push('■ 申込書（PDF）');\n  lines.push('　このメールに添付しています。申込内容の修正ページからもダウンロードできます。');\n  lines.push('');\n  lines.push('■ 当日受付票（二次元コード）');\n  lines.push('　当日の受付で、次のページの二次元コードを提示してください。');\n  lines.push('　' + site + 'ticket.html?t=' + entry['トークン']);\n  lines.push('');\n  lines.push('■ 申込内容の修正は' + warekiDateTime_(cfg['申込締切']) + 'まで可能です。');\n  lines.push('　' + site + (div.type === 'team' ? 'entry-team.html' : 'entry-individual.html') + '?t=' + entry['トークン']);\n  lines.push('');\n  lines.push('--');\n  lines.push(cfg['署名']);\n  var subject = '【' + cfg['大会名'] + '】' + div.name + ' ' + (isNew ? '申込受付' : '申込修正') + '（' + entry['チーム名'] + '）';\n  var mail = { to: entry['申込者メール'], subject: subject, body: lines.join('\\n'), name: '岩手県中学生ソフトテニス連盟' };\n  /* 申込書PDFを添付（作成に失敗してもメールは送る） */\n  try {\n    mail.attachments = [buildApplicationPdf_(entry, cfg)];\n  } catch (pErr) {\n    log_('pdf-error', entry['チーム名'] + ': ' + pErr.message);\n  }\n  MailApp.sendEmail(mail);\n}\n\n/* ============================================================\n   申込書PDF（A4縦1枚）\n   Googleドキュメントで作成 → PDF化 → 一時ドキュメントは削除\n   ============================================================ */\nvar PDF_GREEN = '#1a4a2e';\nvar PDF_LIGHT = '#e8f1eb';\n\nfunction buildApplicationPdf_(entry, cfg) {\n  var div = DIVISIONS[entry['区分']];\n  var doc = DocumentApp.create('申込書_' + entry['区分'] + '_' + entry['チーム名']);\n  var fileId = doc.getId();\n  try {\n    var body = doc.getBody();\n    body.setPageWidth(595.28).setPageHeight(841.89);\n    body.setMarginTop(36).setMarginBottom(30).setMarginLeft(42).setMarginRight(42);\n\n    var head = body.getParagraphs()[0];\n    head.setText(cfg['大会名']);\n    pdfPara_(head, 12, true, DocumentApp.HorizontalAlignment.CENTER, 0, 2);\n    pdfPara_(body.appendParagraph(div.name + '　参加申込書'), 18, true, DocumentApp.HorizontalAlignment.CENTER, 0, 4);\n    var stamp = '申込日時：' + warekiDateTime_(entry['申込日時']);\n    if (entry['更新日時'] && entry['更新日時'] !== entry['申込日時']) stamp += '　最終更新：' + warekiDateTime_(entry['更新日時']);\n    pdfPara_(body.appendParagraph(stamp), 9, false, DocumentApp.HorizontalAlignment.RIGHT, 0, 6);\n\n    pdfHeading_(body, '大会情報');\n    pdfKvTable_(body, [\n      ['期日', div.type === 'team' ? cfg['団体戦日程'] : cfg['個人戦日程']],\n      ['会場', div.gender === '男' ? cfg['男子会場'] : cfg['女子会場']],\n      ['開場・受付', '開場 ' + cfg['開場時刻'] + '　／　受付 ' + cfg['受付時刻']]\n    ]);\n\n    pdfHeading_(body, 'チーム');\n    var teamRows = [\n      ['チーム名', entry['チーム名']],\n      ['組合せ表記（略称）', entry['略称'] || ''],\n      ['地区', districtName_(entry['地区'])]\n    ];\n    if (div.type === 'team') teamRows.push(['監督（ベンチ入り指導者）', entry['監督氏名'] + '（' + entry['監督役職'] + '）']);\n    pdfKvTable_(body, teamRows);\n\n    if (div.type === 'team') {\n      pdfHeading_(body, '選手');\n      var players = parseJson_(entry['選手JSON'], []);\n      var rows = [['No.', '氏名', '学年', '備考']];\n      var i, p;\n      for (i = 0; i < 8; i++) {\n        p = players[i] || { vacant: true };\n        var note = p.vacant ? '欠員' : (p.offRoster ? '登録名簿外（要確認）' : '');\n        if (p.changedFrom) note = (note ? note + '\\n' : '') + '選手変更（変更前：' + p.changedFrom + '）';\n        rows.push([String(i + 1), p.vacant ? '' : p.name, p.vacant ? '' : p.grade, note]);\n      }\n      pdfGridTable_(body, rows, [40, 230, 60, 181]);\n    } else {\n      pdfHeading_(body, '出場ペア');\n      var pairs = pairsForEntry_(entry);\n      var prow = [['ペア', '選手A', '選手B', '監督（ベンチ入り指導者）']];\n      var k, pr;\n      for (k = 0; k < pairs.length; k++) {\n        pr = pairs[k];\n        prow.push([String(k + 1),\n          pr.aName + '（' + pr.aGrade + '）\\n' + pr.aTeam,\n          pr.bName + '（' + pr.bGrade + '）\\n' + pr.bTeam,\n          (pr.coachName || '') + (pr.coachTitle ? '\\n（' + pr.coachTitle + '）' : '')]);\n      }\n      pdfGridTable_(body, prow, [40, 165, 165, 141]);\n    }\n\n    pdfHeading_(body, '申込責任者');\n    pdfKvTable_(body, [\n      ['氏名（役職）', entry['申込者氏名'] + '（' + entry['申込者役職'] + '）'],\n      ['携帯番号', entry['申込者電話']],\n      ['メールアドレス', entry['申込者メール']]\n    ]);\n\n    pdfHeading_(body, '参加料');\n    var feeText = toInt_(entry['参加料']).toLocaleString() + '円';\n    if (div.type === 'indiv') feeText += '（' + toInt_(entry['ペア数']) + 'ペア × ' + toInt_(cfg['個人戦参加料']).toLocaleString() + '円）';\n    pdfKvTable_(body, [['参加料', feeText + '　大会当日の受付で現金にて納入']]);\n\n    pdfPara_(pdfNextPara_(body, '受付コード：' + (entry['受付コード'] || '') + '　　岩手県中学生ソフトテニス連盟'), 8, false, DocumentApp.HorizontalAlignment.RIGHT, 10, 0);\n\n    doc.saveAndClose();\n    var name = cfg['大会名'] + '_' + div.name + '_申込書_' + entry['チーム名'] + '.pdf';\n    return DriveApp.getFileById(fileId).getAs(MimeType.PDF).setName(name);\n  } finally {\n    try { DriveApp.getFileById(fileId).setTrashed(true); } catch (e) { /* 削除失敗は無視 */ }\n  }\n}\n\nfunction pdfPara_(p, size, bold, align, before, after) {\n  p.setAlignment(align).setSpacingBefore(before).setSpacingAfter(after).setLineSpacing(1);\n  var t = p.editAsText();\n  if (t.getText().length > 0) t.setFontSize(size).setBold(bold).setForegroundColor('#000000');\n  return p;\n}\n\n/* ============================================================\n   区分別 申込一覧PDF（A4横）\n   ============================================================ */\nfunction adminListPdf_(body, cfg) {\n  var div = DIVISIONS[body.div];\n  if (!div) throw new Error('区分を指定してください。');\n  var t = table_(SHEET_ENTRY);\n  var entries = [];\n  var i;\n  for (i = 0; i < t.rows.length; i++) if (t.rows[i]['区分'] === body.div) entries.push(t.rows[i]);\n  entries.sort(function (a, b) { return districtCompare_(a['地区'], b['地区']) || String(a['チーム名']).localeCompare(String(b['チーム名']), 'ja'); });\n  var applied = 0;\n  var feeTotal = 0;\n  for (i = 0; i < entries.length; i++) {\n    if (entries[i]['状態'] === '申込済') { applied++; feeTotal += toInt_(entries[i]['参加料']); }\n  }\n\n  var name = cfg['大会名'] + '_' + div.name + '_申込一覧.pdf';\n  var doc = DocumentApp.create('一覧_' + body.div);\n  var fileId = doc.getId();\n  try {\n    var b = doc.getBody();\n    b.setPageWidth(841.89).setPageHeight(595.28);\n    b.setMarginTop(28).setMarginBottom(24).setMarginLeft(28).setMarginRight(28);\n    var head = b.getParagraphs()[0];\n    head.setText(cfg['大会名'] + '　' + div.name + '　申込一覧');\n    pdfPara_(head, 14, true, DocumentApp.HorizontalAlignment.CENTER, 0, 2);\n    var summary = (div.type === 'team' ? cfg['団体戦日程'] : cfg['個人戦日程']) + '　' + (div.gender === '男' ? cfg['男子会場'] : cfg['女子会場']) +\n      '　｜　申込済 ' + applied + ' / 出場 ' + entries.length + ' チーム';\n    var rows, widths;\n    if (div.type === 'team') {\n      rows = [['No.', '地区', 'チーム名\\n（略称）', '監督', '1', '2', '3', '4', '5', '6', '7', '8', '状態']];\n      var e, players, row, k, p;\n      for (i = 0; i < entries.length; i++) {\n        e = entries[i];\n        players = e['状態'] === '申込済' ? parseJson_(e['選手JSON'], []) : [];\n        row = [String(i + 1), districtName_(e['地区']), e['チーム名'] + (e['略称'] ? '\\n（' + e['略称'] + '）' : ''), e['監督氏名'] || ''];\n        for (k = 0; k < 8; k++) {\n          p = players[k];\n          if (!p) row.push('');\n          else if (p.vacant) row.push('欠員');\n          else row.push(p.name + (p.offRoster ? '※' : '') + '\\n' + p.grade);\n        }\n        row.push(e['状態'] || '未申込');\n        rows.push(row);\n      }\n      widths = [22, 36, 104, 62, 62, 62, 62, 62, 62, 62, 62, 62, 46];\n    } else {\n      var pt = table_(SHEET_PAIR);\n      var pairs = [];\n      for (i = 0; i < pt.rows.length; i++) if (pt.rows[i]['区分'] === body.div) pairs.push(pairObj_(pt.rows[i]));\n      summary += '（' + pairs.length + 'ペア）';\n      var stateOf = {};\n      var abbrOf = {};\n      for (i = 0; i < entries.length; i++) { stateOf[entries[i]['チーム名']] = entries[i]['状態'] || '未申込'; abbrOf[entries[i]['チーム名']] = entries[i]['略称'] || ''; }\n      rows = [['No.', '選手A', '学年', '所属', '選手B', '学年', '所属', '監督（役職）', '申込チーム\\n（略称）', '状態']];\n      var pr;\n      for (i = 0; i < pairs.length; i++) {\n        pr = pairs[i];\n        rows.push([String(i + 1), pr.aName, pr.aGrade || '', pr.aTeam, pr.bName, pr.bGrade || '', pr.bTeam,\n          pr.coachName ? pr.coachName + '\\n（' + pr.coachTitle + '）' : '',\n          pr.payer + (abbrOf[pr.payer] ? '\\n（' + abbrOf[pr.payer] + '）' : ''), stateOf[pr.payer] || '未申込']);\n      }\n      widths = [22, 82, 32, 108, 82, 32, 108, 100, 108, 46];\n    }\n    summary += '　｜　参加料（申込済）' + feeTotal.toLocaleString() + '円　｜　作成 ' + warekiDateTime_(now_());\n    pdfPara_(b.appendParagraph(summary), 8.5, false, DocumentApp.HorizontalAlignment.RIGHT, 0, 4);\n    pdfGridTable_(b, rows, widths, 8.5);\n    if (div.type === 'team') pdfPara_(pdfNextPara_(b, '※ 登録名簿にない選手（要確認）'), 8, false, DocumentApp.HorizontalAlignment.LEFT, 4, 0);\n    doc.saveAndClose();\n    var blob = DriveApp.getFileById(fileId).getAs(MimeType.PDF).setName(name);\n    return { status: 'ok', name: name, base64: Utilities.base64Encode(blob.getBytes()) };\n  } finally {\n    try { DriveApp.getFileById(fileId).setTrashed(true); } catch (err) { /* 削除失敗は無視 */ }\n  }\n}\n\n/* 表の直後に自動で入る空段落があれば再利用する（余白を詰める） */\nfunction pdfNextPara_(body, text) {\n  var n = body.getNumChildren();\n  var last = n > 0 ? body.getChild(n - 1) : null;\n  if (last && last.getType() === DocumentApp.ElementType.PARAGRAPH && last.asParagraph().getText() === '' && n > 1) {\n    var p = last.asParagraph();\n    p.setText(text);\n    return p;\n  }\n  return body.appendParagraph(text);\n}\n\nfunction pdfHeading_(body, label) {\n  var p = pdfNextPara_(body, '■ ' + label);\n  pdfPara_(p, 10.5, true, DocumentApp.HorizontalAlignment.LEFT, 8, 3);\n  p.editAsText().setForegroundColor(PDF_GREEN);\n}\n\n/* 項目名｜内容 の2列表 */\nfunction pdfKvTable_(body, rows) {\n  var table = body.appendTable(rows);\n  table.setBorderColor('#999999').setBorderWidth(0.5);\n  table.setColumnWidth(0, 150);\n  var r, c, cell;\n  for (r = 0; r < table.getNumRows(); r++) {\n    for (c = 0; c < 2; c++) {\n      cell = table.getRow(r).getCell(c);\n      pdfCell_(cell, 10, c === 0, c === 0 ? PDF_LIGHT : '#ffffff', '#000000');\n    }\n  }\n  return table;\n}\n\n/* 見出し行つきの一覧表（1行目が見出し） */\nfunction pdfGridTable_(body, rows, widths, size) {\n  size = size || 10;\n  var table = body.appendTable(rows);\n  table.setBorderColor('#999999').setBorderWidth(0.5);\n  var r, c, cell;\n  for (c = 0; c < widths.length; c++) table.setColumnWidth(c, widths[c]);\n  for (r = 0; r < table.getNumRows(); r++) {\n    for (c = 0; c < table.getRow(r).getNumCells(); c++) {\n      cell = table.getRow(r).getCell(c);\n      if (r === 0) {\n        pdfCell_(cell, size - 0.5, true, PDF_GREEN, '#ffffff');\n      } else {\n        /* 見出しの白文字がデータ行に引き継がれないよう黒を明示 */\n        pdfCell_(cell, size, false, '#ffffff', '#000000');\n      }\n      if (c === 0) cell.getChild(0).asParagraph().setAlignment(DocumentApp.HorizontalAlignment.CENTER);\n    }\n  }\n  return table;\n}\n\nfunction pdfCell_(cell, size, bold, bg, color) {\n  cell.setBackgroundColor(bg).setPaddingTop(3).setPaddingBottom(3).setPaddingLeft(5).setPaddingRight(5);\n  var t = cell.editAsText();\n  if (t.getText().length > 0) t.setFontSize(size).setBold(bold).setForegroundColor(color);\n  var n = cell.getNumChildren();\n  var i;\n  for (i = 0; i < n; i++) {\n    if (cell.getChild(i).getType() === DocumentApp.ElementType.PARAGRAPH) {\n      cell.getChild(i).asParagraph().setSpacingBefore(0).setSpacingAfter(0).setLineSpacing(1);\n    }\n  }\n}\n\n/* ============================================================\n   データヘルパー\n   ============================================================ */\nfunction ss_() { return SpreadsheetApp.getActiveSpreadsheet(); }\n\nfunction table_(name) {\n  var sh = ss_().getSheetByName(name);\n  if (!sh) throw new Error('シート「' + name + '」がありません。setup() を実行してください。');\n  var values = sh.getDataRange().getValues();\n  var headers = values.length ? values[0] : [];\n  var rows = [];\n  var i, j, o;\n  for (i = 1; i < values.length; i++) {\n    o = { _row: i + 1 };\n    for (j = 0; j < headers.length; j++) o[headers[j]] = values[i][j] === null ? '' : values[i][j];\n    rows.push(o);\n  }\n  return { sheet: sh, headers: headers, rows: rows };\n}\n\nfunction writeRow_(t, rowObj, update) {\n  var range = t.sheet.getRange(rowObj._row, 1, 1, t.headers.length);\n  var current = range.getValues()[0];\n  var k, col;\n  for (k in update) {\n    if (!update.hasOwnProperty(k)) continue;\n    col = t.headers.indexOf(k);\n    if (col < 0 && HEADERS[t.sheet.getName()] && HEADERS[t.sheet.getName()].indexOf(k) >= 0) {\n      /* 新しく追加した列（例：略称）は自動でヘッダーを足す */\n      t.sheet.getRange(1, t.headers.length + 1).setNumberFormat('@').setValue(k).setFontWeight('bold');\n      t.headers.push(k);\n      current.push('');\n      range = t.sheet.getRange(rowObj._row, 1, 1, t.headers.length);\n      col = t.headers.length - 1;\n    }\n    if (col < 0) throw new Error('シート「' + t.sheet.getName() + '」に列「' + k + '」がありません。setup() を再実行してください。');\n    current[col] = update[k] === undefined || update[k] === null ? '' : update[k];\n    rowObj[k] = current[col];\n  }\n  range.setNumberFormat('@').setValues([current]);\n}\n\nfunction appendObj_(t, obj) {\n  var row = [];\n  var i;\n  for (i = 0; i < t.headers.length; i++) row.push(obj[t.headers[i]] === undefined ? '' : obj[t.headers[i]]);\n  var r = t.sheet.getLastRow() + 1;\n  t.sheet.getRange(r, 1, 1, row.length).setNumberFormat('@').setValues([row]);\n}\n\nfunction appendEntry_(divCode, teamName) {\n  var master = masterTeam_(teamName, DIVISIONS[divCode].gender);\n  var t = table_(SHEET_ENTRY);\n  appendObj_(t, {\n    entryId: 'E' + newCode_(8), '区分': divCode, 'チーム名': teamName,\n    '地区': master ? districtName_(master['地区']) : '', '代表者名': master ? master['代表者名'] : '',\n    '代表者メール': master ? master['代表者メール'] : '', 'トークン': newCode_(16), '状態': '未申込'\n  });\n}\n\nfunction ensureEntry_(divCode, teamName) {\n  if (entryStateFor_(divCode, teamName) === null) appendEntry_(divCode, teamName);\n}\n\n/* 支払チームのペアが0になり、未申込なら出場枠を削除 */\nfunction cleanupEntry_(divCode, teamName) {\n  var pt = table_(SHEET_PAIR);\n  var i;\n  for (i = 0; i < pt.rows.length; i++) {\n    if (pt.rows[i]['区分'] === divCode && pt.rows[i]['支払チーム'] === teamName) return;\n  }\n  var t = table_(SHEET_ENTRY);\n  for (i = 0; i < t.rows.length; i++) {\n    if (t.rows[i]['区分'] === divCode && t.rows[i]['チーム名'] === teamName && t.rows[i]['状態'] !== '申込済') {\n      t.sheet.deleteRow(t.rows[i]._row);\n      return;\n    }\n  }\n}\n\nfunction entryStateFor_(divCode, teamName) {\n  var t = table_(SHEET_ENTRY);\n  var i;\n  for (i = 0; i < t.rows.length; i++) {\n    if (t.rows[i]['区分'] === divCode && t.rows[i]['チーム名'] === teamName) return t.rows[i]['状態'] || '未申込';\n  }\n  return null;\n}\n\n/* 申込リンクが初めて開かれた日時を記録（管理画面の「未開封」判定に使う） */\nfunction recordFirstAccess_(token) {\n  try {\n    var t = table_(SHEET_ENTRY);\n    var i;\n    for (i = 0; i < t.rows.length; i++) {\n      if (String(t.rows[i]['トークン']) === String(token)) {\n        if (!t.rows[i]['初回アクセス日時']) writeRow_(t, t.rows[i], { '初回アクセス日時': now_() });\n        return;\n      }\n    }\n  } catch (err) {\n    log_('error', '初回アクセス記録: ' + err.message);\n  }\n}\n\nfunction findEntryByToken_(token) {\n  if (!token || String(token).length < 8) return null;\n  var t = table_(SHEET_ENTRY);\n  var i;\n  for (i = 0; i < t.rows.length; i++) {\n    if (String(t.rows[i]['トークン']) === String(token)) return t.rows[i];\n  }\n  return null;\n}\n\n/* 加盟チーム名簿からチームを探す。同じ名前で男女別に登録している団体（例：クラブ）は、\n   gender（'男'／'女'）に合う種別の登録を優先する（男子・女子 → 完全一致、男女 → 次点） */\nfunction masterTeam_(name, gender) {\n  var m = table_(SHEET_MASTER);\n  var best = null, bestScore = -1;\n  var i, sc;\n  for (i = 0; i < m.rows.length; i++) {\n    if (m.rows[i]['チーム名'] !== name) continue;\n    sc = gender ? categoryScore_(m.rows[i]['種別'], gender) : 0;\n    if (sc > bestScore) { best = m.rows[i]; bestScore = sc; }\n  }\n  return best;\n}\n\nfunction categoryScore_(cat, gender) {\n  cat = String(cat || '');\n  if (cat.indexOf('男女') >= 0) return 1;\n  if (cat.indexOf(gender) >= 0) return 2;\n  return cat ? 0 : 1;\n}\n\n/* 登録名簿のうち、指定の性別の選手（性別未設定の選手も含める） */\nfunction rosterFor_(teamName, gender) {\n  var m = masterTeam_(teamName, gender);\n  if (!m) return [];\n  var players = parseJson_(m['選手JSON'], []);\n  var out = [];\n  var i;\n  for (i = 0; i < players.length; i++) {\n    if (!players[i].gender || players[i].gender === gender) out.push({ name: players[i].name, grade: players[i].grade });\n  }\n  return out;\n}\n\nfunction isPairOfEntry_(pr, entry) {\n  return pr['区分'] === entry['区分'] && pr['支払チーム'] === entry['チーム名'];\n}\n\nfunction pairsForEntry_(entry) {\n  var pt = table_(SHEET_PAIR);\n  var out = [];\n  var i;\n  for (i = 0; i < pt.rows.length; i++) {\n    if (isPairOfEntry_(pt.rows[i], entry)) out.push(pairObj_(pt.rows[i]));\n  }\n  return out;\n}\n\nfunction pairObj_(r) {\n  var joint = r['A所属'] !== r['B所属'];\n  var label = r['A氏名'] + '・' + r['B氏名'] + '（' + (joint ? r['A所属'] + '／' + r['B所属'] : r['A所属']) + '）';\n  return {\n    pairId: r.pairId, div: r['区分'],\n    aName: r['A氏名'], aGrade: r['A学年'], aTeam: r['A所属'],\n    bName: r['B氏名'], bGrade: r['B学年'], bTeam: r['B所属'],\n    payer: r['支払チーム'], joint: joint, label: label, change: parseJson_(r['変更記録'], null), preChange: parseJson_(r['申込時変更'], null),\n    coachName: r['監督氏名'], coachTitle: r['監督役職']\n  };\n}\n\nfunction getConfig_() {\n  var sh = ss_().getSheetByName(SHEET_CONFIG);\n  if (!sh) throw new Error('シート「設定」がありません。setup() を実行してください。');\n  var values = sh.getDataRange().getValues();\n  var cfg = {};\n  var i, v;\n  /* シートにない項目は初期値を使う（項目を追加したときの保険） */\n  for (i = 0; i < CONFIG_DEFAULTS.length; i++) cfg[CONFIG_DEFAULTS[i][0]] = CONFIG_DEFAULTS[i][1];\n  for (i = 1; i < values.length; i++) {\n    v = values[i][1];\n    if (v instanceof Date) {\n      v = v.getFullYear() < 1901 ? Utilities.formatDate(v, 'Asia/Tokyo', 'H:mm') : Utilities.formatDate(v, 'Asia/Tokyo', 'yyyy-MM-dd HH:mm');\n    }\n    if (String(values[i][0]) !== '') cfg[String(values[i][0])] = v;\n  }\n  return cfg;\n}\n\nfunction periodInfo_(cfg) {\n  var start = parseJst_(cfg['申込開始']);\n  var end = parseJst_(cfg['申込締切']);\n  var now = new Date();\n  var state = 'open';\n  if (start && now < start) state = 'before';\n  if (end && now > end) state = 'after';\n  return { state: state, start: cfg['申込開始'], end: cfg['申込締切'] };\n}\n\nfunction parseJst_(s) {\n  if (!s) return null;\n  if (s instanceof Date) return s;\n  try {\n    return Utilities.parseDate(String(s).trim().slice(0, 16), 'Asia/Tokyo', 'yyyy-MM-dd HH:mm');\n  } catch (err) {\n    return null;\n  }\n}\n\n/* 「2026-11-19 17:00」→「令和8年11月19日（木）17:00」 */\nfunction warekiDateTime_(s) {\n  var d = parseJst_(s);\n  if (!d) return String(s || '');\n  var y = toInt_(Utilities.formatDate(d, 'Asia/Tokyo', 'yyyy'));\n  var md = Utilities.formatDate(d, 'Asia/Tokyo', 'M月d日');\n  var hm = Utilities.formatDate(d, 'Asia/Tokyo', 'H:mm');\n  var w = ['日', '月', '火', '水', '木', '金', '土'][toInt_(Utilities.formatDate(d, 'Asia/Tokyo', 'u')) % 7];\n  return '令和' + (y - 2018) + '年' + md + '（' + w + '）' + hm;\n}\n\n/* 中体連の地区順 */\nvar DISTRICT_ORDER = ['久慈', '二戸', '岩手', '盛岡', '紫波', '花巻', '和賀', '胆江', '一関', '気仙', '遠野', '釜石・大槌', '宮古'];\n/* 地区名の表示：団体登録の「01_久慈」のような並び順の番号（数字＋アンダーバー等）を外す */\nfunction districtName_(d) {\n  return String(d || '').replace(/^\\s*[0-9０-９]+\\s*[_＿\\-－.．、:：]\\s*/, '').trim();\n}\nfunction districtCompare_(a, b) {\n  a = districtName_(a);\n  b = districtName_(b);\n  var ia = DISTRICT_ORDER.indexOf(a), ib = DISTRICT_ORDER.indexOf(b);\n  if (ia < 0) ia = 99;\n  if (ib < 0) ib = 99;\n  return ia - ib;\n}\n\n/* 略称の候補：「○○中学校」→「○○中」 */\nfunction suggestAbbr_(name) {\n  return String(name || '').replace(/中学校$/, '中').replace(/[\\s　]/g, '');\n}\n\nfunction siteUrl_(cfg) {\n  var u = String(cfg['サイトURL'] || '');\n  return u.charAt(u.length - 1) === '/' ? u : u + '/';\n}\n\nfunction log_(kind, msg) {\n  try {\n    var sh = ss_().getSheetByName(SHEET_LOG);\n    if (sh) sh.appendRow([now_(), kind, msg]);\n  } catch (err) { /* ログ失敗は無視 */ }\n}\n\nfunction now_() { return Utilities.formatDate(new Date(), 'Asia/Tokyo', 'yyyy-MM-dd HH:mm:ss'); }\n\nfunction newCode_(len) {\n  var s = '';\n  while (s.length < len) s += Utilities.getUuid().replace(/-/g, '');\n  return s.slice(0, len);\n}\n\nfunction parseJson_(s, fallback) {\n  if (!s) return fallback;\n  try { return JSON.parse(s); } catch (err) { return fallback; }\n}\n\nfunction toInt_(v) { var n = parseInt(String(v).replace(/[^0-9-]/g, ''), 10); return isNaN(n) ? 0 : n; }\n\nfunction normName_(s) { return String(s || '').replace(/[\\s　]/g, ''); }\n\nfunction requireText_(v, label) {\n  if (v === undefined || v === null || String(v).trim() === '') throw new Error(label + 'を入力してください。');\n}\n\nfunction json_(o) {\n  return ContentService.createTextOutput(JSON.stringify(o)).setMimeType(ContentService.MimeType.JSON);\n}\n\n/* ============================================================\n   一度だけ実行：出場枠の代表者を、区分の性別に合う名簿の登録に合わせ直す\n   （同じ名前で男女別に登録しているチームの、男子の枠に女子の代表者が入っていた件の修正）\n   - まだ申込していない枠だけを直す。直した枠は「リンク未送信」に戻すので、\n     管理画面の「未送信のチームにリンクを送信」で正しい代表者へ送れる\n   - GASの画面で関数「fixEntryReps」を選んで実行。結果は実行ログとシート「ログ」に出る\n   ============================================================ */\nfunction fixEntryReps() {\n  var t = table_(SHEET_ENTRY);\n  var fixed = [], applied = [];\n  var i, e, mt;\n  for (i = 0; i < t.rows.length; i++) {\n    e = t.rows[i];\n    if (!DIVISIONS[e['区分']]) continue;\n    mt = masterTeam_(e['チーム名'], DIVISIONS[e['区分']].gender);\n    if (!mt) continue;\n    if (String(mt['代表者メール']) === String(e['代表者メール']) && String(mt['代表者名']) === String(e['代表者名'])) continue;\n    var label = DIVISIONS[e['区分']].name + '／' + e['チーム名'] + '：' + (e['代表者名'] || '') + '（' + (e['代表者メール'] || '') + '）→ ' + (mt['代表者名'] || '') + '（' + (mt['代表者メール'] || '') + '）';\n    if (e['状態'] === '申込済') { applied.push(label); continue; }\n    writeRow_(t, e, { '代表者名': mt['代表者名'] || '', '代表者メール': mt['代表者メール'] || '', '地区': districtName_(mt['地区'] || e['地区']), 'リンク送信日時': '', '初回アクセス日時': '' });\n    fixed.push(label);\n  }\n  var msg = '直した枠：' + fixed.length + '件' + (fixed.length ? '\\n' + fixed.join('\\n') : '') +\n    (applied.length ? '\\n申込済みのため直していない枠（確認してください）：\\n' + applied.join('\\n') : '');\n  log_('代表者の修正', msg);\n  Logger.log(msg);\n  return msg;\n}\n\n\n/* ============================================================\n   第40回岩手県中学校インドアソフトテニス大会 システム\n   当日受付・領収書（フェーズ2）\n   - Code.gs と同じプロジェクトに「Reception.gs」として追加する\n   - 規約：ES5（var / function のみ）\n   ============================================================ */\n\nvar RECEIPT_GREEN = '#1a4a2e';\n\n/* ============================================================\n   受付API（受付パスワード または 管理パスワード）\n   ============================================================ */\nfunction receptionRoute_(body) {\n  var cfg = getConfig_();\n  var pw = String(body.pw || '');\n  if (!pw || (pw !== String(cfg['受付パスワード']) && pw !== String(cfg['管理パスワード']))) {\n    return { status: 'error', code: 'auth', message: 'パスワードが違います。' };\n  }\n  switch (body.action) {\n    case 'recLogin': return recLogin_(cfg);\n    case 'recList': return recList_(body);\n    case 'recLookup': return recLookup_(body);\n    case 'recConfirm': return recConfirm_(body, cfg);\n    case 'recCancel': return recCancel_(body);\n    default: return { status: 'error', message: '不明な受付アクション: ' + body.action };\n  }\n}\n\nfunction recLogin_(cfg) {\n  return {\n    status: 'ok', tournament: cfg['大会名'], divisions: DIVISIONS, divOrder: DIV_ORDER,\n    dates: { team: cfg['団体戦日程'], indiv: cfg['個人戦日程'] },\n    venues: { '男': cfg['男子会場'], '女': cfg['女子会場'] }\n  };\n}\n\n/* 区分の一覧（手動検索・集計用）。申込済みのみ */\nfunction recList_(body) {\n  var t = table_(SHEET_ENTRY);\n  var list = [];\n  var i, r;\n  for (i = 0; i < t.rows.length; i++) {\n    r = t.rows[i];\n    if (body.div && r['区分'] !== body.div) continue;\n    if (r['状態'] !== '申込済') continue;\n    list.push(recSummary_(r));\n  }\n  list.sort(function (a, b) { return districtCompare_(a.district, b.district) || String(a.teamName).localeCompare(String(b.teamName), 'ja'); });\n  return { status: 'ok', entries: list };\n}\n\nfunction recSummary_(r) {\n  var div = DIVISIONS[r['区分']];\n  return {\n    code: r['受付コード'], div: r['区分'], divName: div.name, teamName: r['チーム名'], abbr: r['略称'] || '',\n    district: districtName_(r['地区']), fee: toInt_(r['参加料']), pairCount: toInt_(r['ペア数']),\n    reception: r['受付状態'] || '', receptionAt: r['受付日時'] || '', staff: r['受付担当'] || ''\n  };\n}\n\n/* 受付コード（二次元コードの中身）で1件取得 */\nfunction recLookup_(body) {\n  var entry = findEntryByCode_(body.code);\n  if (!entry) return { status: 'error', code: 'notfound', message: 'この受付票は見つかりません。申込済みか確認してください。' };\n  if (entry['状態'] !== '申込済') return { status: 'error', code: 'notapplied', message: '「' + entry['チーム名'] + '」はまだ申込が完了していません。' };\n  var res = recSummary_(entry);\n  res.status = 'ok';\n  res.applicantName = entry['申込者氏名'];\n  res.applicantPhone = entry['申込者電話'];\n  res.payers = receiptAddressees_(entry);\n  if (DIVISIONS[entry['区分']].type === 'team') {\n    var players = parseJson_(entry['選手JSON'], []);\n    var names = [];\n    var i;\n    for (i = 0; i < players.length; i++) if (!players[i].vacant) names.push(players[i].no + '.' + players[i].name);\n    res.coach = entry['監督氏名'];\n    res.members = names;\n  } else {\n    var pairs = pairsForEntry_(entry);\n    var k;\n    res.members = [];\n    for (k = 0; k < pairs.length; k++) res.members.push(pairs[k].label);\n  }\n  return res;\n}\n\n/* 受付確定：現金受領 → 受付済み → 領収書PDF付きメール */\nfunction recConfirm_(body, cfg) {\n  var lock = LockService.getScriptLock();\n  if (!lock.tryLock(20000)) throw new Error('混み合っています。もう一度押してください。');\n  var entry;\n  try {\n    var t = table_(SHEET_ENTRY);\n    var code = normCode_(body.code);\n    var i;\n    entry = null;\n    for (i = 0; i < t.rows.length; i++) if (String(t.rows[i]['受付コード']) === code && code) entry = t.rows[i];\n    if (!entry) throw new Error('この受付票は見つかりません。');\n    if (entry['状態'] !== '申込済') throw new Error('まだ申込が完了していません。');\n    if (entry['受付状態'] === '受付済') {\n      return { status: 'error', code: 'already', message: 'すでに受付済みです（' + entry['受付日時'] + '　担当：' + (entry['受付担当'] || '—') + '）', entry: recSummary_(entry) };\n    }\n    writeRow_(t, entry, { '受付状態': '受付済', '受付日時': now_(), '受付担当': String(body.staff || '').slice(0, 20) });\n  } finally {\n    lock.releaseLock();\n  }\n  log_('受付', DIVISIONS[entry['区分']].name + '／' + entry['チーム名'] + '／' + toInt_(entry['参加料']) + '円／' + (body.staff || ''));\n  var mailError = '';\n  try {\n    sendReceptionMail_(entry, cfg);\n  } catch (err) {\n    mailError = err.message;\n    log_('mail-error', '受付完了メール ' + entry['チーム名'] + ': ' + err.message);\n  }\n  var res = recSummary_(entry);\n  return { status: 'ok', entry: res, mailError: mailError };\n}\n\nfunction recCancel_(body) {\n  var lock = LockService.getScriptLock();\n  lock.waitLock(20000);\n  try {\n    var t = table_(SHEET_ENTRY);\n    var code = normCode_(body.code);\n    var i;\n    for (i = 0; i < t.rows.length; i++) {\n      if (code && String(t.rows[i]['受付コード']) === code) {\n        writeRow_(t, t.rows[i], { '受付状態': '', '受付日時': '', '受付担当': '' });\n        log_('受付取消', t.rows[i]['チーム名'] + '／' + (body.staff || ''));\n        return { status: 'ok', entry: recSummary_(t.rows[i]) };\n      }\n    }\n    throw new Error('この受付票は見つかりません。');\n  } finally {\n    lock.releaseLock();\n  }\n}\n\nfunction normCode_(code) {\n  return String(code || '').replace(/^IWIN:/i, '').replace(/\\s/g, '');\n}\n\nfunction findEntryByCode_(code) {\n  var c = normCode_(code);\n  if (!c) return null;\n  var t = table_(SHEET_ENTRY);\n  var i;\n  for (i = 0; i < t.rows.length; i++) if (String(t.rows[i]['受付コード']) === c) return t.rows[i];\n  return null;\n}\n\n/* ============================================================\n   受付完了メール（申込責任者のみ・領収書PDF添付）\n   ============================================================ */\nfunction sendReceptionMail_(entry, cfg) {\n  var t = table_(SHEET_ENTRY);\n  var row = null;\n  var i;\n  for (i = 0; i < t.rows.length; i++) if (t.rows[i].entryId === entry.entryId) row = t.rows[i];\n  if (!row) throw new Error('申込データが見つかりません。');\n  var div = DIVISIONS[row['区分']];\n  var receipt = getReceiptBlob_(row, cfg);\n  var lines = [];\n  lines.push(row['チーム名'] + '　' + row['申込者氏名'] + ' 様');\n  lines.push('');\n  lines.push(cfg['大会名'] + '　' + div.name + 'の受付を完了しました。');\n  lines.push('参加料を受領しましたので、領収書（PDF）を添付します。');\n  lines.push('');\n  lines.push('■ 受付内容');\n  lines.push('　チーム名：' + row['チーム名']);\n  lines.push('　参加料：' + toInt_(row['参加料']).toLocaleString() + '円' + (div.type === 'indiv' ? '（' + toInt_(row['ペア数']) + 'ペア）' : ''));\n  lines.push('　受付日時：' + warekiDateTime_(row['受付日時']));\n  lines.push('　領収書番号：' + (row['領収書番号'] || ''));\n  lines.push('');\n  lines.push('※ 紙の領収書が必要な場合は、大会本部へお申し出ください。');\n  lines.push('');\n  lines.push('--');\n  lines.push(cfg['署名']);\n  MailApp.sendEmail({\n    to: row['申込者メール'],\n    subject: '【' + cfg['大会名'] + '】' + div.name + ' 受付完了・領収書（' + row['チーム名'] + '）',\n    body: lines.join('\\n'),\n    name: '岩手県中学生ソフトテニス連盟',\n    attachments: [receipt]\n  });\n  writeRow_(t, row, { '受付メール送信日時': now_() });\n}\n\n/* ============================================================\n   領収書\n   ============================================================ */\n\n/* 宛名：チーム名。個人戦で合同ペアがあれば相手チームも併記 */\nfunction receiptAddressees_(entry) {\n  var names = [entry['チーム名']];\n  if (DIVISIONS[entry['区分']].type === 'indiv') {\n    var pairs = pairsForEntry_(entry);\n    var i;\n    for (i = 0; i < pairs.length; i++) {\n      if (names.indexOf(pairs[i].aTeam) < 0) names.push(pairs[i].aTeam);\n      if (names.indexOf(pairs[i].bTeam) < 0) names.push(pairs[i].bTeam);\n    }\n  }\n  return names;\n}\n\n/* 領収書番号：区分ごとの連番（一度付けたら変えない） */\nfunction ensureReceiptNo_(t, row) {\n  if (row['領収書番号']) return row['領収書番号'];\n  var max = 0;\n  var i, m;\n  for (i = 0; i < t.rows.length; i++) {\n    m = String(t.rows[i]['領収書番号'] || '').match(new RegExp('^' + row['区分'] + '-(\\\\d+)$'));\n    if (m && toInt_(m[1]) > max) max = toInt_(m[1]);\n  }\n  var no = row['区分'] + '-' + ('00' + (max + 1)).slice(-3);\n  writeRow_(t, row, { '領収書番号': no });\n  return no;\n}\n\n/* 保存済みの領収書PDFを使う。なければ（または申込修正後なら）作り直して保存 */\nfunction getReceiptBlob_(row, cfg) {\n  var fresh = row['領収書ファイルID'] && String(row['領収書作成日時']) >= String(row['更新日時'] || row['申込日時']);\n  if (fresh) {\n    try {\n      return DriveApp.getFileById(row['領収書ファイルID']).getBlob();\n    } catch (err) {\n      log_('error', '領収書ファイルが開けないため再作成: ' + row['チーム名']);\n    }\n  }\n  return saveReceipt_(row, cfg);\n}\n\nfunction saveReceipt_(row, cfg) {\n  var t = table_(SHEET_ENTRY);\n  var target = null;\n  var i;\n  for (i = 0; i < t.rows.length; i++) if (t.rows[i].entryId === row.entryId) target = t.rows[i];\n  if (!target) throw new Error('申込データが見つかりません。');\n  ensureReceiptNo_(t, target);\n  var blob = buildReceiptPdf_([target], cfg, receiptFileName_(target, cfg));\n  var folder = receiptFolder_();\n  if (target['領収書ファイルID']) {\n    try { DriveApp.getFileById(target['領収書ファイルID']).setTrashed(true); } catch (e) { /* 古いファイルが無い場合は無視 */ }\n  }\n  var file = folder.createFile(blob);\n  writeRow_(t, target, { '領収書ファイルID': file.getId(), '領収書作成日時': now_() });\n  return file.getBlob();\n}\n\nfunction receiptFileName_(row, cfg) {\n  return '領収書_' + row['領収書番号'] + '_' + DIVISIONS[row['区分']].name + '_' + row['チーム名'] + '.pdf';\n}\n\nfunction receiptFolder_() {\n  var props = PropertiesService.getScriptProperties();\n  var id = props.getProperty('RECEIPT_FOLDER_ID');\n  if (id) {\n    try { return DriveApp.getFolderById(id); } catch (e) { /* 消されていたら作り直す */ }\n  }\n  var folder = DriveApp.createFolder('県インドア大会_領収書');\n  props.setProperty('RECEIPT_FOLDER_ID', folder.getId());\n  return folder;\n}\n\nfunction sealBlob_(cfg) {\n  var id = String(cfg['角印画像ファイルID'] || '').trim();\n  if (!id) return null;\n  var m = id.match(/[-\\w]{25,}/);\n  try {\n    return DriveApp.getFileById(m ? m[0] : id).getBlob();\n  } catch (err) {\n    log_('error', '角印画像を読み込めません: ' + err.message);\n    return null;\n  }\n}\n\n/* 領収書PDF（A5横・1件1ページ）。rows を複数渡すと印刷用にまとめる */\nfunction buildReceiptPdf_(rows, cfg, fileName) {\n  var doc = DocumentApp.create('領収書_tmp');\n  var fileId = doc.getId();\n  try {\n    var body = doc.getBody();\n    body.setPageWidth(595.28).setPageHeight(419.53);\n    body.setMarginTop(30).setMarginBottom(24).setMarginLeft(44).setMarginRight(44);\n    var seal = sealBlob_(cfg);\n    var i;\n    for (i = 0; i < rows.length; i++) {\n      if (i > 0) body.appendPageBreak();\n      appendReceipt_(body, rows[i], cfg, seal, i === 0);\n    }\n    doc.saveAndClose();\n    return DriveApp.getFileById(fileId).getAs(MimeType.PDF).setName(fileName);\n  } finally {\n    try { DriveApp.getFileById(fileId).setTrashed(true); } catch (e) { /* 削除失敗は無視 */ }\n  }\n}\n\nfunction appendReceipt_(body, row, cfg, seal, isFirst) {\n  var div = DIVISIONS[row['区分']];\n  var C = DocumentApp.HorizontalAlignment;\n  var dateText = String(div.type === 'team' ? cfg['団体戦日程'] : cfg['個人戦日程']).replace(/（.*?）/g, '');\n  var fee = toInt_(row['参加料']);\n\n  var top = isFirst ? body.getParagraphs()[0] : body.appendParagraph('');\n  top.setText('No. ' + (row['領収書番号'] || '') + '　　発行日　' + dateText);\n  pdfPara_(top, 9, false, C.RIGHT, 0, 2);\n\n  pdfPara_(body.appendParagraph('領　収　書'), 26, true, C.CENTER, 4, 16);\n\n  var names = receiptAddressees_(row);\n  var addr = body.appendParagraph(names.join(' 様、') + ' 様');\n  pdfPara_(addr, names.length > 1 ? 13 : 16, true, C.LEFT, 0, 14);\n  addr.editAsText().setUnderline(true);\n\n  var amount = body.appendTable([['金額', '￥' + fee.toLocaleString() + '－']]);\n  amount.setBorderColor('#333333').setBorderWidth(1);\n  amount.setColumnWidth(0, 70);\n  pdfCell_(amount.getRow(0).getCell(0), 12, true, '#e8f1eb', '#000000');\n  pdfCell_(amount.getRow(0).getCell(1), 22, true, '#ffffff', '#000000');\n  amount.getRow(0).getCell(0).getChild(0).asParagraph().setAlignment(C.CENTER);\n  amount.getRow(0).getCell(1).getChild(0).asParagraph().setAlignment(C.CENTER);\n  amount.getRow(0).getCell(0).setVerticalAlignment(DocumentApp.VerticalAlignment.CENTER);\n  amount.getRow(0).getCell(1).setVerticalAlignment(DocumentApp.VerticalAlignment.CENTER).setPaddingTop(8).setPaddingBottom(8);\n\n  var tadashi = '但し　' + cfg['大会名'] + '　' + div.name + '　参加料' +\n    (div.type === 'indiv' ? '（' + toInt_(row['ペア数']) + 'ペア分）' : '') + 'として';\n  pdfPara_(pdfNextPara_(body, tadashi), 11, false, C.LEFT, 14, 4);\n  pdfPara_(body.appendParagraph('上記正に領収いたしました。'), 11, false, C.LEFT, 0, 28);\n\n  /* 発行者（右寄せ）＋角印 */\n  var issuer = body.appendTable([[String(cfg['領収書発行者']) + '\\n' + String(cfg['領収書代表者']), '']]);\n  issuer.setBorderWidth(0);\n  issuer.setColumnWidth(0, 420);\n  issuer.setColumnWidth(1, 70);\n  var c0 = issuer.getRow(0).getCell(0);\n  pdfCell_(c0, 12, false, '#ffffff', '#000000');\n  var n = c0.getNumChildren();\n  var k;\n  for (k = 0; k < n; k++) c0.getChild(k).asParagraph().setAlignment(C.RIGHT);\n  var c1 = issuer.getRow(0).getCell(1);\n  pdfCell_(c1, 10, false, '#ffffff', '#000000');\n  if (seal) {\n    var img = c1.getChild(0).asParagraph().appendInlineImage(seal);\n    var w = img.getWidth();\n    var h = img.getHeight();\n    var size = 58;\n    if (w && h) img.setWidth(size).setHeight(Math.round(size * h / w));\n  }\n\n  var foot = pdfNextPara_(body, '受付コード：' + (row['受付コード'] || ''));\n  pdfPara_(foot, 7.5, false, C.RIGHT, 18, 0);\n  foot.editAsText().setForegroundColor('#666666');\n}\n\n/* ============================================================\n   管理画面から\n   ============================================================ */\nfunction findEntryRow_(entryId) {\n  var t = table_(SHEET_ENTRY);\n  var i;\n  for (i = 0; i < t.rows.length; i++) if (t.rows[i].entryId === entryId) return t.rows[i];\n  return null;\n}\n\n/* 1件の領収書PDF（ダウンロード用） */\nfunction adminReceiptPdf_(body, cfg) {\n  var row = findEntryRow_(body.entryId);\n  if (!row) throw new Error('申込データが見つかりません。');\n  if (row['状態'] !== '申込済') throw new Error('まだ申込されていません。');\n  var blob = getReceiptBlob_(row, cfg);\n  var latest = findEntryRow_(body.entryId);\n  return { status: 'ok', name: receiptFileName_(latest, cfg), base64: Utilities.base64Encode(blob.getBytes()) };\n}\n\n/* 領収書の事前一括作成。時間切れ前に区切り、残り件数を返す（画面側で繰り返し呼ぶ） */\nfunction adminReceiptBatch_(body, cfg) {\n  var started = new Date().getTime();\n  var t = table_(SHEET_ENTRY);\n  var targets = [];\n  var i, r;\n  for (i = 0; i < t.rows.length; i++) {\n    r = t.rows[i];\n    if (r['状態'] !== '申込済') continue;\n    if (body.div && r['区分'] !== body.div) continue;\n    if (r['領収書ファイルID'] && String(r['領収書作成日時']) >= String(r['更新日時'] || r['申込日時'])) continue;\n    targets.push(r);\n  }\n  var done = 0;\n  for (i = 0; i < targets.length; i++) {\n    if (new Date().getTime() - started > 240000) break;\n    saveReceipt_(targets[i], cfg);\n    done++;\n  }\n  log_('領収書作成', done + '件');\n  return { status: 'ok', done: done, remaining: targets.length - done };\n}\n\n/* 区分別の印刷用PDF（A5横・1件1ページ） */\nfunction adminReceiptPrint_(body, cfg) {\n  var div = DIVISIONS[body.div];\n  if (!div) throw new Error('区分を指定してください。');\n  var t = table_(SHEET_ENTRY);\n  var rows = [];\n  var i;\n  for (i = 0; i < t.rows.length; i++) {\n    if (t.rows[i]['区分'] === body.div && t.rows[i]['状態'] === '申込済') rows.push(t.rows[i]);\n  }\n  if (rows.length === 0) throw new Error(div.name + 'の申込はまだありません。');\n  rows.sort(function (a, b) { return districtCompare_(a['地区'], b['地区']) || String(a['チーム名']).localeCompare(String(b['チーム名']), 'ja'); });\n  for (i = 0; i < rows.length; i++) ensureReceiptNo_(t, rows[i]);\n  var name = cfg['大会名'] + '_' + div.name + '_領収書（印刷用）.pdf';\n  var blob = buildReceiptPdf_(rows, cfg, name);\n  return { status: 'ok', name: name, base64: Utilities.base64Encode(blob.getBytes()), count: rows.length };\n}\n\n/* 受付完了メールの再送（メール失敗時など） */\nfunction adminResendReceipt_(body, cfg) {\n  var row = findEntryRow_(body.entryId);\n  if (!row) throw new Error('申込データが見つかりません。');\n  if (row['受付状態'] !== '受付済') throw new Error('まだ受付が済んでいません。');\n  sendReceptionMail_(row, cfg);\n  return { status: 'ok' };\n}\n\n/* ============================================================\n   選手変更（本部・管理画面から）\n   要項11(3)：個人戦は1名のみ、団体戦はやむを得ない場合。届出は紙で本部へ\n   ============================================================ */\nfunction changeLog_() {\n  var sh = ss_().getSheetByName(SHEET_CHANGE);\n  if (!sh) return [];\n  var t = table_(SHEET_CHANGE);\n  var out = [];\n  var i, r;\n  for (i = t.rows.length - 1; i >= 0; i--) {\n    r = t.rows[i];\n    out.push({ at: r['日時'], div: r['区分'], team: r['チーム'], target: r['対象'], from: r['変更前'], to: r['変更後'], offRoster: r['名簿外'] === '○', reason: r['理由'] });\n  }\n  return out;\n}\n\nfunction addChangeLog_(divCode, team, target, from, to, offRoster, reason, publicReason) {\n  var sh = ss_().getSheetByName(SHEET_CHANGE);\n  if (!sh) throw new Error('シート「選手変更」がありません。setup() を実行してください。');\n  if (publicReason) ensureHeaders_(sh, HEADERS[SHEET_CHANGE]);\n  appendObj_(table_(SHEET_CHANGE), {\n    '日時': now_(), '区分': DIVISIONS[divCode].name, 'チーム': team, '対象': target,\n    '変更前': from, '変更後': to, '名簿外': offRoster ? '○' : '', '理由': String(reason || '').slice(0, 100),\n    '理由公開': publicReason ? '○' : ''\n  });\n  log_('選手変更', DIVISIONS[divCode].name + '／' + team + '／' + target + '：' + from + ' → ' + to);\n}\n\n/* 団体戦：番号（1〜8）の選手を差し替える、または欠員にする */\nfunction adminChangeTeamPlayer_(body) {\n  var lock = LockService.getScriptLock();\n  lock.waitLock(20000);\n  try {\n    var t = table_(SHEET_ENTRY);\n    var entry = null;\n    var i;\n    for (i = 0; i < t.rows.length; i++) if (t.rows[i].entryId === body.entryId) entry = t.rows[i];\n    if (!entry) throw new Error('申込データが見つかりません。');\n    var div = DIVISIONS[entry['区分']];\n    if (div.type !== 'team') throw new Error('団体戦の申込ではありません。');\n    if (entry['状態'] !== '申込済') throw new Error('まだ申込されていません。');\n    var slot = toInt_(body.slot);\n    if (slot < 1 || slot > 8) throw new Error('番号（1〜8）を選んでください。');\n    var players = parseJson_(entry['選手JSON'], []);\n    var cur = players[slot - 1] || { no: slot, vacant: true };\n    var fromName = cur.vacant ? '（欠員）' : cur.name;\n    var rec;\n    if (body.mode === 'vacant') {\n      if (cur.vacant) throw new Error('No.' + slot + 'はすでに欠員です。');\n      rec = { no: slot, vacant: true, changedFrom: fromName };\n    } else {\n      requireText_(body.name, '交代する選手の氏名');\n      requireText_(body.grade, '交代する選手の学年');\n      var key = normName_(body.name);\n      for (i = 0; i < players.length; i++) {\n        if (i !== slot - 1 && players[i] && !players[i].vacant && normName_(players[i].name) === key) {\n          throw new Error('「' + body.name + '」はすでにNo.' + (i + 1) + 'に登録されています。');\n        }\n      }\n      var roster = rosterFor_(entry['チーム名'], div.gender);\n      var onRoster = false;\n      for (i = 0; i < roster.length; i++) if (normName_(roster[i].name) === key) onRoster = true;\n      rec = { no: slot, name: String(body.name).trim(), grade: body.grade, offRoster: !onRoster, changedFrom: fromName };\n    }\n    /* 何度変更しても「元の選手」を残す。元の選手に戻したら変更なしに戻す */\n    if (cur.changedFrom) rec.changedFrom = cur.changedFrom;\n    if (!rec.vacant && rec.changedFrom && normName_(rec.changedFrom) === normName_(rec.name)) delete rec.changedFrom;\n    if (rec.vacant && rec.changedFrom === '（欠員）') delete rec.changedFrom;\n    if (body.dryRun) return { status: 'ok', team: entry['チーム名'], target: 'No.' + slot, from: fromName, to: rec.vacant ? '（欠員）' : rec.name + '（' + rec.grade + '）', offRoster: !!rec.offRoster };\n    players[slot - 1] = rec;\n    var count = 0;\n    for (i = 0; i < players.length; i++) if (players[i] && !players[i].vacant) count++;\n    var update = { '選手JSON': JSON.stringify(players) };\n    if (rec.offRoster) {\n      update['要確認'] = (entry['要確認'] ? entry['要確認'] + ' / ' : '') + 'No.' + slot + ' ' + rec.name + ' は登録名簿にない（選手変更）';\n    }\n    writeRow_(t, entry, update);\n    addChangeLog_(entry['区分'], entry['チーム名'], 'No.' + slot, fromName, rec.vacant ? '（欠員）' : rec.name + '（' + rec.grade + '）', !!rec.offRoster, body.reason);\n    var orderNote = cur.vacant ? [] : fixOrdersAfterChange_(entry, cur.name, rec.vacant ? '' : rec.name);\n    return { status: 'ok', count: count, orderNote: orderNote };\n  } finally {\n    lock.releaseLock();\n  }\n}\n\n/* 個人戦：ペアの1名を同じチームの選手と交代（1ペアにつき1名まで） */\nfunction adminChangePairPlayer_(body) {\n  var lock = LockService.getScriptLock();\n  lock.waitLock(20000);\n  try {\n    return changePairPlayerCore_(body);\n  } finally {\n    lock.releaseLock();\n  }\n}\n\n/* 個人戦：ペアの1名を交代（ロックは呼び出し側。1ペアにつき1名まで） */\nfunction changePairPlayerCore_(body) {\n  {\n    var pt = table_(SHEET_PAIR);\n    var pr = null;\n    var i;\n    for (i = 0; i < pt.rows.length; i++) if (pt.rows[i].pairId === body.pairId) pr = pt.rows[i];\n    if (!pr) throw new Error('ペアが見つかりません。');\n    var side = body.side === 'B' ? 'B' : 'A';\n    var other = side === 'A' ? 'B' : 'A';\n    var log = parseJson_(pr['変更記録'], null);\n    if (log && log.side !== side) {\n      throw new Error('このペアはすでに選手' + log.side + '（' + log.from + '）を変更済みです。個人戦の選手変更は1名のみです。');\n    }\n    requireText_(body.name, '交代する選手の氏名');\n    requireText_(body.grade, '交代する選手の学年');\n    var team = pr[side + '所属'];\n    var fromName = pr[side + '氏名'];\n    var key = normName_(body.name);\n    if (normName_(pr[other + '氏名']) === key) throw new Error('ペアの相手と同じ選手です。');\n    for (i = 0; i < pt.rows.length; i++) {\n      var q = pt.rows[i];\n      if (q.pairId === pr.pairId || q['区分'] !== pr['区分']) continue;\n      if ((normName_(q['A氏名']) === key && q['A所属'] === team) || (normName_(q['B氏名']) === key && q['B所属'] === team)) {\n        throw new Error('「' + body.name + '」は別のペアで出場しています。');\n      }\n    }\n    var roster = rosterFor_(team, DIVISIONS[pr['区分']].gender);\n    var onRoster = false;\n    for (i = 0; i < roster.length; i++) if (normName_(roster[i].name) === key) onRoster = true;\n    var origin = log ? log.from : fromName;\n    var pairLabel = pr['A氏名'] + '・' + pr['B氏名'];\n    if (body.dryRun) return { status: 'ok', team: team, target: 'ペア（' + pairLabel + '）の選手' + side, from: fromName, to: String(body.name).trim() + '（' + body.grade + '）', offRoster: !onRoster };\n    var update = {};\n    update[side + '氏名'] = String(body.name).trim();\n    update[side + '学年'] = body.grade;\n    /* 元の選手に戻した場合は「変更なし」に戻す */\n    update['変更記録'] = normName_(origin) === key ? '' : JSON.stringify({ side: side, from: origin, at: now_() });\n    writeRow_(pt, pr, update);\n    addChangeLog_(pr['区分'], team, 'ペア（' + pairLabel + '）の選手' + side,\n      fromName, String(body.name).trim() + '（' + body.grade + '）', !onRoster, body.reason, body.publicReason);\n    return { status: 'ok' };\n  }\n}\n\n/* 団体戦の選手変更のあと、終わっていない試合のオーダーを直す\n   交代：元の選手の名前を新しい選手に置き換える／欠員：置き換えず、本部が訂正する試合を返す */\nfunction fixOrdersAfterChange_(entry, oldName, newName) {\n  var notes = [];\n  var ms = loadMatches_(entry['区分']);\n  var byId = {};\n  var i, j, k, m, side, o, hit, changed, upd;\n  for (i = 0; i < ms.length; i++) byId[ms[i].id] = ms[i];\n  var key = normName_(oldName);\n  for (i = 0; i < ms.length; i++) {\n    m = ms[i];\n    if (m.state === '終了') continue;\n    var sides = [['L', m.left, m.orderL, 'オーダー左'], ['R', m.right, m.orderR, 'オーダー右']];\n    for (j = 0; j < 2; j++) {\n      side = sides[j];\n      o = side[2];\n      if (!o || !o.p || resolveRef_(side[1], byId, {}, 0) !== entry.entryId) continue;\n      changed = false;\n      for (k = 0; k < o.p.length; k++) {\n        if (!o.p[k]) continue;\n        if (normName_(o.p[k][0]) === key) { if (newName) { o.p[k][0] = newName; changed = true; } else notes.push('第' + m.no + '試合'); }\n        if (normName_(o.p[k][1]) === key) { if (newName) { o.p[k][1] = newName; changed = true; } else notes.push('第' + m.no + '試合'); }\n      }\n      if (changed) {\n        hit = matchRow_(m.id);\n        upd = { '更新日時': now_() };\n        upd[side[3]] = JSON.stringify(o);\n        writeRow_(hit.t, hit.row, upd);\n        notes.push('第' + m.no + '試合のオーダーを「' + oldName + '」→「' + newName + '」に置き換え');\n      }\n    }\n  }\n  if (!newName && notes.length) notes = ['欠員にした「' + oldName + '」が' + notes.join('・') + 'のオーダーに入っています。本部の「オーダー」から訂正してください。'];\n  return notes;\n}\n\n/* 監督（ベンチ入り指導者）の変更：団体戦は entryId、個人戦は pairId */\nfunction adminChangeCoach_(body) {\n  requireText_(body.name, '新しい監督の氏名');\n  requireText_(body.title, '新しい監督の役職');\n  var name = String(body.name).trim();\n  var lock = LockService.getScriptLock();\n  lock.waitLock(20000);\n  try {\n    var i;\n    if (body.pairId) {\n      var pt = table_(SHEET_PAIR);\n      var pr = null;\n      for (i = 0; i < pt.rows.length; i++) if (pt.rows[i].pairId === body.pairId) pr = pt.rows[i];\n      if (!pr) throw new Error('ペアが見つかりません。');\n      var fromP = (pr['監督氏名'] || '（未登録）') + (pr['監督役職'] ? '（' + pr['監督役職'] + '）' : '');\n      var target = 'ペア（' + pr['A氏名'] + '・' + pr['B氏名'] + '）の監督';\n      if (normName_(pr['監督氏名']) === normName_(name) && pr['監督役職'] === body.title) throw new Error('今の監督と同じです。');\n      if (body.dryRun) return { status: 'ok', team: pr['支払チーム'], target: target, from: fromP, to: name + '（' + body.title + '）' };\n      writeRow_(pt, pr, { '監督氏名': name, '監督役職': body.title });\n      addChangeLog_(pr['区分'], pr['支払チーム'], target, fromP, name + '（' + body.title + '）', false, body.reason);\n      return { status: 'ok' };\n    }\n    var t = table_(SHEET_ENTRY);\n    var entry = null;\n    for (i = 0; i < t.rows.length; i++) if (t.rows[i].entryId === body.entryId) entry = t.rows[i];\n    if (!entry) throw new Error('申込データが見つかりません。');\n    if (DIVISIONS[entry['区分']].type !== 'team') throw new Error('個人戦はペアを指定してください。');\n    var from = (entry['監督氏名'] || '（未登録）') + (entry['監督役職'] ? '（' + entry['監督役職'] + '）' : '');\n    if (normName_(entry['監督氏名']) === normName_(name) && entry['監督役職'] === body.title) throw new Error('今の監督と同じです。');\n    if (body.dryRun) return { status: 'ok', team: entry['チーム名'], target: '監督', from: from, to: name + '（' + body.title + '）' };\n    writeRow_(t, entry, { '監督氏名': name, '監督役職': body.title });\n    addChangeLog_(entry['区分'], entry['チーム名'], '監督', from, name + '（' + body.title + '）', false, body.reason);\n    return { status: 'ok' };\n  } finally {\n    lock.releaseLock();\n  }\n}\n\n/* ============================================================\n   変更申請（監督がスマホから申請 → 競技委員長が許可・却下 → 許可で自動反映）\n   ============================================================ */\nvar REQ_KINDS = { player: '選手変更', vacant: '欠員報告', coach: '監督変更' };\n\nfunction reqTable_() {\n  var ss = ss_();\n  var sh = ss.getSheetByName(SHEET_REQ);\n  if (!sh) {\n    sh = ss.insertSheet(SHEET_REQ);\n    sh.getRange(1, 1, 1, HEADERS[SHEET_REQ].length).setValues([HEADERS[SHEET_REQ]]).setFontWeight('bold');\n  }\n  return table_(SHEET_REQ);\n}\n\nfunction reqObj_(r) {\n  var c = parseJson_(r['内容'], {});\n  return {\n    id: r['申請ID'], at: r['日時'], div: r['区分'], divName: DIVISIONS[r['区分']] ? DIVISIONS[r['区分']].name : r['区分'],\n    entryId: r.entryId, team: r['チーム'], kind: r['種別'], target: r['対象'], from: c.from || '', to: c.to || '',\n    offRoster: !!c.offRoster, reason: r['理由'], state: r['状態'] || '申請中', decidedAt: r['処理日時'] || '', comment: r['コメント'] || '', by: r['申請者'] || ''\n  };\n}\n\n/* 申請を、既存の変更関数の引数に組み立てる */\nfunction reqApplyBody_(entry, p) {\n  var b = { kind: p.kind, reason: p.reason };\n  var div = DIVISIONS[entry['区分']];\n  if (p.kind === 'coach') {\n    if (div.type === 'team') b.entryId = entry.entryId; else b.pairId = p.pairId;\n    b.name = p.name; b.title = p.title;\n  } else if (div.type === 'team') {\n    b.entryId = entry.entryId; b.slot = p.slot; b.mode = p.kind === 'vacant' ? 'vacant' : 'replace'; b.name = p.name; b.grade = p.grade;\n  } else {\n    if (p.kind !== 'player') throw new Error('個人戦の申請は「選手変更」か「監督変更」です。');\n    b.pairId = p.pairId; b.side = p.side; b.name = p.name; b.grade = p.grade;\n  }\n  return b;\n}\n\nfunction reqRun_(entry, b) {\n  var div = DIVISIONS[entry['区分']];\n  if (b.kind === 'coach') return adminChangeCoach_(b);\n  if (div.type === 'team') return adminChangeTeamPlayer_(b);\n  /* 個人戦：自チームが支払うペアに限る */\n  var ps = pairsForEntry_(entry);\n  var ok = false;\n  var i;\n  for (i = 0; i < ps.length; i++) if (ps[i].pairId === b.pairId) ok = true;\n  if (!ok) throw new Error('このチームのペアではありません。');\n  return adminChangePairPlayer_(b);\n}\n\n/* 変更申請の締切：その区分の大会当日の受付終了時刻（設定「受付時刻」の終わり。例 7:35〜8:00 → 8:00） */\nfunction changeDeadline_(cfg, div) {\n  var day = String(div.type === 'team' ? cfg['団体戦日程'] : cfg['個人戦日程']);\n  var y, mo, d;\n  var m = day.match(/令和\\s*(\\d+)\\s*年\\s*(\\d+)\\s*月\\s*(\\d+)\\s*日/);\n  if (m) { y = 2018 + toInt_(m[1]); mo = toInt_(m[2]); d = toInt_(m[3]); }\n  else {\n    m = day.match(/(\\d{4})[-\\/年](\\d{1,2})[-\\/月](\\d{1,2})/);\n    if (!m) return null;\n    y = toInt_(m[1]); mo = toInt_(m[2]); d = toInt_(m[3]);\n  }\n  var times = String(cfg['受付時刻'] || '8:00').match(/(\\d{1,2}):(\\d{2})/g);\n  var end = times ? times[times.length - 1] : '8:00';\n  var hm = end.split(':');\n  var z = function (n) { return (n < 10 ? '0' : '') + n; };\n  return parseJst_(y + '-' + z(mo) + '-' + z(d) + ' ' + z(toInt_(hm[0])) + ':' + hm[1]);\n}\n\nfunction changePeriod_(cfg, div) {\n  var nowT = new Date().getTime();\n  var start = parseJst_(cfg['申込締切']);\n  var end = changeDeadline_(cfg, div);\n  var endText = end ? Utilities.formatDate(end, 'Asia/Tokyo', 'M月d日 H:mm') : '';\n  if (start && nowT < start.getTime()) {\n    return { open: false, before: true, deadline: endText, message: '申込締切（' + warekiDateTime_(cfg['申込締切']) + '）までは、申込フォームから直接修正できます。変更申請は締切後に使います。' };\n  }\n  if (end && nowT > end.getTime()) {\n    return { open: false, after: true, deadline: endText, message: '変更申請の受付は、大会当日の受付終了（' + endText + '）で締め切りました。' };\n  }\n  return { open: true, deadline: endText, message: '' };\n}\n\n/* 監督用：変更申請ページのデータ */\nfunction changeInfo_(token) {\n  var entry = findEntryByToken_(token);\n  if (!entry) return { status: 'error', message: 'リンクが無効です。受付票のボタンから開いてください。' };\n  var cfg = getConfig_();\n  var div = DIVISIONS[entry['区分']];\n  var res = {\n    status: 'ok', tournament: cfg['大会名'], division: div.name, type: div.type, team: entry['チーム名'], applied: entry['状態'] === '申込済',\n    period: changePeriod_(cfg, div), entryUrl: siteUrl_(cfg) + (div.type === 'team' ? 'entry-team.html' : 'entry-individual.html') + '?t=' + entry['トークン'],\n    requests: []\n  };\n  var i;\n  if (div.type === 'team') {\n    var ps = parseJson_(entry['選手JSON'], []);\n    res.coach = { name: entry['監督氏名'] || '', title: entry['監督役職'] || '' };\n    res.players = [];\n    for (i = 0; i < 8; i++) {\n      var p = ps[i] || { no: i + 1, vacant: true };\n      res.players.push({ no: i + 1, name: p.vacant ? '' : p.name, grade: p.vacant ? '' : p.grade, vacant: !!p.vacant, changedFrom: p.changedFrom || '' });\n    }\n    res.roster = rosterFor_(entry['チーム名'], div.gender);\n  } else {\n    var pairs = pairsForEntry_(entry);\n    res.pairs = [];\n    res.rosters = {};\n    for (i = 0; i < pairs.length; i++) {\n      var q = pairs[i];\n      res.pairs.push({ pairId: q.pairId, label: q.label, a: { name: q.aName, grade: q.aGrade, team: q.aTeam }, b: { name: q.bName, grade: q.bGrade, team: q.bTeam },\n        coach: { name: q.coachName || '', title: q.coachTitle || '' }, change: q.change });\n      if (!res.rosters[q.aTeam]) res.rosters[q.aTeam] = rosterFor_(q.aTeam, div.gender);\n      if (!res.rosters[q.bTeam]) res.rosters[q.bTeam] = rosterFor_(q.bTeam, div.gender);\n    }\n  }\n  var rt = reqTable_();\n  for (i = rt.rows.length - 1; i >= 0; i--) if (rt.rows[i].entryId === entry.entryId) res.requests.push(reqObj_(rt.rows[i]));\n  return res;\n}\n\n/* 監督用：変更を申請する（内容はここで検証し、反映は許可のとき） */\nfunction apiChangeRequest_(body) {\n  var entry = findEntryByToken_(body.t);\n  if (!entry) throw new Error('リンクが無効です。');\n  if (entry['状態'] !== '申込済') throw new Error('申込が済んでいないため、変更申請はできません。');\n  var cfg = getConfig_();\n  var period = changePeriod_(cfg, DIVISIONS[entry['区分']]);\n  if (!period.open) throw new Error(period.message);\n  if (!REQ_KINDS[body.kind]) throw new Error('申請の種類を選んでください。');\n  requireText_(body.reason, '変更の理由');\n  var b = reqApplyBody_(entry, body);\n  b.dryRun = true;\n  var check = reqRun_(entry, b);\n  var rt = reqTable_();\n  var i;\n  for (i = 0; i < rt.rows.length; i++) {\n    if (rt.rows[i].entryId === entry.entryId && rt.rows[i]['状態'] === '申請中' && rt.rows[i]['対象'] === check.target) {\n      throw new Error('「' + check.target + '」の申請が確認待ちです。結果が出るまでお待ちください。');\n    }\n  }\n  var params = { kind: body.kind, slot: body.slot || '', pairId: body.pairId || '', side: body.side || '', name: body.name || '', grade: body.grade || '', title: body.title || '',\n    from: check.from, to: check.to, offRoster: !!check.offRoster };\n  var id = 'R' + newCode_(6);\n  appendObj_(rt, {\n    '申請ID': id, '日時': now_(), '区分': entry['区分'], entryId: entry.entryId, 'チーム': entry['チーム名'], '種別': REQ_KINDS[body.kind],\n    '対象': check.target, '内容': JSON.stringify(params), '理由': String(body.reason).slice(0, 200), '状態': '申請中', '申請者': String(body.by || '').slice(0, 40)\n  });\n  log_('変更申請', DIVISIONS[entry['区分']].name + '／' + entry['チーム名'] + '／' + check.target + '：' + check.from + ' → ' + check.to);\n  var to = String(cfg['変更申請の通知先'] || '').trim();\n  if (to) {\n    try {\n      MailApp.sendEmail({ to: to, subject: '【変更申請】' + DIVISIONS[entry['区分']].name + '　' + entry['チーム名'],\n        body: DIVISIONS[entry['区分']].name + '　' + entry['チーム名'] + '\\n' + REQ_KINDS[body.kind] + '：' + check.target + '\\n' + check.from + ' → ' + check.to +\n          (check.offRoster ? '（登録名簿にない選手）' : '') + '\\n理由：' + body.reason + '\\n\\n管理画面「選手変更」で許可・却下してください。\\n' + siteUrl_(cfg) + 'admin.html',\n        name: '県インドア大会システム' });\n    } catch (e) { log_('mail-error', '変更申請の通知: ' + e.message); }\n  }\n  return { status: 'ok', id: id };\n}\n\n/* 競技委員長：許可・却下 */\nfunction adminChangeDecide_(body) {\n  var rt = reqTable_();\n  var row = null;\n  var i;\n  for (i = 0; i < rt.rows.length; i++) if (rt.rows[i]['申請ID'] === body.id) row = rt.rows[i];\n  if (!row) throw new Error('申請が見つかりません。');\n  if (row['状態'] !== '申請中') throw new Error('この申請はすでに「' + row['状態'] + '」です。');\n  var t = table_(SHEET_ENTRY);\n  var entry = null;\n  for (i = 0; i < t.rows.length; i++) if (t.rows[i].entryId === row.entryId) entry = t.rows[i];\n  if (!entry) throw new Error('申込データが見つかりません。');\n  var approve = body.decision === 'approve';\n  var comment = String(body.comment || '').slice(0, 200);\n  if (!approve && !comment) throw new Error('却下の理由（監督に伝える内容）を入力してください。');\n  var result = { status: 'ok' };\n  if (approve) {\n    var p = parseJson_(row['内容'], {});\n    p.reason = '申請：' + row['理由'];\n    result = reqRun_(entry, reqApplyBody_(entry, p));\n  }\n  writeRow_(rt, row, { '状態': approve ? '許可' : '却下', '処理日時': now_(), 'コメント': comment });\n  log_('変更申請', (approve ? '許可' : '却下') + '：' + row['チーム'] + '／' + row['対象']);\n  try { sendChangeResultMail_(entry, reqObj_(row), getConfig_()); } catch (e) { log_('mail-error', '変更申請の結果: ' + e.message); }\n  return { status: 'ok', orderNote: result.orderNote || [] };\n}\n\nfunction sendChangeResultMail_(entry, r, cfg) {\n  var to = entry['申込者メール'] || entry['代表者メール'];\n  if (!to) return;\n  var ok = r.state === '許可';\n  var lines = [];\n  lines.push(entry['チーム名'] + '　ご担当者 様');\n  lines.push('');\n  lines.push(cfg['大会名'] + '　' + r.divName + 'の変更申請について、競技委員長が' + (ok ? '許可しました。' : '却下しました。'));\n  lines.push('');\n  lines.push('■ ' + r.kind + '：' + r.target);\n  lines.push('　' + r.from + ' → ' + r.to);\n  if (r.comment) lines.push('■ 競技委員長から：' + r.comment);\n  lines.push('');\n  lines.push(ok ? '変更は進行表・組合せ・オーダー画面などに反映されています。' : '内容を確認のうえ、必要であれば大会本部へご相談ください。');\n  lines.push('');\n  lines.push('--');\n  lines.push(cfg['署名']);\n  MailApp.sendEmail({ to: to, subject: '【' + cfg['大会名'] + '】変更申請の結果（' + (ok ? '許可' : '却下') + '）', body: lines.join('\\n'), name: '岩手県中学生ソフトテニス連盟' });\n}\n\nfunction changeRequests_() {\n  var sh = ss_().getSheetByName(SHEET_REQ);\n  if (!sh) return [];\n  var rt = table_(SHEET_REQ);\n  var out = [];\n  var i;\n  for (i = rt.rows.length - 1; i >= 0; i--) out.push(reqObj_(rt.rows[i]));\n  return out;\n}\n\n/* 公開用：選手変更一覧（変更前・変更後。理由と名簿外の印は出さない。監督の変更も氏名を出す＝申込フォームの同意の範囲） */\nfunction publicChanges_(divCode) {\n  var sh = ss_().getSheetByName(SHEET_CHANGE);\n  if (!sh) return [];\n  var t = table_(SHEET_CHANGE);\n  var name = divCode && DIVISIONS[divCode] ? DIVISIONS[divCode].name : '';\n  var out = [];\n  var i, r;\n  for (i = 0; i < t.rows.length; i++) {\n    r = t.rows[i];\n    if (name && r['区分'] !== name) continue;\n    var isCoach = /監督/.test(String(r['対象']));\n    /* 監督は氏名だけ（役職は出さない） */\n    var strip = function (v) { return isCoach ? String(v || '').replace(/（[^（）]*）$/, '') : v; };\n    out.push({ at: String(r['日時']).slice(5, 16), div: r['区分'], team: r['チーム'], target: r['対象'], from: strip(r['変更前']), to: strip(r['変更後']),\n      note: r['理由公開'] === '○' ? String(r['理由'] || '').replace(/^申請：/, '') : '' });\n  }\n  return out;\n}\n\n/* ============================================================\n   申込時の選手変更（競技委員会承認）：委員長が対象ペアに設定 → 監督が申込フォームで代わりの選手を選ぶ\n   → 申込の送信で選手変更として記録（1ペア1名の枠を使う）。理由は選手変更一覧に載せられる\n   ============================================================ */\nfunction adminSetPreChange_(body) {\n  var pt = table_(SHEET_PAIR);\n  var pr = null;\n  var i;\n  for (i = 0; i < pt.rows.length; i++) if (pt.rows[i].pairId === body.pairId) pr = pt.rows[i];\n  if (!pr) throw new Error('ペアが見つかりません。');\n  if (!body.side) {\n    writeRow_(pt, pr, { '申込時変更': '' });\n    log_('申込時変更', '解除：' + pr['A氏名'] + '・' + pr['B氏名']);\n    return { status: 'ok' };\n  }\n  var side = body.side === 'B' ? 'B' : 'A';\n  var log = parseJson_(pr['変更記録'], null);\n  if (log && log.side !== side) throw new Error('このペアはすでに選手' + log.side + 'を変更済みです（1ペア1名まで）。');\n  requireText_(body.reason, '理由');\n  writeRow_(pt, pr, { '申込時変更': JSON.stringify({ side: side, reason: String(body.reason).slice(0, 100), pub: !!body.publicReason }) });\n  log_('申込時変更', DIVISIONS[pr['区分']].name + '：' + pr['A氏名'] + '・' + pr['B氏名'] + '／選手' + side + '／' + body.reason);\n  return { status: 'ok' };\n}\n\n\n/* ============================================================\n   第40回岩手県中学校インドアソフトテニス大会 システム\n   組合せ・進行表（フェーズ3）\n   - Code.gs と同じプロジェクトに「Progress.gs」として追加する\n   - 規約：ES5（var / function のみ）\n   ============================================================ */\n\nvar BLOCKS = ['A', 'B', 'C', 'D'];\n/* 予選リーグ（4ペア総当たり）の試合順：1-2、3-4、1-3、2-4、2-3、1-4 */\nvar LEAGUE_ROUNDS = [[[1, 2], [3, 4]], [[1, 3], [2, 4]], [[2, 3], [1, 4]]];\n/* 決勝トーナメント：A1位-C2位、D2位-B1位、C1位-A2位、B2位-D1位 */\nvar KO_QF = [['A1', 'C2'], ['D2', 'B1'], ['C1', 'A2'], ['B2', 'D1']];\nvar STATES = ['待機', '呼出', '試合中', '終了'];\n/* 予選リーグの審判（リーグ内）：試合（枠番号の組）→ 審判をする枠番号。各ペア1〜2回 */\nvar LEAGUE_REFS = { '12': 3, '34': 1, '13': 4, '24': 1, '23': 4, '14': 2 };\n\nfunction drawSlots_(divCode) {\n  var div = DIVISIONS[divCode];\n  var out = [];\n  var i, j;\n  if (div.type === 'team') {\n    for (i = 1; i <= 16; i++) out.push(String(i));\n  } else {\n    for (i = 0; i < BLOCKS.length; i++) for (j = 1; j <= 4; j++) out.push(BLOCKS[i] + j);\n  }\n  return out;\n}\n\n/* ============================================================\n   表示名\n   ============================================================ */\nfunction surname_(name) {\n  var s = String(name || '').trim();\n  var m = s.split(/[\\s　]+/);\n  return m.length > 1 ? m[0] : s;\n}\n\nfunction plainName_(name) { return String(name || '').replace(/[\\s　]+/g, ''); }\n\nfunction gradeCirc_(g) { return ['', '①', '②', '③'][toInt_(g)] || ''; }\n\nfunction teamShort_(entryRow) {\n  if (!entryRow) return '';\n  return entryRow['略称'] || suggestAbbr_(entryRow['チーム名']);\n}\n\n/* 区分の参加者（チーム・ペア）の表示情報 */\nfunction participants_(divCode) {\n  var div = DIVISIONS[divCode];\n  var t = table_(SHEET_ENTRY);\n  var abbrOf = {};\n  var out = {};\n  var i, r;\n  for (i = 0; i < t.rows.length; i++) {\n    r = t.rows[i];\n    if (r['区分'] === divCode) abbrOf[r['チーム名']] = teamShort_(r);\n    if (div.type === 'team' && r['区分'] === divCode) {\n      out[r.entryId] = { id: r.entryId, label: teamShort_(r), full: r['チーム名'], sub: districtName_(r['地区']), state: r['状態'] || '未申込' };\n    }\n  }\n  if (div.type === 'indiv') {\n    var pt = table_(SHEET_PAIR);\n    for (i = 0; i < pt.rows.length; i++) {\n      r = pt.rows[i];\n      if (r['区分'] !== divCode) continue;\n      var ta = abbrOf[r['A所属']] || suggestAbbr_(r['A所属']);\n      var tb = abbrOf[r['B所属']] || suggestAbbr_(r['B所属']);\n      out[r.pairId] = {\n        id: r.pairId,\n        /* 表示はフルネーム（登録名簿の空白の有無で表記が変わらないよう、空白を除いて統一） */\n        label: plainName_(r['A氏名']) + '・' + plainName_(r['B氏名']),\n        labelG: plainName_(r['A氏名']) + gradeCirc_(r['A学年']) + '・' + plainName_(r['B氏名']) + gradeCirc_(r['B学年']),\n        full: r['A氏名'] + '・' + r['B氏名'],\n        sub: ta === tb ? ta : ta + '／' + tb,\n        state: '',\n        names: [r['A氏名'], r['B氏名']],\n        grades: [r['A学年'], r['B学年']],\n        teams: [ta, tb],\n        teamsFull: [r['A所属'], r['B所属']],\n        changed: r['変更記録'] ? 1 : 0\n      };\n    }\n  }\n  return out;\n}\n\n/* ============================================================\n   組合せ（管理画面）\n   ============================================================ */\nfunction adminDrawLoad_(body) {\n  var div = DIVISIONS[body.div];\n  if (!div) throw new Error('区分を指定してください。');\n  var people = participants_(body.div);\n  var list = [];\n  var k;\n  for (k in people) if (people.hasOwnProperty(k)) list.push(people[k]);\n  if (div.type === 'team') {\n    list.sort(function (a, b) { return districtCompare_(a.sub, b.sub) || String(a.full).localeCompare(String(b.full), 'ja'); });\n  }\n  var draw = {};\n  var dt = table_(SHEET_DRAW);\n  var i;\n  for (i = 0; i < dt.rows.length; i++) if (dt.rows[i]['区分'] === body.div) draw[dt.rows[i]['枠']] = dt.rows[i]['対象ID'];\n  var mt = table_(SHEET_MATCH);\n  var count = 0;\n  var progressed = 0;\n  for (i = 0; i < mt.rows.length; i++) {\n    if (mt.rows[i]['区分'] !== body.div) continue;\n    count++;\n    if (mt.rows[i]['状態'] && mt.rows[i]['状態'] !== '待機' && mt.rows[i]['備考'] !== '不戦勝') progressed++;\n  }\n  return { status: 'ok', slots: drawSlots_(body.div), draw: draw, candidates: list, matchCount: count, progressed: progressed };\n}\n\nfunction adminDrawSave_(body) {\n  var div = DIVISIONS[body.div];\n  if (!div) throw new Error('区分を指定してください。');\n  var people = participants_(body.div);\n  var slots = drawSlots_(body.div);\n  var a = body.assign || {};\n  var used = {};\n  var rows = [];\n  var i, id;\n  for (i = 0; i < slots.length; i++) {\n    id = a[slots[i]] || '';\n    if (!id) continue;\n    if (!people[id]) throw new Error('枠' + slots[i] + 'の選択が正しくありません。');\n    if (used[id]) throw new Error('「' + people[id].label + '」が2つの枠に入っています（' + used[id] + '・' + slots[i] + '）。');\n    used[id] = slots[i];\n    rows.push([body.div, slots[i], id]);\n  }\n  var lock = LockService.getScriptLock();\n  lock.waitLock(20000);\n  try {\n    var dt = table_(SHEET_DRAW);\n    for (i = dt.rows.length - 1; i >= 0; i--) if (dt.rows[i]['区分'] === body.div) dt.sheet.deleteRow(dt.rows[i]._row);\n    for (i = 0; i < rows.length; i++) appendObj_(table_(SHEET_DRAW), { '区分': rows[i][0], '枠': rows[i][1], '対象ID': rows[i][2] });\n  } finally {\n    lock.releaseLock();\n  }\n  log_('組合せ保存', div.name + '：' + rows.length + '/' + slots.length + (body.by ? '（' + body.by + '）' : ''));\n  return { status: 'ok', filled: rows.length, total: slots.length };\n}\n\n/* 組合せから試合を作る（既定のコート割り・順番つき） */\nfunction adminGenerate_(body) {\n  var div = DIVISIONS[body.div];\n  if (!div) throw new Error('区分を指定してください。');\n  var draw = {};\n  var dt = table_(SHEET_DRAW);\n  var i;\n  for (i = 0; i < dt.rows.length; i++) if (dt.rows[i]['区分'] === body.div) draw[dt.rows[i]['枠']] = dt.rows[i]['対象ID'];\n  var lock = LockService.getScriptLock();\n  lock.waitLock(20000);\n  try {\n    var mt = table_(SHEET_MATCH);\n    var existing = [];\n    for (i = 0; i < mt.rows.length; i++) if (mt.rows[i]['区分'] === body.div) existing.push(mt.rows[i]);\n    for (i = 0; i < existing.length; i++) {\n      if (existing[i]['状態'] && existing[i]['状態'] !== '待機' && existing[i]['備考'] !== '不戦勝' && !body.force) {\n        throw new Error('すでに試合が始まっています。作り直すと結果が消えます（作り直す場合は確認のうえ再実行）。');\n      }\n    }\n    for (i = existing.length - 1; i >= 0; i--) mt.sheet.deleteRow(existing[i]._row);\n    var ms = div.type === 'team' ? teamTemplate_(body.div, draw) : indivTemplate_(body.div, draw);\n    var stamp = now_();\n    var rows = [];\n    for (i = 0; i < ms.length; i++) {\n      var m = ms[i];\n      rows.push([m.id, body.div, m.stage, m.round, String(m.no), m.left, m.right, m.court, String(m.seq), m.two ? '1' : '', m.state || '待機', '', '', m.winner || '', m.score || '', m.note || '', stamp]);\n    }\n    var sh = ss_().getSheetByName(SHEET_MATCH);\n    if (rows.length) sh.getRange(sh.getLastRow() + 1, 1, rows.length, rows[0].length).setNumberFormat('@').setValues(rows);\n    if (div.type === 'indiv') {\n      var rt = table_(SHEET_RANK);\n      for (i = rt.rows.length - 1; i >= 0; i--) if (rt.rows[i]['区分'] === body.div) rt.sheet.deleteRow(rt.rows[i]._row);\n    }\n  } finally {\n    lock.releaseLock();\n  }\n  log_('進行表作成', div.name + '：' + rows.length + '試合');\n  return { status: 'ok', count: rows.length };\n}\n\nfunction ref_(kind, id) { return id ? kind + ':' + id : ''; }\n\nfunction teamTemplate_(divCode, draw) {\n  var ms = [];\n  var i, l, r;\n  /* 1回戦：Aコート＝第1〜4試合、Bコート＝第5〜8試合 */\n  for (i = 0; i < 8; i++) {\n    l = draw[String(i * 2 + 1)] || '';\n    r = draw[String(i * 2 + 2)] || '';\n    var m = { id: divCode + '-R1-' + (i + 1), stage: 'R1', round: '1回戦', no: i + 1, left: ref_('E', l), right: ref_('E', r),\n      court: i < 4 ? 'A' : 'B', seq: i < 4 ? (i * 2 + 1) : ((i - 4) * 2 + 2) };\n    if (!l || !r) {\n      m.state = '終了';\n      m.winner = l ? 'L' : (r ? 'R' : '');\n      m.score = '不戦勝';\n      m.note = '不戦勝';\n    }\n    ms.push(m);\n  }\n  var w = function (n) { return 'W:' + divCode + '-R1-' + n; };\n  ms.push({ id: divCode + '-QF-1', stage: 'QF', round: '準々決勝', no: 9, left: w(1), right: w(2), court: 'A', seq: 9 });\n  ms.push({ id: divCode + '-QF-3', stage: 'QF', round: '準々決勝', no: 11, left: w(5), right: w(6), court: 'B', seq: 10 });\n  ms.push({ id: divCode + '-QF-2', stage: 'QF', round: '準々決勝', no: 10, left: w(3), right: w(4), court: 'A', seq: 11 });\n  ms.push({ id: divCode + '-QF-4', stage: 'QF', round: '準々決勝', no: 12, left: w(7), right: w(8), court: 'B', seq: 12 });\n  ms.push({ id: divCode + '-SF-1', stage: 'SF', round: '準決勝', no: 13, left: 'W:' + divCode + '-QF-1', right: 'W:' + divCode + '-QF-2', court: 'A', seq: 13 });\n  ms.push({ id: divCode + '-SF-2', stage: 'SF', round: '準決勝', no: 14, left: 'W:' + divCode + '-QF-3', right: 'W:' + divCode + '-QF-4', court: 'B', seq: 14 });\n  ms.push({ id: divCode + '-F', stage: 'F', round: '決勝', no: 15, left: 'W:' + divCode + '-SF-1', right: 'W:' + divCode + '-SF-2', court: 'A', seq: 15, two: true });\n  return ms;\n}\n\nfunction indivTemplate_(divCode, draw) {\n  var ms = [];\n  var courts = { A: ['A', 'B'], B: ['C', 'D'] };\n  var seqOf = { A: 1, B: 2 };\n  var no = 0;\n  var tmp = [];\n  var c, r, bi, k, blk, pr, l, rr;\n  /* 予選リーグ：Aコート＝A・Bブロック、Bコート＝C・Dブロック。1試合ずつブロックを交互に（A1-2 → B1-2 → A3-4 → B3-4 …） */\n  for (c in courts) {\n    if (!courts.hasOwnProperty(c)) continue;\n    for (r = 0; r < LEAGUE_ROUNDS.length; r++) {\n      for (k = 0; k < LEAGUE_ROUNDS[r].length; k++) {\n        for (bi = 0; bi < courts[c].length; bi++) {\n          blk = courts[c][bi];\n          pr = LEAGUE_ROUNDS[r][k];\n          l = draw[blk + pr[0]] || '';\n          rr = draw[blk + pr[1]] || '';\n          if (!l || !rr) continue;\n          tmp.push({ id: divCode + '-L-' + blk + pr[0] + pr[1], stage: 'L', block: blk, round: blk + 'ブロック（' + pr[0] + '-' + pr[1] + '）',\n            left: ref_('P', l), right: ref_('P', rr), court: c, seq: seqOf[c] });\n          seqOf[c] += 2;\n        }\n      }\n    }\n  }\n  tmp.sort(function (a, b) { return a.seq - b.seq; });\n  for (k = 0; k < tmp.length; k++) { tmp[k].no = ++no; ms.push(tmp[k]); }\n  var base = Math.max(seqOf.A, seqOf.B);\n  var q;\n  for (q = 0; q < KO_QF.length; q++) {\n    ms.push({ id: divCode + '-QF-' + (q + 1), stage: 'QF', round: '決勝T 準々決勝', no: ++no, left: 'R:' + KO_QF[q][0], right: 'R:' + KO_QF[q][1],\n      court: q % 2 === 0 ? 'A' : 'B', seq: base + q });\n  }\n  ms.push({ id: divCode + '-SF-1', stage: 'SF', round: '決勝T 準決勝', no: ++no, left: 'W:' + divCode + '-QF-1', right: 'W:' + divCode + '-QF-2', court: 'A', seq: base + 4 });\n  ms.push({ id: divCode + '-SF-2', stage: 'SF', round: '決勝T 準決勝', no: ++no, left: 'W:' + divCode + '-QF-3', right: 'W:' + divCode + '-QF-4', court: 'B', seq: base + 5 });\n  ms.push({ id: divCode + '-F', stage: 'F', round: '決勝', no: ++no, left: 'W:' + divCode + '-SF-1', right: 'W:' + divCode + '-SF-2', court: 'A', seq: base + 6 });\n  return ms;\n}\n\n/* ============================================================\n   進行表データ（公開・本部共通）\n   ============================================================ */\nfunction hm_(min) {\n  if (min === null || min === undefined || isNaN(min)) return '';\n  var h = Math.floor(min / 60);\n  var m = Math.round(min % 60);\n  if (m === 60) { h++; m = 0; }\n  return h + ':' + (m < 10 ? '0' : '') + m;\n}\n\nfunction toMin_(s) {\n  var m = String(s || '').match(/(\\d{1,2}):(\\d{2})(?::\\d{2})?$/);\n  return m ? toInt_(m[1]) * 60 + toInt_(m[2]) : null;\n}\n\nfunction nowMin_() {\n  return toMin_(Utilities.formatDate(new Date(), 'Asia/Tokyo', 'HH:mm'));\n}\n\nfunction loadMatches_(divCode) {\n  var mt = table_(SHEET_MATCH);\n  var out = [];\n  var i, r;\n  for (i = 0; i < mt.rows.length; i++) {\n    r = mt.rows[i];\n    if (r['区分'] !== divCode) continue;\n    out.push({\n      _row: r, id: r.matchId, stage: r['段階'], round: r['ラウンド'], no: toInt_(r['番号']), left: r['左'], right: r['右'],\n      court: r['コート'] || 'A', seq: toInt_(r['順番']), two: r['2面'] === '1', state: r['状態'] || '待機',\n      start: r['開始'], end: r['終了'], winner: r['勝者'], score: r['スコア'], note: r['備考'],\n      orderL: parseJson_(r['オーダー左'], null), orderR: parseJson_(r['オーダー右'], null), pairs: parseJson_(r['番手'], []), tb: parseJson_(r['判定'], {}), pub: r['オーダー公開'] || ''\n    });\n  }\n  out.sort(function (a, b) { return a.seq - b.seq || a.no - b.no; });\n  return out;\n}\n\nfunction loadRanks_(divCode) {\n  var rt = table_(SHEET_RANK);\n  var ranks = {};\n  var i;\n  for (i = 0; i < rt.rows.length; i++) {\n    if (rt.rows[i]['区分'] !== divCode) continue;\n    ranks[rt.rows[i]['ブロック'] + '1'] = rt.rows[i]['1位'];\n    ranks[rt.rows[i]['ブロック'] + '2'] = rt.rows[i]['2位'];\n    if (rt.rows[i]['3位']) ranks[rt.rows[i]['ブロック'] + '3'] = rt.rows[i]['3位'];\n  }\n  return ranks;\n}\n\n/* 予選リーグ表の「得失」欄：本部が表示を選んだブロックだけ、入力した組だけに出す\n   kind：'' は出さない。個人戦は ゲーム／ポイント、団体戦のリーグでは マッチ も選べる */\nvar DIFF_KINDS = { indiv: ['ゲーム', 'ポイント'], team: ['マッチ', 'ゲーム', 'ポイント'] };\n\nfunction loadDiff_(divCode) {\n  var rt = table_(SHEET_RANK);\n  var out = {};\n  var i, r, vals;\n  for (i = 0; i < rt.rows.length; i++) {\n    r = rt.rows[i];\n    if (r['区分'] !== divCode || !r['得失表示']) continue;\n    vals = {};\n    try { vals = JSON.parse(r['得失値'] || '{}') || {}; } catch (e) { vals = {}; }\n    out[r['ブロック']] = { kind: String(r['得失表示']), label: '得失' + r['得失表示'], vals: vals };\n  }\n  return out;\n}\n\n/* 「+3」「-2」「0」の形にそろえる。空欄は出さない。数字でなければエラー */\nfunction normDiff_(v) {\n  var s = String(v === undefined || v === null ? '' : v).trim()\n    .replace(/[０-９]/g, function (c) { return String.fromCharCode(c.charCodeAt(0) - 0xFEE0); })\n    .replace(/[＋]/g, '+').replace(/[−－ー‐]/g, '-').replace(/\\s/g, '');\n  if (s === '') return '';\n  if (!/^[+\\-]?\\d{1,3}$/.test(s)) return null;\n  var n = parseInt(s, 10);\n  return n > 0 ? '+' + n : String(n);\n}\n\n/* 参照（E:/P:/W:/R:）を参加者IDに解決。未確定なら null */\nfunction resolveRef_(ref, byId, ranks, depth) {\n  if (!ref) return null;\n  var kind = ref.charAt(0);\n  var key = ref.slice(2);\n  if (kind === 'E' || kind === 'P') return key;\n  if (kind === 'R') return ranks[key] || null;\n  if (kind === 'W') {\n    var m = byId[key];\n    if (!m || !m.winner || (depth || 0) > 6) return null;\n    return resolveRef_(m.winner === 'L' ? m.left : m.right, byId, ranks, (depth || 0) + 1);\n  }\n  return null;\n}\n\nfunction refPlaceholder_(ref, byId) {\n  if (!ref) return '（なし）';\n  var kind = ref.charAt(0);\n  var key = ref.slice(2);\n  if (kind === 'R') return key.charAt(0) + 'ブロック' + key.charAt(1) + '位';\n  if (kind === 'W') return byId[key] ? '第' + byId[key].no + '試合の勝者' : '勝者';\n  return '';\n}\n\nfunction matchDuration_(m, div, cfg) {\n  if (div.type === 'indiv') return toInt_(cfg['7ゲーム目安（分）']) || 30;\n  var g5 = toInt_(cfg['5ゲーム目安（分）']) || 20;\n  return m.two ? g5 * 2 : g5 * 3;\n}\n\n/* 予定時刻の計算：コートの空き・前の試合の終了＋間隔・同じ選手の連戦を考慮 */\nfunction computeTimes_(ms, div, cfg, ranksReady) {\n  var byId = {};\n  var i;\n  for (i = 0; i < ms.length; i++) byId[ms[i].id] = ms[i];\n  var dayStart = toMin_(cfg['競技開始時刻']) || 540;\n  var gap = div.type === 'team' ? toInt_(cfg['団体戦の次戦までの間隔（分）']) : toInt_(cfg['個人戦の次戦までの間隔（分）']);\n  var live = false;\n  for (i = 0; i < ms.length; i++) if (ms[i].start && ms[i].note !== '不戦勝') live = true;\n  var now = live ? nowMin_() : null;\n  var est = {};\n  var blockEnd = {};\n  var iter, m, free, lastEnd, dur, start, end, ready, sides, s, ref, k;\n  for (iter = 0; iter < 4; iter++) {\n    free = { A: dayStart, B: dayStart };\n    lastEnd = {};\n    blockEnd = {};\n    for (i = 0; i < ms.length; i++) {\n      m = ms[i];\n      if (m.note === '不戦勝') { est[m.id] = { start: null, end: dayStart }; continue; }\n      dur = matchDuration_(m, div, cfg);\n      ready = dayStart;\n      sides = [m.left, m.right];\n      for (s = 0; s < 2; s++) {\n        ref = sides[s];\n        if (!ref) continue;\n        if (ref.charAt(0) === 'W' && est[ref.slice(2)]) ready = Math.max(ready, est[ref.slice(2)].end + gap);\n        if (ref.charAt(0) === 'W' && !est[ref.slice(2)] && byId[ref.slice(2)]) ready = Math.max(ready, dayStart + dur + gap);\n        if (ref.charAt(0) === 'R') {\n          k = ref.charAt(2);\n          if (blockEnd[k] !== undefined) ready = Math.max(ready, blockEnd[k] + gap);\n        }\n        if ((ref.charAt(0) === 'E' || ref.charAt(0) === 'P') && lastEnd[ref] !== undefined) ready = Math.max(ready, lastEnd[ref] + gap);\n      }\n      var courtFree = m.two ? Math.max(free.A, free.B) : free[m.court];\n      if (m.state === '終了' && m.start) {\n        start = toMin_(m.start);\n        end = toMin_(m.end) || start + dur;\n      } else if (m.state === '試合中' && m.start) {\n        start = toMin_(m.start);\n        end = start + dur;\n        if (now !== null) end = Math.max(end, now + 5);\n      } else {\n        start = Math.max(courtFree, ready);\n        if (now !== null) start = Math.max(start, now);\n        end = start + dur;\n      }\n      est[m.id] = { start: start, end: end };\n      if (m.two) { free.A = Math.max(free.A, end); free.B = Math.max(free.B, end); } else { free[m.court] = Math.max(free[m.court], end); }\n      for (s = 0; s < 2; s++) if (sides[s] && (sides[s].charAt(0) === 'E' || sides[s].charAt(0) === 'P')) lastEnd[sides[s]] = end;\n      if (m.stage === 'L') blockEnd[m.id.split('-L-')[1].charAt(0)] = Math.max(blockEnd[m.id.split('-L-')[1].charAt(0)] || 0, end);\n    }\n  }\n  return est;\n}\n\nfunction loadDraw_(divCode) {\n  var dt = table_(SHEET_DRAW);\n  var d = {};\n  var i;\n  for (i = 0; i < dt.rows.length; i++) if (dt.rows[i]['区分'] === divCode) d[String(dt.rows[i]['枠'])] = dt.rows[i]['対象ID'];\n  return d;\n}\n\n/* 審判の割当\n   個人戦：予選リーグ＝リーグ内（LEAGUE_REFS）／決勝T1回戦＝各コートの初戦はA・Bブロック3位、2戦目以降は同じコートの直前の試合の敗者／準決勝・決勝＝審判員\n   団体戦：各コートの初戦＝Aコートは7番・8番、Bコートは15番・16番のチームから1名ずつ、2戦目以降は同じコートの直前の試合の敗者／決勝＝審判員\n   戻り値：matchId → { official } または { id } または { ids }（2チームから1名ずつ） または { text }（未確定の説明） */\nfunction refereeMap_(ms, div, byId, ranks, draw) {\n  var res = {};\n  var chain = { A: [], B: [] };\n  var i, j, m, key, blk, pos, cands, id, prev, court, loserRef;\n  for (i = 0; i < ms.length; i++) {\n    m = ms[i];\n    if (m.note === '不戦勝') continue;\n    if (m.stage === 'F' || (div.type === 'indiv' && m.stage === 'SF')) { res[m.id] = { official: true }; continue; }\n    if (m.stage === 'L') {\n      key = m.id.split('-L-')[1] || '';\n      blk = key.charAt(0);\n      pos = key.slice(1);\n      cands = [LEAGUE_REFS[pos]];\n      for (j = 1; j <= 4; j++) if (pos.indexOf(String(j)) < 0 && j !== LEAGUE_REFS[pos]) cands.push(j);\n      res[m.id] = { text: '本部が指定' };\n      for (j = 0; j < cands.length; j++) {\n        id = cands[j] ? draw[blk + cands[j]] : '';\n        if (id) { res[m.id] = { id: id }; break; }\n      }\n      continue;\n    }\n    court = m.court === 'B' ? 'B' : 'A';\n    prev = chain[court].length ? chain[court][chain[court].length - 1] : null;\n    if (!prev) {\n      if (div.type === 'team') {\n        var pair = court === 'A' ? ['7', '8'] : ['15', '16'];\n        var ids = [];\n        for (j = 0; j < pair.length; j++) if (draw[pair[j]]) ids.push(draw[pair[j]]);\n        res[m.id] = ids.length === 2 ? { ids: ids } : (ids.length === 1 ? { id: ids[0] } : { text: '本部が指定' });\n      } else {\n        id = ranks[court + '3'];\n        res[m.id] = id ? { id: id } : { text: court + 'ブロック3位' };\n      }\n    } else {\n      id = null;\n      if (prev.winner === 'L' || prev.winner === 'R') {\n        loserRef = prev.winner === 'L' ? prev.right : prev.left;\n        id = resolveRef_(loserRef, byId, ranks, 0);\n      }\n      res[m.id] = id ? { id: id, after: prev.no } : { text: '第' + prev.no + '試合の敗者' };\n    }\n    chain[court].push(m);\n  }\n  return res;\n}\n\nfunction progressData_(divCode, isAdmin, previewMs) {\n  var div = DIVISIONS[divCode];\n  if (!div) return { status: 'error', message: '区分が正しくありません。' };\n  var cfg = getConfig_();\n  var ms = previewMs || loadMatches_(divCode);\n  var ranks = div.type === 'indiv' && !previewMs ? loadRanks_(divCode) : {};\n  var people = participants_(divCode);\n  var byId = {};\n  var i;\n  for (i = 0; i < ms.length; i++) byId[ms[i].id] = ms[i];\n  var est = computeTimes_(ms, div, cfg);\n  var refs = refereeMap_(ms, div, byId, ranks, loadDraw_(divCode));\n  var playersOf = {};\n  if (div.type === 'team' && isAdmin) {\n    var et = table_(SHEET_ENTRY);\n    for (i = 0; i < et.rows.length; i++) if (et.rows[i]['区分'] === divCode) playersOf[et.rows[i].entryId] = teamPlayers_(et.rows[i]);\n  }\n  var out = [];\n  var m, side, sides, s, pid, e;\n  var lastEnd = 0;\n  for (i = 0; i < ms.length; i++) {\n    m = ms[i];\n    sides = [];\n    for (s = 0; s < 2; s++) {\n      side = s === 0 ? m.left : m.right;\n      pid = resolveRef_(side, byId, ranks, 0);\n      var origin = side && side.charAt(0) === 'R' ? side.slice(2) + '位' : '';\n      if (pid && people[pid]) sides.push({ decided: true, id: pid, label: people[pid].label, sub: people[pid].sub, full: people[pid].full, origin: origin, names: people[pid].names || null, grades: people[pid].grades || null, teamsFull: people[pid].teamsFull || null, changed: people[pid].changed || 0 });\n      else sides.push({ decided: false, label: refPlaceholder_(side, byId), sub: '', origin: origin });\n    }\n    e = est[m.id] || {};\n    var rf = refs[m.id] || null;\n    var referee = null;\n    if (rf && rf.official) referee = { official: true, label: '審判員' };\n    else if (rf && rf.id) referee = { decided: true, id: rf.id, label: people[rf.id] ? people[rf.id].label : '', sub: people[rf.id] ? people[rf.id].sub : '' };\n    else if (rf && rf.ids) referee = { decided: true, ids: rf.ids, label: (people[rf.ids[0]] ? people[rf.ids[0]].label : '') + '・' + (people[rf.ids[1]] ? people[rf.ids[1]].label : ''), sub: '各1名' };\n    else if (rf) referee = { decided: false, label: rf.text };\n    if (e.end && e.end > lastEnd && m.note !== '不戦勝') lastEnd = e.end;\n    out.push({\n      id: m.id, no: m.no, stage: m.stage, round: m.round, court: m.court, seq: m.seq, two: m.two, state: m.state,\n      plan: hm_(e.start), planEnd: hm_(e.end), start: String(m.start || '').slice(11, 16), end: String(m.end || '').slice(11, 16),\n      left: sides[0], right: sides[1], winner: m.winner, score: m.score, note: m.note, referee: referee,\n      team: div.type === 'team' ? teamView_(m, byId, cfg, isAdmin) : null\n    });\n    if (div.type === 'team' && isAdmin) {\n      out[out.length - 1].team.playersL = sides[0].decided ? playersOf[sides[0].id] || [] : [];\n      out[out.length - 1].team.playersR = sides[1].decided ? playersOf[sides[1].id] || [] : [];\n    }\n  }\n  var res = {\n    status: 'ok', division: div, tournament: cfg['大会名'],\n    date: div.type === 'team' ? cfg['団体戦日程'] : cfg['個人戦日程'],\n    venue: div.gender === '男' ? cfg['男子会場'] : cfg['女子会場'],\n    startTime: cfg['競技開始時刻'], finishPlan: hm_(lastEnd), updated: Utilities.formatDate(new Date(), 'Asia/Tokyo', 'HH:mm:ss'),\n    matches: out\n  };\n  /* ブロック分け（組合せ）は、進行表を作成（＝公開）した区分だけ返す。保存しただけの組合せ案は出さない */\n  if (div.type === 'indiv' && ms.length) {\n    var blocks = {};\n    var dt = table_(SHEET_DRAW);\n    for (i = 0; i < dt.rows.length; i++) {\n      var d = dt.rows[i];\n      if (d['区分'] !== divCode) continue;\n      var b = String(d['枠']).charAt(0);\n      if (!blocks[b]) blocks[b] = [];\n      var pp = people[d['対象ID']];\n      blocks[b].push({ pos: toInt_(String(d['枠']).slice(1)), id: d['対象ID'], label: pp ? pp.label : '', sub: pp ? pp.sub : '',\n        names: pp ? pp.names : [], grades: pp ? pp.grades : [], teams: pp ? pp.teams : [], teamsFull: pp ? pp.teamsFull : [] });\n    }\n    for (b in blocks) if (blocks.hasOwnProperty(b)) blocks[b].sort(function (x, y) { return x.pos - y.pos; });\n    res.blocks = blocks;\n    res.ranks = ranks;\n    res.diff = loadDiff_(divCode);\n    res.diffKinds = DIFF_KINDS[div.type];\n  }\n  if (isAdmin) {\n    var reqs = changeRequests_();\n    res.pendingChanges = 0;\n    for (i = 0; i < reqs.length; i++) if (reqs[i].div === divCode && reqs[i].state === '申請中') res.pendingChanges++;\n    res.config = {\n      start: cfg['競技開始時刻'], g5: cfg['5ゲーム目安（分）'], g7: cfg['7ゲーム目安（分）'],\n      gapTeam: cfg['団体戦の次戦までの間隔（分）'], gapIndiv: cfg['個人戦の次戦までの間隔（分）']\n    };\n  }\n  return res;\n}\n\n/* ============================================================\n   本部操作（本部パスワード または 管理パスワード）\n   ============================================================ */\nfunction controlRoute_(body) {\n  var cfg = getConfig_();\n  var pw = String(body.pw || '');\n  if (!pw || (pw !== String(cfg['本部パスワード']) && pw !== String(cfg['管理パスワード']))) {\n    return { status: 'error', code: 'auth', message: 'パスワードが違います。' };\n  }\n  switch (body.action) {\n    case 'ctlLoad': return progressData_(body.div, true);\n    case 'ctlUpdate': return adminCtlUpdate_(body);\n    case 'ctlRanks': return adminCtlRanks_(body);\n    case 'ctlDiff': return adminCtlDiff_(body);\n    case 'ctlConfig': return adminCtlConfig_(body);\n    case 'ctlOrder': return ctlOrder_(body);\n    case 'ctlPairs': return ctlPairs_(body);\n    default: return { status: 'error', message: '不明な操作です。' };\n  }\n}\nfunction adminCtlUpdate_(body) {\n  var lock = LockService.getScriptLock();\n  lock.waitLock(20000);\n  try {\n    var ms = loadMatches_(body.div);\n    var div = DIVISIONS[body.div];\n    var byId = {};\n    var i;\n    for (i = 0; i < ms.length; i++) byId[ms[i].id] = ms[i];\n    var m = byId[body.matchId];\n    if (!m) throw new Error('試合が見つかりません。');\n    var t = table_(SHEET_MATCH);\n    var row = null;\n    for (i = 0; i < t.rows.length; i++) if (t.rows[i].matchId === m.id) row = t.rows[i];\n    var upd = {};\n    var stamp = now_();\n    var ranks = div.type === 'indiv' ? loadRanks_(body.div) : {};\n    var op = body.op;\n\n    if (op === 'up' || op === 'down') {\n      var same = [];\n      for (i = 0; i < ms.length; i++) if (ms[i].court === m.court || ms[i].two || m.two) same.push(ms[i]);\n      var idx = -1;\n      for (i = 0; i < same.length; i++) if (same[i].id === m.id) idx = i;\n      var other = op === 'up' ? same[idx - 1] : same[idx + 1];\n      if (!other) throw new Error('これ以上動かせません。');\n      if (other.state === '終了' || other.state === '試合中') throw new Error('終了・試合中の試合とは入れ替えられません。');\n      var r2 = null;\n      for (i = 0; i < t.rows.length; i++) if (t.rows[i].matchId === other.id) r2 = t.rows[i];\n      writeRow_(t, r2, { '順番': String(m.seq), '更新日時': stamp });\n      upd['順番'] = String(other.seq);\n    } else if (op === 'court') {\n      if (m.state === '終了') throw new Error('終了した試合は移動できません。');\n      upd['コート'] = m.court === 'A' ? 'B' : 'A';\n    } else if (op === 'two') {\n      if (div.type !== 'team') throw new Error('2面展開は団体戦のみです。');\n      if (m.state === '終了') throw new Error('終了した試合は変更できません。');\n      upd['2面'] = m.two ? '' : '1';\n    } else if (op === 'state') {\n      var st = body.state;\n      if (STATES.indexOf(st) < 0) throw new Error('状態が正しくありません。');\n      if (st === '終了') throw new Error('終了は「結果入力」から行ってください。');\n      if (st !== '待機') {\n        if (!resolveRef_(m.left, byId, ranks, 0) || !resolveRef_(m.right, byId, ranks, 0)) throw new Error('対戦相手が決まっていません。');\n      }\n      if (m.state === '終了') assertNoDependentsStarted_(m, ms);\n      upd['状態'] = st;\n      if (st === '試合中' && !m.start) upd['開始'] = stamp;\n      if (st === '試合中' && div.type === 'team' && !m.pub) upd['オーダー公開'] = stamp;\n      if (st === '待機' || st === '呼出') { upd['開始'] = ''; upd['終了'] = ''; upd['勝者'] = ''; upd['スコア'] = ''; }\n    } else if (op === 'publish') {\n      if (div.type !== 'team') throw new Error('オーダーの公開は団体戦のみです。');\n      if (m.state === '終了') throw new Error('終了した試合です。');\n      if (!m.orderL || !m.orderR) throw new Error('両チームのオーダーがそろっていません。未提出のチームは「オーダー」から代理入力してください。');\n      upd['オーダー公開'] = stamp;\n    } else if (op === 'unpublish') {\n      if (m.state === '試合中' || m.state === '終了') throw new Error('試合が始まっているため、非公開に戻せません。');\n      upd['オーダー公開'] = '';\n    } else if (op === 'result') {\n      if (body.winner !== 'L' && body.winner !== 'R') throw new Error('勝者を選んでください。');\n      if (!resolveRef_(m.left, byId, ranks, 0) || !resolveRef_(m.right, byId, ranks, 0)) throw new Error('対戦相手が決まっていません。');\n      if (m.state === '終了' && m.winner !== body.winner) assertNoDependentsStarted_(m, ms);\n      upd['状態'] = '終了';\n      upd['勝者'] = body.winner;\n      upd['スコア'] = String(body.score || '').slice(0, 30);\n      if (!m.start) upd['開始'] = stamp;\n      if (!m.end || m.state !== '終了') upd['終了'] = stamp;\n    } else {\n      throw new Error('不明な操作です。');\n    }\n    upd['更新日時'] = stamp;\n    writeRow_(t, row, upd);\n  } finally {\n    lock.releaseLock();\n  }\n  return progressData_(body.div, true);\n}\n\n/* 勝者を変える・取り消す前に、次の試合が始まっていないか確認 */\nfunction assertNoDependentsStarted_(m, ms) {\n  var i;\n  for (i = 0; i < ms.length; i++) {\n    if ((ms[i].left === 'W:' + m.id || ms[i].right === 'W:' + m.id) && ms[i].state !== '待機' && ms[i].state !== '呼出') {\n      throw new Error('次の試合（第' + ms[i].no + '試合）が始まっているため変更できません。');\n    }\n  }\n}\n\n/* 予選リーグの順位（1位・2位、審判に使う3位）を本部が入力 */\nfunction adminCtlRanks_(body) {\n  var div = DIVISIONS[body.div];\n  if (!div || div.type !== 'indiv') throw new Error('個人戦の区分を指定してください。');\n  var blk = String(body.block || '');\n  if (BLOCKS.indexOf(blk) < 0) throw new Error('ブロックを指定してください。');\n  if (body.first && body.first === body.second) throw new Error('1位と2位が同じです。');\n  if (body.third && (body.third === body.first || body.third === body.second)) throw new Error('3位が1位・2位と同じです。');\n  var dt = table_(SHEET_DRAW);\n  var members = {};\n  var i;\n  for (i = 0; i < dt.rows.length; i++) if (dt.rows[i]['区分'] === body.div && String(dt.rows[i]['枠']).charAt(0) === blk) members[dt.rows[i]['対象ID']] = true;\n  if ((body.first && !members[body.first]) || (body.second && !members[body.second]) || (body.third && !members[body.third])) throw new Error(blk + 'ブロックのペアを選んでください。');\n  var old = loadRanks_(body.div);\n  var changed = (old[blk + '1'] || '') !== (body.first || '') || (old[blk + '2'] || '') !== (body.second || '');\n  var ms = loadMatches_(body.div);\n  for (i = 0; changed && i < ms.length; i++) {\n    if (ms[i].stage === 'QF' && (ms[i].left === 'R:' + blk + '1' || ms[i].right === 'R:' + blk + '1' || ms[i].left === 'R:' + blk + '2' || ms[i].right === 'R:' + blk + '2') &&\n        ms[i].state !== '待機' && ms[i].state !== '呼出') {\n      throw new Error('決勝トーナメント（第' + ms[i].no + '試合）が始まっているため変更できません。');\n    }\n  }\n  var lock = LockService.getScriptLock();\n  lock.waitLock(20000);\n  try {\n    ensureHeaders_(table_(SHEET_RANK).sheet, HEADERS[SHEET_RANK]);\n    var rt = table_(SHEET_RANK);\n    var target = null;\n    for (i = 0; i < rt.rows.length; i++) if (rt.rows[i]['区分'] === body.div && rt.rows[i]['ブロック'] === blk) target = rt.rows[i];\n    var vals = { '1位': body.first || '', '2位': body.second || '', '3位': body.third || '', '更新日時': now_() };\n    if (target) writeRow_(rt, target, vals);\n    else { vals['区分'] = body.div; vals['ブロック'] = blk; appendObj_(rt, vals); }\n  } finally {\n    lock.releaseLock();\n  }\n  log_('予選順位', div.name + '／' + blk + 'ブロック');\n  return progressData_(body.div, true);\n}\n\n/* 予選リーグ表の「得失」欄を本部が設定（表示の種類と、組ごとの値） */\nfunction adminCtlDiff_(body) {\n  var div = DIVISIONS[body.div];\n  if (!div) throw new Error('区分を指定してください。');\n  var blk = String(body.block || '');\n  if (BLOCKS.indexOf(blk) < 0) throw new Error('ブロックを指定してください。');\n  var kind = String(body.kind || '');\n  var kinds = DIFF_KINDS[div.type] || [];\n  if (kind && kinds.indexOf(kind) < 0) throw new Error('得失の種類が正しくありません。');\n  var dt = table_(SHEET_DRAW);\n  var members = {};\n  var i;\n  for (i = 0; i < dt.rows.length; i++) if (dt.rows[i]['区分'] === body.div && String(dt.rows[i]['枠']).charAt(0) === blk) members[dt.rows[i]['対象ID']] = true;\n  var src = body.vals || {};\n  var vals = {};\n  var k, v;\n  if (kind) {\n    for (k in src) {\n      if (!src.hasOwnProperty(k) || !members[k]) continue;\n      v = normDiff_(src[k]);\n      if (v === null) throw new Error('得失の値は「+3」「-2」「0」のように数字で入力してください。');\n      if (v !== '') vals[k] = v;\n    }\n  }\n  var lock = LockService.getScriptLock();\n  lock.waitLock(20000);\n  try {\n    ensureHeaders_(table_(SHEET_RANK).sheet, HEADERS[SHEET_RANK]);\n    var rt = table_(SHEET_RANK);\n    var target = null;\n    for (i = 0; i < rt.rows.length; i++) if (rt.rows[i]['区分'] === body.div && rt.rows[i]['ブロック'] === blk) target = rt.rows[i];\n    var upd = { '得失表示': kind, '得失値': kind ? JSON.stringify(vals) : '', '更新日時': now_() };\n    if (target) writeRow_(rt, target, upd);\n    else { upd['区分'] = body.div; upd['ブロック'] = blk; appendObj_(rt, upd); }\n  } finally {\n    lock.releaseLock();\n  }\n  log_('得失表示', div.name + '／' + blk + 'ブロック：' + (kind ? '得失' + kind : '表示しない'));\n  return progressData_(body.div, true);\n}\n\n/* 目安時間などの変更（設定シートに書き込み） */\nfunction adminCtlConfig_(body) {\n  var allowed = { start: '競技開始時刻', g5: '5ゲーム目安（分）', g7: '7ゲーム目安（分）', gapTeam: '団体戦の次戦までの間隔（分）', gapIndiv: '個人戦の次戦までの間隔（分）' };\n  var vals = body.values || {};\n  var sh = ss_().getSheetByName(SHEET_CONFIG);\n  var data = sh.getDataRange().getValues();\n  var k, i, found, v;\n  for (k in allowed) {\n    if (!allowed.hasOwnProperty(k) || vals[k] === undefined) continue;\n    v = String(vals[k]).trim();\n    if (k === 'start' && !/^\\d{1,2}:\\d{2}$/.test(v)) throw new Error('競技開始時刻は「9:00」の形で入力してください。');\n    if (k !== 'start' && !/^\\d{1,3}$/.test(v)) throw new Error(allowed[k] + 'は数字で入力してください。');\n    found = false;\n    for (i = 1; i < data.length; i++) {\n      if (String(data[i][0]) === allowed[k]) { sh.getRange(i + 1, 2).setNumberFormat('@').setValue(v); found = true; }\n    }\n    if (!found) sh.appendRow([allowed[k], v]);\n  }\n  log_('目安時間変更', JSON.stringify(vals));\n  return progressData_(body.div, true);\n}\n\n/* ============================================================\n   団体戦：オーダー・番手結果・勝敗判定（フェーズ4）\n   3ダブルス。1回戦は3番手まで行う。2回戦以降は2勝で決着（残りは打ち切り）。\n   6名未満のチームは第3マッチが欠員（不戦敗）。不戦敗・リタイアのスコアは勝者から見て「3-R」（R＝リタイアメント）。同数のときは 得失ゲーム差 → 得失ポイント差（本部入力）→ 代表戦（本部入力）\n   ============================================================ */\n\n/* 選手（欠員を除く。選手変更を反映済み） */\nfunction teamPlayers_(entryRow) {\n  var ps = parseJson_(entryRow['選手JSON'], []);\n  var out = [];\n  var i;\n  for (i = 0; i < ps.length; i++) if (ps[i] && !ps[i].vacant && ps[i].name) out.push({ no: ps[i].no || (i + 1), name: ps[i].name, grade: ps[i].grade });\n  return out;\n}\n\n/* オーダーの確認と整形：[[A,B],[C,D],[E,F] or null] */\nfunction normalizeOrder_(entryRow, pairs) {\n  var players = teamPlayers_(entryRow);\n  var names = {};\n  var i, j;\n  for (i = 0; i < players.length; i++) names[normName_(players[i].name)] = players[i].name;\n  var need = players.length >= 6 ? 3 : 2;\n  var used = {};\n  var out = [];\n  for (i = 0; i < 3; i++) {\n    var pr = (pairs && pairs[i]) || [];\n    if (i >= need) {\n      out.push(null);\n      continue;\n    }\n    if (!pr[0] || !pr[1]) throw new Error('第' + (i + 1) + 'マッチの選手を2名選んでください。');\n    var row = [];\n    for (j = 0; j < 2; j++) {\n      var key = normName_(pr[j]);\n      if (!names[key]) throw new Error('「' + pr[j] + '」は登録選手にいません。');\n      if (used[key]) throw new Error('「' + names[key] + '」が2つのマッチに入っています。');\n      used[key] = true;\n      row.push(names[key]);\n    }\n    out.push(row);\n  }\n  return out;\n}\n\nfunction matchRow_(matchId) {\n  var t = table_(SHEET_MATCH);\n  var i;\n  for (i = 0; i < t.rows.length; i++) if (t.rows[i].matchId === matchId) return { t: t, row: t.rows[i] };\n  return null;\n}\n\nfunction entryById_(entryId) {\n  var t = table_(SHEET_ENTRY);\n  var i;\n  for (i = 0; i < t.rows.length; i++) if (t.rows[i].entryId === entryId) return t.rows[i];\n  return null;\n}\n\n/* オーダー締切（分）：1回戦は設定の時刻、2回戦以降は前の試合（遅い方）の終了＋提出時間 */\nfunction orderDeadline_(m, byId, cfg) {\n  if (m.stage === 'R1') return { deadline: toMin_(cfg['1回戦オーダー締切']), gather: null, decidedAt: null };\n  var refs = [m.left, m.right];\n  var last = null;\n  var i, f;\n  for (i = 0; i < 2; i++) {\n    if (!refs[i] || refs[i].charAt(0) !== 'W') continue;\n    f = byId[refs[i].slice(2)];\n    if (!f || f.state !== '終了') return { deadline: null, gather: null, decidedAt: null };\n    var e = toMin_(f.end);\n    if (f.note === '不戦勝') e = null;\n    if (e !== null && (last === null || e > last)) last = e;\n  }\n  if (last === null) return { deadline: null, gather: null, decidedAt: null };\n  return { deadline: last + (toInt_(cfg['オーダー提出（分）']) || 10), gather: last + (toInt_(cfg['コート集合（分）']) || 15), decidedAt: last };\n}\n\n/* 番手ごとの状態と勝敗の判定 */\nfunction teamOutcome_(m) {\n  var oL = m.orderL ? m.orderL.p : null;\n  var oR = m.orderR ? m.orderR.p : null;\n  var res = m.pairs || [];\n  var isR1 = m.stage === 'R1';\n  var wL = 0, wR = 0, gd = 0, done = 0;\n  var rows = [];\n  var i, r, fL, fR, sc;\n  for (i = 0; i < 3; i++) {\n    r = res[i] || {};\n    fL = !!(oL && i === 2 && !oL[2]);\n    fR = !!(oR && i === 2 && !oR[2]);\n    var row = { w: '', g: '', kind: '' };\n    if (fL && fR) { row.kind = 'none'; done++; }\n    else if (fL) { row.w = 'R'; row.g = 'R-3'; row.kind = 'forfeit'; row.vac = true; wR++; done++; }\n    else if (fR) { row.w = 'L'; row.g = '3-R'; row.kind = 'forfeit'; row.vac = true; wL++; done++; }\n    else if (r.w === 'L' || r.w === 'R') {\n      row.w = r.w;\n      row.g = r.g || '';\n      /* 不戦勝・リタイア：「3-R」（旧表記「不戦勝」も同じ扱い）。得失ゲーム差には入れない */\n      if (r.g === '不戦勝') row.g = r.w === 'L' ? '3-R' : 'R-3';\n      row.kind = /R/.test(row.g) ? 'forfeit' : 'played';\n      if (r.w === 'L') wL++; else wR++;\n      done++;\n      sc = String(r.g || '').match(/^(\\d+)-(\\d+)$/);\n      if (sc) gd += toInt_(sc[1]) - toInt_(sc[2]);\n    }\n    rows.push(row);\n  }\n  var out = { rows: rows, wL: wL, wR: wR, gd: gd, decided: false, winner: '', score: '', need: '' };\n  if (!isR1 && (wL >= 2 || wR >= 2)) {\n    out.decided = true;\n    out.winner = wL >= 2 ? 'L' : 'R';\n    for (i = 0; i < 3; i++) if (!rows[i].w && rows[i].kind !== 'none') rows[i].kind = 'abort';\n  } else if (done === 3) {\n    if (wL !== wR) { out.decided = true; out.winner = wL > wR ? 'L' : 'R'; }\n    else if (gd !== 0) { out.decided = true; out.winner = gd > 0 ? 'L' : 'R'; out.via = 'G差'; }\n    else if (m.tb && (m.tb.points === 'L' || m.tb.points === 'R')) { out.decided = true; out.winner = m.tb.points; out.via = 'P差'; }\n    else if (m.tb && (m.tb.rep === 'L' || m.tb.rep === 'R')) { out.decided = true; out.winner = m.tb.rep; out.via = '代表戦'; out.need = 'rep'; }\n    else out.need = m.tb && m.tb.pointsTie ? 'rep' : 'points';\n  }\n  if (out.decided) out.score = wL + '-' + wR + (out.via ? '（' + out.via + '）' : '');\n  return out;\n}\n\n/* 進行表に載せる団体戦の情報。showAll=false のときは両チームのオーダーが揃うまで選手名を出さない */\nfunction teamView_(m, byId, cfg, showAll) {\n  var dl = orderDeadline_(m, byId, cfg);\n  var both = !!(m.orderL && m.orderR);\n  /* オーダーの公開：本部が「公開」を押したとき（試合開始のあいさつ）。開始・終了した試合も公開扱い */\n  var open = !!m.pub || m.state === '試合中' || m.state === '終了';\n  var oc = teamOutcome_(m);\n  var nowM = nowMin_();\n  var pairs = [];\n  var i;\n  for (i = 0; i < 3; i++) {\n    pairs.push({\n      l: (showAll || open) && m.orderL ? m.orderL.p[i] : null,\n      r: (showAll || open) && m.orderR ? m.orderR.p[i] : null,\n      w: oc.rows[i].w, g: oc.rows[i].g, kind: oc.rows[i].kind, vac: !!oc.rows[i].vac\n    });\n  }\n  var pending = m.state === '待機' || m.state === '呼出';\n  return {\n    orderL: !!m.orderL, orderR: !!m.orderR, both: both, open: open, pubAt: m.pub ? String(m.pub).slice(11, 16) : '',\n    byL: m.orderL ? m.orderL.by : '', byR: m.orderR ? m.orderR.by : '',\n    deadline: hm_(dl.deadline), gather: hm_(dl.gather),\n    overdue: pending && dl.deadline !== null && nowM !== null && nowM > dl.deadline && !both,\n    pairs: pairs, wL: oc.wL, wR: oc.wR, gd: oc.gd, need: m.state === '終了' ? '' : oc.need, tb: m.tb || {}\n  };\n}\n\nfunction saveOrder_(divCode, matchId, side, pairs, by, allowLocked) {\n  var lock = LockService.getScriptLock();\n  lock.waitLock(20000);\n  try {\n    var ms = loadMatches_(divCode);\n    var byId = {};\n    var i;\n    for (i = 0; i < ms.length; i++) byId[ms[i].id] = ms[i];\n    var m = byId[matchId];\n    if (!m) throw new Error('試合が見つかりません。');\n    if (DIVISIONS[divCode].type !== 'team') throw new Error('団体戦の試合ではありません。');\n    var lid = resolveRef_(m.left, byId, {}, 0);\n    var rid = resolveRef_(m.right, byId, {}, 0);\n    if (!lid || !rid) throw new Error('対戦相手が決まっていません。');\n    if (m.state === '終了') throw new Error('試合は終了しています。');\n    if (!allowLocked) {\n      if (m.state === '試合中') throw new Error('試合が始まっているため変更できません。');\n      if (m.pub) throw new Error('本部がオーダーを公開したため、変更できません。変更は本部へ申し出てください。');\n      /* 提出後の修正は、オーダー提出の締切（1回戦は設定の時刻、2回戦以降は前の試合の終了＋設定の分）まで */\n      var mine = side === 'L' ? m.orderL : m.orderR;\n      if (mine) {\n        var dl = orderDeadline_(m, byId, getConfig_());\n        var nowM = nowMin_();\n        if (dl.deadline !== null && nowM !== null && nowM > dl.deadline) throw new Error('オーダー提出の締切（' + hm_(dl.deadline) + '）を過ぎたため、修正できません。変更は本部へ申し出てください。');\n      }\n    }\n    var entry = entryById_(side === 'L' ? lid : rid);\n    var order = normalizeOrder_(entry, pairs);\n    var hit = matchRow_(matchId);\n    var upd = { '更新日時': now_() };\n    upd[side === 'L' ? 'オーダー左' : 'オーダー右'] = JSON.stringify({ p: order, at: now_(), by: by });\n    writeRow_(hit.t, hit.row, upd);\n    log_('オーダー', DIVISIONS[divCode].name + '／第' + m.no + '試合／' + entry['チーム名'] + '（' + by + '）');\n    return order;\n  } finally {\n    lock.releaseLock();\n  }\n}\n\n/* 監督ポータルから提出 */\nfunction apiSubmitOrder_(body) {\n  var entry = findEntryByToken_(body.t);\n  if (!entry) return { status: 'error', message: 'リンクが無効です。' };\n  if (DIVISIONS[entry['区分']].type !== 'team') return { status: 'error', message: '団体戦のリンクではありません。' };\n  if (entry['受付状態'] !== '受付済') return { status: 'error', message: '当日受付が済んでいません。受付を済ませてからオーダーを提出してください。' };\n  var ms = loadMatches_(entry['区分']);\n  var byId = {};\n  var i, side = '';\n  for (i = 0; i < ms.length; i++) byId[ms[i].id] = ms[i];\n  var m = byId[body.matchId];\n  if (!m) return { status: 'error', message: '試合が見つかりません。' };\n  if (resolveRef_(m.left, byId, {}, 0) === entry.entryId) side = 'L';\n  else if (resolveRef_(m.right, byId, {}, 0) === entry.entryId) side = 'R';\n  if (!side) return { status: 'error', message: 'このチームの試合ではありません。' };\n  saveOrder_(entry['区分'], m.id, side, body.pairs, '監督', false);\n  return portalData_(body.t);\n}\n\n/* 本部の代理入力（そろった後の訂正も可） */\nfunction ctlOrder_(body) {\n  saveOrder_(body.div, body.matchId, body.side === 'R' ? 'R' : 'L', body.pairs, '本部', true);\n  return progressData_(body.div, true);\n}\n\n/* 本部：マッチごとの結果（勝者・ゲーム数）と同数時の判定（シートの列名は「番手」のまま） */\nfunction ctlPairs_(body) {\n  var lock = LockService.getScriptLock();\n  lock.waitLock(20000);\n  try {\n    var ms = loadMatches_(body.div);\n    var byId = {};\n    var i;\n    for (i = 0; i < ms.length; i++) byId[ms[i].id] = ms[i];\n    var m = byId[body.matchId];\n    if (!m) throw new Error('試合が見つかりません。');\n    if (DIVISIONS[body.div].type !== 'team') throw new Error('団体戦の試合ではありません。');\n    if (!resolveRef_(m.left, byId, {}, 0) || !resolveRef_(m.right, byId, {}, 0)) throw new Error('対戦相手が決まっていません。');\n    var pairs = [];\n    var p, g;\n    for (i = 0; i < 3; i++) {\n      p = (body.pairs || [])[i] || {};\n      g = String(p.g || '').trim().replace(/[ＲｒＲr]/g, 'R');\n      if (p.w !== 'L' && p.w !== 'R') { pairs.push({}); continue; }\n      if (g && g !== '不戦勝' && !/^\\d+-\\d+$/.test(g) && !/^(\\d+-R|R-\\d+)$/.test(g)) throw new Error('第' + (i + 1) + 'マッチのゲーム数が正しくありません。');\n      pairs.push({ w: p.w, g: g });\n    }\n    var tb = body.tb || {};\n    m.pairs = pairs;\n    m.tb = { points: tb.points || '', rep: tb.rep || '', pointsTie: !!tb.pointsTie };\n    var oc = teamOutcome_(m);\n    var stamp = now_();\n    var upd = { '番手': JSON.stringify(pairs), '判定': JSON.stringify(m.tb), '更新日時': stamp };\n    var any = false;\n    for (i = 0; i < 3; i++) if (pairs[i].w) any = true;\n    if (oc.decided) {\n      if (m.state === '終了' && m.winner !== oc.winner) assertNoDependentsStarted_(m, ms);\n      upd['状態'] = '終了';\n      upd['勝者'] = oc.winner;\n      upd['スコア'] = oc.score;\n      if (!m.start) upd['開始'] = stamp;\n      if (m.state !== '終了' || !m.end) upd['終了'] = stamp;\n    } else {\n      if (m.state === '終了') assertNoDependentsStarted_(m, ms);\n      upd['勝者'] = '';\n      upd['スコア'] = '';\n      upd['終了'] = '';\n      if (any) { upd['状態'] = '試合中'; if (!m.start) upd['開始'] = stamp; }\n    }\n    var hit = matchRow_(m.id);\n    writeRow_(hit.t, hit.row, upd);\n  } finally {\n    lock.releaseLock();\n  }\n  return progressData_(body.div, true);\n}\n\n/* ============================================================\n   監督ポータル（申込リンクのトークンで表示）\n   ============================================================ */\nfunction portalData_(token) {\n  var entry = findEntryByToken_(token);\n  if (!entry) return { status: 'error', message: 'リンクが無効です。受付票のボタンから開いてください。' };\n  var div = DIVISIONS[entry['区分']];\n  if (div.type !== 'team') return { status: 'error', message: 'オーダー提出は団体戦のみです。' };\n  var cfg = getConfig_();\n  var ms = loadMatches_(entry['区分']);\n  var people = participants_(entry['区分']);\n  var byId = {};\n  var i;\n  for (i = 0; i < ms.length; i++) byId[ms[i].id] = ms[i];\n  var est = computeTimes_(ms, div, cfg);\n  var me = entry.entryId;\n  var mine = [];\n  var appears = false;\n  var m, l, r;\n  for (i = 0; i < ms.length; i++) {\n    m = ms[i];\n    if (m.left === 'E:' + me || m.right === 'E:' + me) appears = true;\n    l = resolveRef_(m.left, byId, {}, 0);\n    r = resolveRef_(m.right, byId, {}, 0);\n    if (l === me || r === me) mine.push({ m: m, side: l === me ? 'L' : 'R', opp: l === me ? r : l, oppRef: l === me ? m.right : m.left });\n  }\n  var res = {\n    status: 'ok', tournament: cfg['大会名'], division: div.name, date: cfg['団体戦日程'],\n    venue: div.gender === '男' ? cfg['男子会場'] : cfg['女子会場'],\n    team: { name: entry['チーム名'], abbr: teamShort_(entry), coach: entry['監督氏名'] },\n    reception: entry['受付状態'] === '受付済', players: teamPlayers_(entry),\n    history: [], view: '', match: null, now: hm_(nowMin_()),\n    divCode: entry['区分'], changeOpen: changePeriod_(cfg, div).open\n  };\n  /* 審判の担当（未終了の試合のうち、このチームが審判をするもの） */\n  var refs = refereeMap_(ms, div, byId, {}, loadDraw_(entry['区分']));\n  res.refDuties = [];\n  for (i = 0; i < ms.length; i++) {\n    var rfm = refs[ms[i].id];\n    if (ms[i].state === '終了' || !rfm || (rfm.id !== me && !(rfm.ids && rfm.ids.indexOf(me) >= 0))) continue;\n    var partner = rfm.ids ? (rfm.ids[0] === me ? rfm.ids[1] : rfm.ids[0]) : null;\n    res.refDuties.push({ no: ms[i].no, round: ms[i].round, court: ms[i].two ? 'A・B' : ms[i].court, plan: hm_((est[ms[i].id] || {}).start), state: ms[i].state,\n      after: rfm.after || null, partner: partner && people[partner] ? people[partner].label : '' });\n  }\n  var current = null;\n  var k;\n  for (k = 0; k < mine.length; k++) {\n    var x = mine[k];\n    if (x.m.state === '終了') {\n      if (x.m.note !== '不戦勝' || x.m.winner) {\n        res.history.push({ no: x.m.no, round: x.m.round, opp: x.opp && people[x.opp] ? people[x.opp].label : '不戦勝', win: x.m.winner === x.side,\n          score: x.m.score ? (x.side === 'L' ? x.m.score : flipScore_(x.m.score)) : '' });\n      }\n    } else if (!current) {\n      current = x;\n    }\n  }\n  if (!appears && !mine.length) { res.view = 'nodraw'; return res; }\n  if (!current) {\n    var last = mine.length ? mine[mine.length - 1] : null;\n    res.view = last && last.m.winner === last.side && last.m.stage === 'F' ? 'champion' : 'finished';\n    /* 表彰の対象（準決勝で負け＝第3位、決勝で負け＝準優勝、優勝） */\n    if (last && last.m.stage === 'F') res.award = last.m.winner === last.side ? '優勝' : '準優勝';\n    else if (last && last.m.stage === 'SF' && last.m.winner && last.m.winner !== last.side) res.award = '第3位';\n    return res;\n  }\n  var cm = current.m;\n  var dl = orderDeadline_(cm, byId, cfg);\n  var tv = teamView_(cm, byId, cfg, false);\n  var myOrder = current.side === 'L' ? cm.orderL : cm.orderR;\n  var oppOrder = current.side === 'L' ? cm.orderR : cm.orderL;\n  var e = est[cm.id] || {};\n  res.match = {\n    id: cm.id, no: cm.no, round: cm.round, court: cm.two ? 'A・B（2面展開）' : cm.court + 'コート', state: cm.state,\n    plan: hm_(e.start), deadline: hm_(dl.deadline), gather: hm_(dl.gather),\n    deadlinePassed: dl.deadline !== null && nowMin_() > dl.deadline,\n    opp: current.opp && people[current.opp] ? { label: people[current.opp].label, full: people[current.opp].full } : { label: refPlaceholder_(current.oppRef, byId), full: '' },\n    oppDecided: !!current.opp,\n    myOrder: myOrder ? myOrder.p : null, myOrderAt: myOrder ? String(myOrder.at).slice(11, 16) : '', myOrderBy: myOrder ? myOrder.by : '',\n    oppSubmitted: !!oppOrder, published: tv.open, pubAt: tv.pubAt,\n    oppOrder: tv.open && oppOrder ? oppOrder.p : null,\n    pairs: tv.pairs, side: current.side,\n    queue: courtQueue_(cm, ms, est)\n  };\n  var prev = null;\n  for (k = mine.length - 1; k >= 0; k--) {\n    var o = mine[k].side === 'L' ? mine[k].m.orderL : mine[k].m.orderR;\n    if (o && mine[k].m.id !== cm.id) { prev = o.p; break; }\n  }\n  res.prevOrder = prev;\n  if (!res.reception) res.view = 'reception';\n  else if (!current.opp) res.view = 'waiting';\n  else if (cm.state === '試合中') res.view = 'playing';\n  else if (tv.open) res.view = 'locked';\n  else res.view = 'order';\n  return res;\n}\n\n/* 監督ポータル用：この試合のコートの様子（いま試合中の試合と、この試合の前に残っている試合の数）\n   2面展開の試合は、A・Bどちらかのコートの試合を数える */\nfunction courtQueue_(cm, ms, est) {\n  if (cm.state === '試合中' || cm.state === '終了') return null;\n  var courts = cm.two ? ['A', 'B'] : [cm.court];\n  var mine = est[cm.id] || {};\n  var live = [];\n  var ahead = 0;\n  var i, x, ex, on;\n  for (i = 0; i < ms.length; i++) {\n    x = ms[i];\n    if (x.id === cm.id || x.state === '終了') continue;\n    on = x.two || courts.indexOf(x.court) >= 0;\n    if (!on) continue;\n    if (x.state === '試合中') { live.push({ no: x.no, court: x.two ? 'A・B' : x.court }); ahead++; continue; }\n    ex = est[x.id] || {};\n    if (ex.start === null || ex.start === undefined || mine.start === null || mine.start === undefined) continue;\n    if (ex.start < mine.start || (ex.start === mine.start && x.seq < cm.seq)) ahead++;\n  }\n  return { live: live, ahead: ahead };\n}\n\n/* 受付票用：このチーム（個人戦はこのチームが申し込んだペア）の表彰（第3位・準優勝・優勝） */\nfunction awardsFor_(entry) {\n  var divCode = entry['区分'];\n  var div = DIVISIONS[divCode];\n  var ids = {};\n  var i, r;\n  if (div.type === 'team') ids[entry.entryId] = true;\n  else {\n    var pt = table_(SHEET_PAIR);\n    for (i = 0; i < pt.rows.length; i++) {\n      r = pt.rows[i];\n      if (r['区分'] === divCode && r['支払チーム'] === entry['チーム名']) ids[r.pairId] = true;\n    }\n  }\n  var ms = loadMatches_(divCode);\n  if (!ms.length) return [];\n  var byId = {};\n  for (i = 0; i < ms.length; i++) byId[ms[i].id] = ms[i];\n  var ranks = div.type === 'indiv' ? loadRanks_(divCode) : {};\n  var people = participants_(divCode);\n  var out = [];\n  var m, l, rr, win, lose;\n  for (i = 0; i < ms.length; i++) {\n    m = ms[i];\n    if ((m.stage !== 'SF' && m.stage !== 'F') || m.state !== '終了' || !m.winner) continue;\n    l = resolveRef_(m.left, byId, ranks, 0);\n    rr = resolveRef_(m.right, byId, ranks, 0);\n    win = m.winner === 'L' ? l : rr;\n    lose = m.winner === 'L' ? rr : l;\n    if (m.stage === 'F') {\n      if (win && ids[win]) out.push({ ord: 1, place: '優勝', id: win });\n      if (lose && ids[lose]) out.push({ ord: 2, place: '準優勝', id: lose });\n    } else if (lose && ids[lose]) out.push({ ord: 3, place: '第3位', id: lose });\n  }\n  out.sort(function (a, b) { return a.ord - b.ord; });\n  return out.map(function (x) { return { place: x.place, label: people[x.id] ? people[x.id].label : '' }; });\n}\n\nfunction flipScore_(s) {\n  var m = String(s).match(/^(\\d+|R)-(\\d+|R)(.*)$/);\n  return m ? m[2] + '-' + m[1] + m[3] : s;\n}\n\n/* ============================================================\n   大会プログラム用データ（公開）\n   組合せ・進行表は progress を区分ごとに読む。ここでは名簿・変更・役員・栄光の記録を返す\n   監督（ベンチ入り指導者）の氏名は申込フォームの同意の範囲で出す（役職・連絡先は出さない）\n   ============================================================ */\nfunction sheetRows_(name) {\n  var sh = ss_().getSheetByName(name);\n  if (!sh || sh.getLastRow() < 2) return [];\n  var t = table_(name);\n  var out = [];\n  var i, k, o, any;\n  for (i = 0; i < t.rows.length; i++) {\n    o = {};\n    any = false;\n    for (k = 0; k < t.headers.length; k++) { o[t.headers[k]] = t.rows[i][t.headers[k]]; if (String(o[t.headers[k]]).trim()) any = true; }\n    if (any) out.push(o);\n  }\n  return out;\n}\n\nfunction programData_(preview) {\n  var cfg = getConfig_();\n  var res = {\n    status: 'ok',\n    info: { tournament: cfg['大会名'], indivDate: cfg['個人戦日程'], teamDate: cfg['団体戦日程'], venueM: cfg['男子会場'], venueW: cfg['女子会場'],\n      open: cfg['開場時刻'], reception: cfg['受付時刻'], start: cfg['競技開始時刻'], site: siteUrl_(cfg) },\n    teams: {}, pairs: {}, changes: publicChanges_(''), officials: sheetRows_(SHEET_OFFICIAL), history: sheetRows_(SHEET_HISTORY)\n  };\n  var dt = table_(SHEET_DRAW);\n  var slotOf = {};\n  var i, r;\n  /* 組合せ番号は、公開した区分（試合がある区分）だけ。プレビューでは保存済みの案も出す */\n  var published = {};\n  var mt = table_(SHEET_MATCH);\n  for (i = 0; i < mt.rows.length; i++) published[mt.rows[i]['区分']] = true;\n  for (i = 0; i < dt.rows.length; i++) {\n    if (!preview && !published[dt.rows[i]['区分']]) continue;\n    slotOf[dt.rows[i]['区分'] + '|' + dt.rows[i]['対象ID']] = String(dt.rows[i]['枠']);\n  }\n  if (preview) res.preview = true;\n  var et = table_(SHEET_ENTRY);\n  for (i = 0; i < et.rows.length; i++) {\n    r = et.rows[i];\n    if (!DIVISIONS[r['区分']] || DIVISIONS[r['区分']].type !== 'team') continue;\n    if (!res.teams[r['区分']]) res.teams[r['区分']] = [];\n    var ps = parseJson_(r['選手JSON'], []);\n    var players = [];\n    var j;\n    for (j = 0; j < 8; j++) {\n      var p = ps[j];\n      if (!p) { players.push({ no: j + 1, vacant: true }); continue; }\n      players.push({ no: j + 1, name: p.vacant ? '' : p.name, grade: p.vacant ? '' : p.grade, vacant: !!p.vacant, changedFrom: p.changedFrom || '' });\n    }\n    res.teams[r['区分']].push({ id: r.entryId, name: r['チーム名'], abbr: teamShort_(r), district: districtName_(r['地区']), applied: r['状態'] === '申込済',\n      slot: slotOf[r['区分'] + '|' + r.entryId] || '', players: players, coach: r['監督氏名'] || '' });\n  }\n  var codes = ['MI', 'WI'];\n  var c;\n  for (c = 0; c < codes.length; c++) {\n    var people = participants_(codes[c]);\n    var pt = table_(SHEET_PAIR);\n    res.pairs[codes[c]] = [];\n    for (i = 0; i < pt.rows.length; i++) {\n      r = pt.rows[i];\n      if (r['区分'] !== codes[c]) continue;\n      var pp = people[r.pairId] || {};\n      var ch = parseJson_(r['変更記録'], null);\n      res.pairs[codes[c]].push({ id: r.pairId, slot: slotOf[codes[c] + '|' + r.pairId] || '',\n        a: { name: r['A氏名'], grade: r['A学年'], team: r['A所属'], abbr: (pp.teams || [])[0] || '' },\n        b: { name: r['B氏名'], grade: r['B学年'], team: r['B所属'], abbr: (pp.teams || [])[1] || '' },\n        change: ch ? { side: ch.side, from: ch.from } : null, coach: r['監督氏名'] || '' });\n    }\n  }\n  return res;\n}\n\n/* ============================================================\n   プレビュー（非公開）：保存済みの組合せ案から、進行表を作成したときと同じ形のデータを\n   その場で組み立てて返す。シートには何も書かない。委員長と組合せ係だけが使える\n   ============================================================ */\nfunction previewMatches_(divCode) {\n  var div = DIVISIONS[divCode];\n  var draw = loadDraw_(divCode);\n  var tm = div.type === 'team' ? teamTemplate_(divCode, draw) : indivTemplate_(divCode, draw);\n  var out = [];\n  var i, m;\n  for (i = 0; i < tm.length; i++) {\n    m = tm[i];\n    out.push({ id: m.id, stage: m.stage, round: m.round, no: m.no, left: m.left, right: m.right, court: m.court, seq: m.seq, two: !!m.two,\n      state: m.state || '待機', start: '', end: '', winner: m.winner || '', score: m.score || '', note: m.note || '',\n      orderL: null, orderR: null, pairs: [], tb: {}, pub: '' });\n  }\n  out.sort(function (a, b) { return a.seq - b.seq || a.no - b.no; });\n  return out;\n}\n\nfunction previewRoute_(body) {\n  if (body.action === 'adminPreviewProgram') return programData_(true);\n  var div = DIVISIONS[body.div];\n  if (!div) throw new Error('区分を指定してください。');\n  var draw = loadDraw_(body.div);\n  var k, n = 0;\n  for (k in draw) if (draw.hasOwnProperty(k) && draw[k]) n++;\n  var res = progressData_(body.div, false, n ? previewMatches_(body.div) : []);\n  res.preview = true;\n  res.drawCount = n;\n  return res;\n}\n";
